Object.assign(window.TEM8_DICTIONARY, {"fighting":{"oxford":{"phon":"ˈfaɪtɪŋ","pos":"noun","senses":[{"en":"the activity of being involved in a battle against an enemy","cn":"战斗；作战","ex":{"en":"Fighting broke out in three districts of the city last night.","cn":"昨晚城中有三个区爆发了战斗。"}},{"en":"a physical struggle with somebody","cn":"搏斗；打斗；打架","ex":{"en":"outbreaks of street fighting","cn":"街头斗殴的爆发"}},{"en":"an argument or arguments with somebody about something","cn":"争执；争吵","ex":{"en":"He hated all the fighting at home.","cn":"他十分厌烦家里无休止的争吵。"}},{"en":"the activity of trying very hard to get something or achieve something","cn":"努力争取；斗争","ex":{"en":"years of fighting against the policy","cn":"对政策的多年抗争"}},{"en":"the activity of taking part in a boxing match","cn":"拳击（运动）","ex":{"en":"prize fighting (= matches for money)","cn":"职业拳击"}}]},"media":{"uk":"media/uk/fighting__gb_1.mp3","us":"media/us/fighting__us_1.mp3"},"examples":[{"en":"Fighting broke out in three districts of the city last night.","cn":"昨夜这座城市有三个区发生了战斗。"},{"en":"outbreaks of street fighting","cn":"巷战的爆发"}],"base":"fight"},"fifty":{"media":{"uk":"media/uk/fifty__gb_1.mp3","us":"media/us/fifty__us_1.mp3"},"oxford":{"phon":"ˈfɪfti","pos":"","senses":[{"en":"50","cn":"五十"},{"en":"numbers, years or temperatures from 50 to 59","cn":"五十几；五十年代","g":"[plural]","ex":{"en":"She was born in the fifties.","cn":"她是五十年代出生的。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 50","en":"Fifty is the number 50."},{"pos":"N-PLURAL 复数名词","cn":"五十几(指 50 到 59 之间的数字)","en":"When you talk about the fifties, you are referring to numbers between 50 and 59. For example, if you are in your fifties, you are aged between 50 and 59. If the temperature is in the fifties, the temperature is between 50 and 59 degrees.","ex":{"en":"I probably look as if I'm in my fifties rather than my seventies.","cn":"我大概看上去像 50 多岁而不是 70 多岁。"}},{"pos":"N-PLURAL 复数名词","cn":"二十世纪五十年代","en":"The fifties is the decade between 1950 and 1959.","ex":{"en":"He began performing in the early fifties.","cn":"他20世纪50年代初开始从事表演。"}}]},"examples":[{"en":"He retired in his fifties.","cn":"他在五十多岁时退休了。"},{"en":"She was born in the fifties.","cn":"她是五十年代出生的。"}]},"firmly":{"media":{"uk":"media/uk/firmly__gb_1.mp3","us":"media/us/firmly__us_1.mp3"},"oxford":{"phon":"ˈfɜːmli","pos":"adverb","senses":[{"en":"in a strong or definite way","cn":"坚定地；坚固地","ex":{"en":"‘I can manage,’ she said firmly.","cn":"“我应付得了。”她坚定地说。"}}]},"examples":[{"en":"It is now firmly established as one of the leading brands in the country.","cn":"现在它已稳稳地确立为国内主要品牌之一。"},{"en":"‘I can manage,’ she said firmly. “","cn":"我应付得了。”她坚定地说。"}]},"filtered":{"lemma":"filter","media":{"img":["media/pic/filter_comp.jpg","media/thumb/filter.jpg"],"uk":"media/uk/filter__gb_1.mp3","us":"media/us/filter__us_1.mp3"}},"fiction":{"media":{"uk":"media/uk/fiction__gb_1.mp3","us":"media/us/fiction__us_1.mp3"},"oxford":{"phon":"ˈfɪkʃn","pos":"noun","senses":[{"en":"a type of literature that describes imaginary people and events, not real ones","cn":"小说","g":"[uncountable]","lab":"US English","ex":{"en":"a work of popular fiction","cn":"通俗小说作品"}},{"en":"a thing that is invented or imagined and is not true","cn":"虚构的事；假想之物","g":"[uncountable, countable]","ex":{"en":"Don't believe what she says—it's pure fiction!","cn":"不要相信她说的话 － 纯粹是编的！"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"小说","en":"Fiction refers to books and stories about imaginary people and events, rather than books about real people or events.","ex":{"en":"Immigrant tales have always been popular themes in fiction","cn":"移民故事一直是小说中常见的主题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"虚构;杜撰;编造","en":"A statement or account that is fiction is not true.","ex":{"en":"The truth or fiction of this story has never been truly determined.","cn":"这个故事一直以来真伪莫辨。"}},{"pos":"N-COUNT 可数名词","cn":"虚构之事;幻想","en":"If something is a fiction, it is not true, although people sometimes pretend that it is true.","ex":{"en":"The idea that the United States could harmoniously accommodate all was a fiction.","cn":"认为美国可以接纳所有的人，使之和谐相处是一个幻想。"}}]},"examples":[{"en":"For years he managed to keep up the fiction that he was not married.","cn":"多年来他设法一直给人一种未婚的假象。"},{"en":"historical/romantic fiction","cn":"历史/言情小说"}]},"field":{"media":{"uk":"media/uk/field__gb_1.mp3","us":"media/us/field__us_1.mp3","img":["media/ldoce/img/field.jpg"]},"oxford":{"phon":"fiːld","pos":"noun","senses":[{"en":"an area of land in the country used for growing crops or keeping animals in, usually surrounded by a fence, etc.","cn":"田；地；牧场","g":"[countable]","lab":"North American English","sc":"area of land","ex":{"en":"We had to walk across a ploughed field.","cn":"我们得步行穿过犁过的田地。"}},{"en":"an area of land used for the purpose mentioned","cn":"（作某种用途的）场地","g":"[countable]","sc":"area of land","ex":{"en":"a landing field","cn":"降落场"}},{"en":"a large area of land covered with the thing mentioned; an area from which the thing mentioned is obtained","cn":"（覆盖…的或有…的）大片地方","g":"[countable]","sc":"area of land","ex":{"en":"The territory is covered with snow, bare rock and ice fields.","cn":"那个地方被白雪、裸岩和冰原所覆盖。"}},{"en":"an area of land used for playing a sport on","cn":"运动场","g":"[countable]","lab":"British English also","sc":"in sport","ex":{"en":"a football/soccer/sports field","cn":"足球场；体育场"}},{"en":"the team that is trying to catch the ball rather than hit it","cn":"守队","g":"[singular + singular or plural verb]","sc":"in sport","ex":{"en":"He took the ball early and hit it through a gap in the field.","cn":"他很早就接球，将球击入球场的空隙。"}},{"en":"all the people or animals competing in a particular sports event","cn":"（比赛项目的）全体参赛者","g":"[singular + singular or plural verb]","sc":"in sport","ex":{"en":"The strong field includes three world record holders.","cn":"强有力的竞争者中有 3 名世界纪录保持者。"}},{"en":"an area of land where a battle is fought","cn":"战场","g":"[countable, usually singular]","sc":"in war","ex":{"en":"a medal for bravery in the field","cn":"作战英勇奖章"}},{"en":"a particular subject or activity that somebody works in or is interested in","cn":"专业；学科；界；领域","g":"[countable]","sc":"subject/activity","ex":{"en":"Child development is such an interesting field.","cn":"儿童发展是一个非常有趣的领域。"}},{"en":"the fact of people doing practical work or study, rather than working in a library or laboratory","cn":"实地；野外","g":"[countable]","sc":"practical work","ex":{"en":"a field study/experiment","cn":"实地研究/实验"}},{"en":"all the people or products competing in a particular area of business","cn":"行业","g":"[singular + singular or plural verb]","sc":"in business","ex":{"en":"They lead the field in home entertainment systems.","cn":"他们在家庭娱乐设备行业中居领先地位。"}},{"en":"an area within which the force mentioned has an effect","cn":"场","g":"[countable]","sc":"physics","ex":{"en":"the earth’s gravitational field","cn":"地球引力场"}},{"en":"part of a record that is a separate item of data","cn":"字段；信息组；栏","g":"[countable]","sc":"computing","ex":{"en":"You will need to create separate fields for first name, surname and address.","cn":"名字、姓氏和地址要各自编成单独的字段。"}},{"en":"to provide a candidate, speaker, team, etc. to represent you in an election, a competition, etc.","cn":"使参加竞选；使参加比赛","g":"[transitive]","sc":"candidate/team","ex":{"en":"Each of the main parties fielded more than 300 candidates.","cn":"每个主要政党都选派出 300 多个候选人。"},"pos":"verb"},{"en":"to be the person or the team that catches the ball and throws it back after somebody has hit it","cn":"担任守场员；任守方","g":"[intransitive]","sc":"in cricket/baseball","ex":{"en":"He won the toss and chose to field first.","cn":"他在掷硬币时猜中了，选择先作守方。"},"pos":"verb"},{"en":"to catch the ball and throw it back","cn":"接守；接防","g":"[transitive]","sc":"in cricket/baseball","ex":{"en":"He fielded the ball expertly.","cn":"他熟练地接住球，防守成功。"},"pos":"verb"},{"en":"to receive and deal with questions or comments","cn":"处理，应付（问题或意见）","g":"[transitive]","sc":"questions","ex":{"en":"The BBC had to field more than 300 phone calls after last night's programme.","cn":"英国广播公司在昨夜的节目播出以后，不得不答复了 300 多个电话。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地;田;牧场","en":"A field is an area of grass, for example in a park or on a farm. A field is also an area of land on which a crop is grown.","ex":{"en":"...a field of wheat","cn":"麦田"}},{"pos":"N-COUNT 可数名词","cn":"运动场;球场","en":"A sports field is an area of grass where sports are played.","ex":{"en":"...a football field","cn":"足球场"}},{"pos":"N-COUNT 可数名词","cn":"矿产地;矿田","en":"A field is an area of land or sea bed under which large amounts of a particular mineral have been found.","ex":{"en":"...an extensive natural gas field in Alaska.","cn":"阿拉斯加一个巨大的天然气田"}},{"pos":"N-COUNT 可数名词","cn":"(磁、引力或电)场","en":"A magnetic, gravitational, or electric field is the area in which that particular force is strong enough to have an effect.","ex":{"en":"Some people are worried that electromagnetic fields from electric power lines could increase the risk of cancer.","cn":"有些人担心输电线的电磁场可能增加致癌几率。"}},{"pos":"N-COUNT 可数名词","cn":"专业;学科;领域","en":"A particular field is a particular subject of study or type of activity.","ex":{"en":"Exciting artistic breakthroughs have recently occurred in the fields of painting, sculpture and architecture","cn":"绘画、雕塑和建筑领域最近出现了激动人心的艺术突破。"}},{"pos":"N-COUNT 可数名词","cn":"字段;信息组;栏","en":"A field is an area of a computer's memory or a program where data can be entered, edited, or stored.","ex":{"en":"Go to a site like Yahoo! Finance and enter 'AOL' in the Get Quotes field.","cn":"登录诸如“雅虎财经”这样的站点，在“股票行情”栏输入“美国在线”。"}},{"pos":"N-COUNT 可数名词","cn":"战场;战地","en":"You can refer to the area where fighting or other military action in a war takes place as the field or the field of battle .","ex":{"en":"We never defeated them on the field of battle.","cn":"我们从未在战场上打败过他们。"}},{"pos":"N-COUNT 可数名词","cn":"视野;视域","en":"Your field of vision or your visual field is the area that you can see without turning your head.","ex":{"en":"Our field of vision is surprisingly wide.","cn":"我们的视野出人意料地开阔。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(体育比赛的)所有参赛者，出场阵容","en":"The field is a way of referring to all the competitors taking part in a particular race or sports contest.","ex":{"en":"Going into the fourth lap, the two most broadly experienced riders led the field","cn":"进入第四圈时，两名身经百战的骑手开始领先。"}},{"pos":"ADJ 形容词","cn":"实地;野外","en":"You use field to describe work or study that is done in a real, natural environment rather than in a theoretical way or in controlled conditions.","ex":{"en":"I also conducted a field study among the boys about their attitude to relationships","cn":"我还对男孩子们进行了一项有关两性关系态度的实地调查。"}},{"pos":"VERB 动词","cn":"(在板球、棒球或圆场棒球中)防守，担任守队","en":"In a game of cricket, baseball, or rounders, the team that is fielding is trying to catch the ball, while the other team is trying to hit it.","ex":{"en":"When we are fielding, the umpires keep looking at the ball.","cn":"我们防守的时候，裁判们一直看着球。"}},{"pos":"VERB 动词","cn":"(通常成功地)回答，处理(问题)","en":"If you say that someone fields a question, you mean that they answer it or deal with it, usually successfully.","ex":{"en":"He was later shown on television, fielding questions.","cn":"他后来出现在电视上，答复问题。"}},{"pos":"VERB 动词","cn":"使…出场;让…参加比赛","en":"If a sports team fields a particular number or type of players, the players are chosen to play for the team on a particular occasion.","ex":{"en":"England intend fielding their strongest team in next month's World Youth Championship.","cn":"英格兰意欲在下月的世界青年锦标赛中推出他们的最强阵容。"}},{"pos":"VERB 动词","cn":"让…参加竞选;让…作竞选候选人","en":"If a candidate in an election is representing a political party, you can say that the party is fielding that candidate.","ex":{"en":"There are signs that the new party aims to field candidates in elections scheduled for February next year.","cn":"有迹象表明新党意欲推举候选人参加定于明年 2 月举行的选举。"}},{"pos":"PHRASE 短语","cn":"纵情享受;肆意地做;尽情地做","en":"If someone is having a field day, they are very busy doing something that they enjoy, even though it may be hurtful for other people.","ex":{"en":"In our absence the office gossips are probably having a field day","cn":"我们不在的时候，办公室里大概谣言四起了吧。"}},{"pos":"PHRASE 短语","cn":"在实地;在野外","en":"Work or study that is done in the field is done in a real, natural environment rather than in a theoretical way or in controlled conditions.","ex":{"en":"The zoo is doing major conservation work, both in captivity and in the field.","cn":"无论在圈养场还是在野外，动物园在动物保护方面都承担了主要的工作。"}},{"pos":"PHRASE 短语","cn":"领先;带头","en":"If you say that someone leads the field in a particular activity, you mean that they are better, more active, or more successful than everyone else who is involved in it.","ex":{"en":"When it comes to picking up awards they lead the field by miles.","cn":"他们在拿奖方面遥遥领先。"}},{"pos":"PHRASE 短语","cn":"到处拈花惹草;滥交","en":"If someone plays the field, they have a number of different romantic or sexual relationships.","ex":{"en":"He gave up playing the field and married a year ago.","cn":"他不再处处留情，一年前结了婚。"}}]},"examples":[{"en":"The BBC had to field more than 300 phone calls after last night's programme.","cn":"英国广播公司在昨夜的节目播出以后，不得不答复了 300 多次电话。"},{"en":"Each of the main parties fielded more than 300 candidates.","cn":"每个主要政党都选派出 300 多名候选人。"}]},"fifth":{"media":{"uk":"media/uk/fifth__gb_1.mp3","us":"media/us/fifth__us_1.mp3"},"oxford":{"phon":"fɪfθ","pos":"ordinal number","senses":[{"en":"5th","cn":"第五","ex":{"en":"Today is the fifth (of May).","cn":"今天是（五月）五号。"}},{"en":"each of five equal parts of something","cn":"五分之一","ex":{"en":"She cut the cake into fifths.","cn":"她把蛋糕切成五块。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第五","en":"The fifth item in a series is the one that you count as number five.","ex":{"en":"Joe has recently returned from his fifth trip to Australia.","cn":"乔最近结束了第五次澳大利亚之行归来。"}},{"pos":"FRACTION 分数词","cn":"五分之一","en":"A fifth is one of five equal parts of something.","ex":{"en":"India spends over a fifth of its budget on defence.","cn":"印度的国防开支占了其财政预算的 1/5 强。"}}]},"examples":[{"en":"Her mother had just given birth to another child, her fifth.","cn":"她的母亲刚又生了孩子，她的第五个孩子。"},{"en":"He gave her a fifth of the total amount.","cn":"他给了她总数的五分之一。"}]},"fittings":{"lemma":"fit"},"filmed":{"lemma":"film","media":{"uk":"media/uk/film__gb_1.mp3","us":"media/us/film__us_1.mp3"}},"fitted":{"media":{"uk":"media/uk/fitted__gb_1.mp3","us":"media/us/fitted__us_1.mp3"},"oxford":{"phon":"ˈfɪtɪd","pos":"adjective","senses":[{"en":"built to be fixed into a particular space","cn":"（按放置的地方）定做的","g":"[only before noun]","lab":"especially British English","ex":{"en":"fitted wardrobes/cupboards","cn":"定制衣橱／橱柜"}},{"en":"with matching cupboards and other furniture built for the space and fixed in place","cn":"有定做配套家具的","g":"[only before noun]","lab":"especially British English","ex":{"en":"a fitted kitchen/bedroom","cn":"整体厨房／卧室"}},{"en":"made to follow the shape of the body","cn":"定做的；合身的","g":"[only before noun]","ex":{"en":"a fitted jacket","cn":"合身的短外套"}},{"en":"suitable; with the right qualities and skills","cn":"合适的；恰当的；胜任的","lab":"especially British English","ex":{"en":"She was well fitted to the role of tragic heroine.","cn":"她很适合演悲剧女主角。"}},{"en":"having something as equipment","cn":"有…设备的","ex":{"en":"Insurance costs will be reduced for houses fitted with window locks.","cn":"窗户有锁的房子保险费用降低。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"紧身的;收身的;合身的","en":"A fitted piece of clothing is designed so that it is the same size and shape as your body rather than being loose.","ex":{"en":"...baggy trousers with fitted jackets.","cn":"宽松的裤子配上紧身夹克"}},{"pos":"ADJ 形容词","cn":"(家具)定做的，配制的","en":"A fitted piece of furniture, for example a cupboard, is designed to fill a particular space and is fixed in place.","ex":{"en":"I've re-carpeted our bedroom and added fitted wardrobes.","cn":"我重铺了卧室的地毯，又添置了定做的壁橱。"}},{"pos":"ADJ 形容词","cn":"(地毯)铺满房间的，定做的，大小合适的","en":"A fitted carpet is cut to the same shape as a room so that it covers the floor completely.","ex":{"en":"...fitted carpets, central heating and double glazing.","cn":"定制的地毯、中央供暖和双层玻璃窗"}},{"pos":"ADJ 形容词","cn":"(床单)大小合适的，按尺寸缝边的","en":"A fitted sheet has the corners sewn so that they fit over the corners of the mattress and do not have to be folded."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合适的;有能力的;胜任的","en":"A person who is fitted to do something or fitted for something has the right qualities for it.","ex":{"en":"Helen was ill fitted to fulfil her daughter's ideal of a gentle mother-figure.","cn":"海伦与她女儿理想中的温柔母亲形象相差甚远。"}},{"pos":"ADJ 形容词","cn":"(房间)配有，装有","en":"If a room is fitted with objects, those objects are in the room and are normally fixed in place.","ex":{"en":"Bedrooms are fitted with alarm pull cords to alert the manager in an emergency.","cn":"卧室中装有警报器拉绳，遇到紧急情况时可向经理报警。"}}]},"examples":[{"en":"Insurance costs will be reduced for houses fitted with window locks.","cn":"窗户有锁的房子保险费用降低。"},{"en":"She was well fitted to the role of tragic heroine.","cn":"她很适合演悲剧女主角。"}],"base":"fit"},"fixed":{"oxford":{"phon":"fɪkst","pos":"adjective","senses":[{"en":"staying the same; not changing or able to be changed","cn":"固定的；不变的；不能变的","ex":{"en":"These fixed prices give farmers a degree of financial security.","cn":"这些固定价格为农民提供了一定程度的财务保障。"}},{"en":"held very strongly; not easily changed","cn":"不易改变的；执着的","lab":"often disapproving","ex":{"en":"My parents had fixed ideas about what I should become.","cn":"父母对我应该成为什么样的人有定见。"}},{"en":"not changing and not sincere","cn":"呆板的；不变的","g":"[only before noun]","ex":{"en":"He greeted all his guests with a fixed smile on his face.","cn":"他对所有的客人都以一贯的笑脸相迎。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"固定的;不变的","en":"You use fixed to describe something which stays the same and does not or cannot vary.","ex":{"en":"They issue a fixed number of shares that trade publicly","cn":"他们发行一定数量的可公开交易的股票。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观念或看法)顽固的，固执的，一成不变的","en":"If you say that someone has fixed ideas or opinions, you mean that they do not often change their ideas and opinions, although perhaps they should.","ex":{"en":"...people who have fixed ideas about things.","cn":"对事物看法一成不变的人"}},{"pos":"ADJ 形容词","cn":"(笑容)僵硬的，呆板的,皮笑肉不笑的","en":"If someone has a fixed smile on their face, they are smiling even though they do not feel happy or pleased.","ex":{"en":"I had to go through the rest of the evening with a fixed smile on my face.","cn":"晚会剩下的时间里，我只好脸上挂着一副僵硬的笑容。"}},{"pos":"PHRASE 短语","cn":"无固定住所的;居无定所的","en":"Someone who is of no fixed address, or in British English no fixed abode, does not have a permanent place to live.","ex":{"en":"They are not able to get a job interview because they have no fixed address","cn":"因为居无定所，他们无法得到工作面试的机会。"}}]},"media":{"uk":"media/uk/fixed__gb_1.mp3","us":"media/us/fixed__us_1.mp3","img":["media/ldoce/img/fixed.jpg"]},"examples":[{"en":"My parents had fixed ideas about what I should become.","cn":"父母对我应该成为什么样的人有定见。"},{"en":"He greeted all his guests with a fixed smile on his face.","cn":"他对所有的客人都以一贯笑容相迎。"}],"base":"fix"},"file":{"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/file2.jpg"],"uk":"media/uk/file__gb_1.mp3","us":"media/us/file__us_1.mp3"},"oxford":{"phon":"faɪl","pos":"noun","senses":[{"en":"a box or folded piece of card for keeping loose papers together and in order","cn":"文件夹；卷宗","ex":{"en":"a box file","cn":"文件箱"}},{"en":"a collection of information stored together in a computer, under a particular name","cn":"（计算机的）文件","ex":{"en":"to create/delete/download/upload a file","cn":"新建／删除／下载／上传文件"}},{"en":"a file and the information it contains, for example about a particular person or subject","cn":"档案","ex":{"en":"The film is based on real FBI case files.","cn":"这部电影改编自联邦调查局的真实案卷。"}},{"en":"a number of issues and responsibilities connected with a particular government policy area","cn":"（政府负责的）问题，议题","lab":"Canadian English","ex":{"en":"The politician's handling of flood, infrastructure and education files has been questioned.","cn":"这位政治家处理洪水、基础设施和教育档案的方式受到质疑。"}},{"en":"a metal tool with a rough surface for cutting or shaping hard substances or for making them smooth","cn":"锉；锉刀","ex":{"en":"Use a file to smooth the edge.","cn":"使用锉刀平滑边缘。"}},{"en":"a line of people or things, one behind the other","cn":"排成一行的人（或物）","ex":{"en":"They set off in file behind the teacher.","cn":"他们跟在教师后面鱼贯出发。"}},{"en":"to put and keep paper documents in a particular place and in a particular order so that you can find them easily; to put a paper document in a box, file, etc.","cn":"把（文件）归档","g":"[transitive]","ex":{"en":"The forms should be filed alphabetically.","cn":"这些表格应该按字母顺序归档。"},"pos":"verb"},{"en":"to present something so that it can be officially recorded and dealt with","cn":"提起（诉讼）；提出（申请）；送交（备案）","g":"[intransitive, transitive]","lab":"law","ex":{"en":"to file for divorce/bankruptcy","cn":"申请离婚／破产"},"pos":"verb"},{"en":"to send a report or a story to your employer","cn":"发送（报道给报社）","g":"[transitive]","ex":{"en":"Newspaper and television reporters filed dozens of stories from the scene of the fire.","cn":"报纸和电视记者报道了火灾现场的数十篇报道。"},"pos":"verb"},{"en":"to walk in a line of people, one after the other, in a particular direction","cn":"排成一行行走","g":"[intransitive]","ex":{"en":"The doors of the museum opened and the visitors began to file in.","cn":"博物馆开门了，参观者鱼贯而入。"},"pos":"verb"},{"en":"to cut or shape something or make something smooth using a file","cn":"锉平；锉去；锉薄；锉光滑","g":"[transitive]","ex":{"en":"to file your nails","cn":"把指甲锉光滑"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文件箱;文件夹","en":"A file is a box or a folded piece of heavy paper or plastic in which letters or documents are kept.","ex":{"en":"He sat behind a table on which were half a dozen files.","cn":"他坐在一张放有6个文件夹的桌子后面。"}},{"pos":"N-COUNT 可数名词","cn":"档案;卷宗","en":"A file is a collection of information about a particular person or thing.","ex":{"en":"There was stuff in that file that was private between me and Dr Denny","cn":"那份档案的有些内容是只应我和丹尼医生知道的。"}},{"pos":"VERB 动词","cn":"把(文件等）归档","en":"If you file a document, you put it in the correct file.","ex":{"en":"A secretary can file papers as efficiently as a floppy disk can store them","cn":"秘书归档文件时可以像软盘存储一样高效。"}},{"pos":"N-COUNT 可数名词","cn":"(计算机的)文件","en":"In computing, a file is a set of related data that has its own name."},{"pos":"VERB 动词","cn":"提起(诉讼);提出(投诉、请求等)","en":"If you file a formal or legal accusation, complaint, or request, you make it officially.","ex":{"en":"A number of them have filed formal complaints against the police","cn":"他们中的许多人都对警方提出了正式控告。"}},{"pos":"VERB 动词","cn":"发送，送交(新闻报道等)","en":"When someone files a report or a news story, they send or give it to their employer.","ex":{"en":"Catherine Bond filed that report for the BBC from Nairobi","cn":"凯瑟琳·邦德从内罗毕向英国广播公司发送了那篇报道。"}},{"pos":"VERB 动词","cn":"排成纵列行进","en":"When a group of people files somewhere, they walk one behind the other in a line.","ex":{"en":"She paused as the group of children filed out of the house","cn":"那群孩子从房子里鱼贯而出时，她停了下来。"}},{"pos":"N-COUNT 可数名词","cn":"锉刀","en":"A file is a hand tool which is used for rubbing hard objects to make them smooth, shape them, or cut through them."},{"pos":"VERB 动词","cn":"(用锉刀)锉","en":"If you file an object, you smooth it, shape it, or cut it with a file.","ex":{"en":"Manicurists are skilled at shaping and filing nails.","cn":"美甲师修锉指甲的手艺娴熟。"}},{"pos":"PHRASE 短语","cn":"记录(或保存)在档的","en":"Something that is on file or on someone's files is recorded or kept in a file or in a collection of information.","ex":{"en":"His fingerprints were on file in Washington","cn":"他的指纹已在华盛顿记录在档。"}},{"pos":"PHRASE 短语","cn":"成纵队;成单列","en":"A group of people who are walking or standing in single file are in a line, one behind the other.","ex":{"en":"We were walking in single file to the lake.","cn":"我们正排成一列朝湖边走去。"}},{"pos":"PHRASAL VERB 短语动词","cn":"把(文件等)归档","en":"If you file away a document, you put it in the correct file.","ex":{"en":"When at home, most evenings would be spent reading, cutting up and filing away his photographs","cn":"晚上在家时，经常都是在看书或剪切和归类他的照片。"}},{"pos":"","cn":"","en":"相关词组：file away"}]},"examples":[{"en":"Every file on the same disk must have a different name.","cn":"同一磁盘上的每一个文件都必须有不同的文件名。"},{"en":"Police have reopened the file (= have started collecting information again) on the missing girl.","cn":"警方对失踪的女孩已重新建档调查。"}]},"finger":{"media":{"uk":"media/uk/finger__gb_1.mp3","us":"media/us/finger__us_1.mp3","img":["media/ldoce/img/hand.jpg"]},"oxford":{"phon":"ˈfɪŋɡə(r)","pos":"noun","senses":[{"en":"one of the four long thin parts that stick out from the hand (or five, if the thumb is included)","cn":"手指","lab":"informal","ex":{"en":"She ran her fingers through her hair.","cn":"她用手指梳理头发。"}},{"en":"having the type of fingers mentioned; having or using the number of fingers mentioned","cn":"有…手指的（指类型）；有（或用）…手指的（指数目）","ex":{"en":"long-fingered","cn":"长指的"}},{"en":"the part of a glove that covers the finger","cn":"（手套的）指部"},{"en":"a long narrow piece of bread, cake, land, etc.","cn":"狭长物（如面包、糕饼、土地等）","ex":{"en":"chocolate fingers","cn":"巧克力条"}},{"en":"to touch or feel something with your fingers","cn":"用手指触摸","ex":{"en":"Gary sat fingering his beard, saying nothing.","cn":"加里坐着用手捋着胡子，一言不发。"},"pos":"verb"},{"en":"to accuse somebody of doing something illegal and tell the police about it","cn":"告发；告密","lab":"informal, especially North American English，，","ex":{"en":"Who fingered him for the burglaries?","cn":"谁告发他入室盗窃？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(除拇指以外的)手指","en":"Your fingers are the four long thin parts at the end of each hand.","ex":{"en":"She suddenly held up a small, bony finger and pointed across the room","cn":"她突然伸出一根瘦小的手指，指向屋子的另一头。"}},{"pos":"N-COUNT 可数名词","cn":"(手套的)手指部分","en":"The fingers of a glove are the parts that a person's fingers fit into."},{"pos":"N-COUNT 可数名词","cn":"指状物;狭长物","en":"A finger of something such as smoke or land is an amount of it that is shaped rather like a finger.","ex":{"en":"...a thin finger of land that separates Pakistan from the former Soviet Union","cn":"分隔巴基斯坦和苏联的一块狭长地带"}},{"pos":"VERB 动词","cn":"用手指触碰;拨弄;抚摸","en":"If you finger something, you touch or feel it with your fingers.","ex":{"en":"He fingered the few coins in his pocket","cn":"他拨弄着口袋里的几枚硬币。"}},{"pos":"VERB 动词","cn":"(通常指向警方)告发，揭发","en":"If you finger a person or organization, you tell someone, usually the police, that the person or organization has done something illegal or wrong.","ex":{"en":"Police and prosecutors manipulated the eyewitnesses so they would finger Aldo","cn":"警方和检察官操纵目击证人指证奥尔多。"}},{"pos":"N-COUNT 可数名词","cn":"一指之宽(指表示容量的杯中酒的深度)","en":"A finger of a strong alcoholic drink is an amount of it which, when it is in a glass, is the same size as the width of a person's finger.","ex":{"en":"I poured two final fingers of bourbon into my glass.","cn":"我把最后两指宽的波旁威士忌都倒进自己杯中。"}},{"pos":"PHRASE 短语","cn":"(因自己的失败或错误而)吃苦头","en":"If you get your fingers burned or burn your fingers, you suffer because something you did or were involved in was a failure or a mistake.","ex":{"en":"He has had his fingers burnt by deals that turned out badly","cn":"几笔糟糕的生意让他吃了苦头。"}},{"pos":"PHRASE 短语","cn":"(把食指与中指交叉以)祈求好运","en":"If you cross your fingers, you put one finger on top of another and hope for good luck. If you say that someone is keeping their fingers crossed, you mean they are hoping for good luck.","ex":{"en":"He crossed his fingers, asking for luck for the first time in his life","cn":"他交叉手指，生平第一次祈求好运。"}},{"pos":"PHRASE 短语","cn":"动…一根毫毛;碰…一下","en":"If you say that someone did not lay a finger on a particular person or thing, you are emphasizing that they did not touch or harm them at all.","ex":{"en":"I must make it clear I never laid a finger on her.","cn":"我得说清楚，我可没有动过她一根毫毛。"}},{"pos":"PHRASE 短语","cn":"尽举手之劳;帮一点忙","en":"If you say that a person does not lift a finger or raise a finger to do something, especially to help someone, you are critical of them because they do nothing.","ex":{"en":"She never lifted a finger around the house","cn":"家里的活儿她从来一点忙都不帮。"}},{"pos":"PHRASE 短语","cn":"到处插手;四处干预","en":"If you say that someone has a finger in every pie, you mean they are involved in a lot of things.","ex":{"en":"He very much likes to have a finger in every pie","cn":"他很喜欢什么事都插上一杠。"}},{"pos":"PHRASE 短语","cn":"指责;指控","en":"If you point the finger at someone or point an accusing finger at someone, you blame them or accuse them of doing wrong.","ex":{"en":"He said he wasn't pointing an accusing finger at anyone in the government or the army.","cn":"他说他并不是在指责政府或军方的任何人。"}},{"pos":"PHRASE 短语","cn":"将怀疑(或指责)的矛头指(向…)","en":"To point the finger of suspicion or blame at someone means to make people suspect them of doing wrong or blame them for doing wrong.","ex":{"en":"Forensic evidence points the finger of suspicion firmly at him.","cn":"法医的证据将怀疑的矛头明确地指向了他。"}},{"pos":"PHRASE 短语","cn":"(粗鲁地叫别人)赶紧(或努力)干起来","en":"If you tell someone to pull their finger out or to get their finger out, you are telling them rudely that you want them to start doing some work or making an effort.","ex":{"en":"Isn't it about time that you pulled your finger out?","cn":"现在到了你该赶紧动起来的时候了吧？"}},{"pos":"PHRASE短语","cn":"弄清，指出，确认(原因、问题等)","en":"If you put your finger on something, for example a reason or problem, you see and identify exactly what it is.","ex":{"en":"Midge couldn't quite put her finger on the reason","cn":"米吉还不能十分确定原因何在。"}},{"pos":"PHRASE 短语","cn":"从…手中溜走;为…所错失","en":"If someone or something slips through your fingers, you just fail to catch them, get them, or keep them.","ex":{"en":"Money has slipped through his fingers all his life","cn":"他这一辈子都没能抓住金钱。"}},{"pos":"","cn":"","en":"to have green fingers→see: ;"},{"pos":"","cn":"","en":"finger on the pulse→see: ;"}]},"examples":[{"en":"You're going to have to pull your finger out if you want to pass this exam.","cn":"如果你想通过这次考试就得多加把劲。"},{"en":"There was something odd about him but I couldn't put my finger on it.","cn":"他有些古怪，但我说不出到底是什么。"}]},"finish":{"media":{"uk":"media/uk/finish__gb_1.mp3","us":"media/us/finish__us_1.mp3"},"oxford":{"phon":"ˈfɪnɪʃ","pos":"verb","senses":[{"en":"to stop doing something or making something because it is complete","cn":"完成；做好","g":"[transitive, intransitive]","ex":{"en":"Haven't you finished your homework yet?","cn":"难道你还没有完成家庭作业吗？"}},{"en":"to come to an end; to bring something to an end","cn":"（使）结束","g":"[intransitive, transitive]","ex":{"en":"The play finished at 10.30.","cn":"比赛于 10:30 结束。"}},{"en":"to eat, drink or use what remains of something","cn":"吃完，喝光，用尽（所剩之物）","g":"[transitive]","ex":{"en":"I quickly finished my tea.","cn":"我迅速把茶喝完。"}},{"en":"to be in a particular state or position at the end of a race or a competition","cn":"（赛跑、竞赛）得…名；获…成绩","g":"[intransitive, transitive]","ex":{"en":"She was delighted to finish second.","cn":"她为竞赛得了第二名而高兴。"}},{"en":"to make somebody so tired or impatient that they cannot do any more","cn":"使筋疲力尽；使失去耐心","g":"[transitive]","lab":"informal","ex":{"en":"Climbing that hill really finished me off.","cn":"登那座山真把我累得筋疲力尽。"}},{"en":"the last part or the end of something","cn":"最后部分；结尾；结局","g":"[countable, usually singular]","ex":{"en":"It was a close finish as they had predicted.","cn":"正如他们所预料的，比赛结果难分上下。"},"pos":"noun"},{"en":"the position in which a person or team finishes a competition","cn":"名次；排名","g":"[countable, usually singular]","ex":{"en":"a second-/third-/fourth-place finish","cn":"第二名；第三名；第四名"},"pos":"noun"},{"en":"the last layer of paint, polish, etc. that is put onto the surface of something; the condition of the surface","cn":"末道漆；抛光；（漆完抛光后的）成品表面","g":"[countable, uncountable]","ex":{"en":"a gloss/matt finish","cn":"光泽／无光表面"},"pos":"noun"},{"en":"the final details that are added to something to make it complete","cn":"最后精细加工","g":"[countable, uncountable]","ex":{"en":"The bows will give a feminine finish to the curtains.","cn":"窗帘最后配上蝴蝶结显出女性的柔美。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"结束;做毕","en":"When you finish doing or dealing with something, you do or deal with the last part of it, so that there is no more for you to do or deal with.","ex":{"en":"As soon as he'd finished eating, he excused himself","cn":"他一吃完就告辞离开了。"}},{"pos":"VERB 动词","cn":"完成;做成","en":"When you finish something that you are making or producing, you reach the end of making or producing it, so that it is complete.","ex":{"en":"The consultants had been working to finish a report this week.","cn":"顾问们一直在为要于本周内完成一份报告而工作。"}},{"pos":"VERB 动词","cn":"(尤指在预定时间)结束，终结","en":"When something such as a course, film, or sale finishes, especially at a planned time, it ends.","ex":{"en":"The teaching day finishes at around 4pm","cn":"一天的教学在下午4点左右结束。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(以某种方式)(使)结束","en":"You say that someone or something finishes a period of time or an event in a particular way to indicate what the final situation was like. You can also say that a period of time or an event finishes in a particular way.","ex":{"en":"The two of them finished by kissing each other goodbye","cn":"他们两人最后互相吻别。"}},{"pos":"VERB 动词","cn":"获得名次","en":"If someone finishes second, for example, in a race or competition, they are in second place at the end of the race or competition.","ex":{"en":"He finished second in the championship four years in a row.","cn":"他连续4年获得锦标赛亚军。"}},{"pos":"VERB 动词","cn":"说完;讲完","en":"To finish means to reach the end of saying something.","ex":{"en":"Her eyes flashed, but he held up a hand. 'Let me finish.'","cn":"她眼光一闪，但他举起一只手说：“让我把话讲完。”"}},{"pos":"N-SING 单数名词","cn":"结束;最后部分","en":"The finish of something is the end of it or the last part of it.","ex":{"en":"I intend to continue it and see the job through to the finish","cn":"我打算继续下去，直到工作彻底完成。"}},{"pos":"N-COUNT 可数名词","cn":"(比赛的)终结，最后阶段","en":"The finish of a race is the end of it.","ex":{"en":"Win a trip to see the finish of the Tour de France!","cn":"赢得观看环法自行车赛最后阶段比赛之旅！"}},{"pos":"N-COUNT 可数名词","cn":"抛光;成品表面","en":"If the surface of something that has been made has a particular kind of finish, it has the appearance or texture mentioned.","ex":{"en":"The finish and workmanship of the woodwork was excellent.","cn":"这件木工品的抛光和做工均属上乘。"}},{"pos":"PHRASE 短语","cn":"生死决战;誓死之战","en":"A fight to the finish is one in which one of the people or groups fighting is killed or completely defeated.","ex":{"en":"The conflict in the North and East of the island was a fight to the finish.","cn":"该岛北部和东部的冲突是一场你死我活的斗争。"}},{"pos":"PHRASE 短语","cn":"最后润色;最后修饰","en":"If you add the finishing touches to something, you add or do the last things that are necessary to complete it.","ex":{"en":"Right up until the last minute, workers were still putting the finishing touches on the pavilions","cn":"直到最后一刻，工人们仍在对展馆进行最后的修饰。"}},{"pos":"PHRASAL VERB 短语动词","cn":"吃光;喝光","en":"If you finish off something that you have been eating or drinking, you eat or drink the last part of it with the result that there is none left.","ex":{"en":"Kelly finished off his coffee","cn":"凯利喝光了他的咖啡。"}},{"pos":"PHRASAL VERB 短语动词","cn":"杀死(已受严重伤害的人);毁灭(已遭严重损坏的物)","en":"If someone finishes off a person or thing that is already badly injured or damaged, they kill or destroy them. →see: ;","ex":{"en":"They meant to finish her off, swiftly and without mercy.","cn":"他们打算毫不留情地迅速结果了她。"}},{"pos":"PHRASAL VERB 短语动词","cn":"最后(处于某地或某种情形)","en":"If you finish up in a particular place or situation, you are in that place or situation after doing or experiencing several things.","ex":{"en":"They had met by chance at university and finished up getting married","cn":"他们在大学偶遇，最后结了婚。"}},{"pos":"PHRASAL VERB 短语动词","cn":"吃完;喝完","en":"If you finish up something that you have been eating or drinking, you eat or drink the last part of it.","ex":{"en":"Finish up your drinks now, please.","cn":"请现在喝完。"}},{"pos":"PHRASAL VERB 短语动词","cn":"与…断绝关系;对…不再感兴趣;同…不再打交道","en":"If you finish with someone or something, you stop dealing with them, being involved with them, or being interested in them.","ex":{"en":"My boyfriend was threatening to finish with me","cn":"男友威胁说要和我分手。"}},{"pos":"","cn":"","en":"相关词组：finish off finish up finish with"}]},"examples":[{"en":"They finished off the show with one of their most famous songs.","cn":"他们用自己的一首最著名的歌曲作演出的压台戏。"},{"en":"We had a five-course lunch and finished up with coffee and mints.","cn":"我们这顿午餐吃了五道菜，最后是咖啡和薄荷糖。"}]},"fierce":{"media":{"uk":"media/uk/fierce__gb_1.mp3","us":"media/us/fierce__us_1.mp3"},"oxford":{"phon":"fɪəs","pos":"adjective","senses":[{"en":"angry and aggressive in a way that is frightening","cn":"凶猛的；凶狠的；凶残的","ex":{"en":"a fierce dog","cn":"恶狗"}},{"en":"showing strong feelings or a lot of activity, often in a way that is violent","cn":"狂热的；强烈的；猛烈的","ex":{"en":"fierce loyalty","cn":"极度的忠诚"}},{"en":"very strong in a way that could cause damage","cn":"狂暴的；恶劣的","ex":{"en":"fierce wind","cn":"狂风"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凶猛的;狂怒的","en":"A fierce animal or person is very aggressive or angry.","ex":{"en":"They look like the teeth of some fierce animal.","cn":"它们看上去像某种猛兽的牙齿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情或行动)激烈的，狂热的","en":"Fierce feelings or actions are very intense or enthusiastic, or involve great activity.","ex":{"en":"Competition has been fierce to win a stake in Skoda","cn":"争夺斯柯达股份的竞争极为激烈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极度的;巨大的;强烈的","en":"Fierce conditions are very intense, great, or strong.","ex":{"en":"The climbers were trapped by a fierce storm which went on for days.","cn":"登山者被一连几天的强风暴雨给困住了。"}}]},"examples":[{"en":"Competition from abroad became fiercer in the 1990s.","cn":"在 20 世纪 90 年代来自国外的竞争加剧。"},{"en":"Two fierce eyes glared at them.","cn":"一双凶狠的眼睛对着他们怒目而视。"}]},"fists":{"lemma":"fist","media":{"uk":"media/uk/fist__gb_1.mp3","us":"media/us/fist__us_1.mp3"}},"firstly":{"media":{"uk":"media/uk/firstly__gb_1.mp3","us":"media/us/firstly__us_1.mp3"},"oxford":{"phon":"ˈfɜːstli","pos":"adverb","senses":[{"en":"used to introduce the first of a list of points you want to make in a speech or piece of writing","cn":"（用于列举）第一，首先","lab":"British English","ex":{"en":"There are two reasons for this decision: firstly…","cn":"作此决定理由有二：第一…"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"首先;第一","en":"You use firstly in speech or writing when you want to give a reason, make a point, or mention an item that will be followed by others connected with it.","ex":{"en":"The programme is now seven years behind schedule as a result, firstly of increased costs, then of technical problems","cn":"该项目现已经比预定时间晚了7年，原因首先是因为成本增加，其次是由于技术问题。"}}]},"examples":[{"en":"The brochure is divided into two sections, dealing firstly with basic courses and secondly with advanced ones.","cn":"小册子分为两部分：第一部分涉及基础课程，第二部分涉及高阶课程。"},{"en":"Maggie had seen him nearly every day at first. Now she saw him much less.","cn":"起初玛吉几乎每天都见到他，现在见到他的次数少得多了。"}]},"firing":{"oxford":{"phon":"ˈfaɪərɪŋ","pos":"noun","senses":[{"en":"the action of firing guns","cn":"射击；发射；开枪；开炮","g":"[uncountable]","ex":{"en":"There was continuous firing throughout the night.","cn":"整夜枪炮不息。"}},{"en":"the action of forcing somebody to leave their job","cn":"解雇；开除","g":"[uncountable, countable]","ex":{"en":"teachers protesting against the firing of a colleague","cn":"因一位同事被开除而抗议的教师们"}}]},"media":{"uk":"media/uk/firing__gb_1.mp3","us":"media/us/firing__us_1.mp3"},"examples":[{"en":"teachers protesting against the firing of a colleague","cn":"因一位同事被开除而抗议的教师们"},{"en":"She's responsible for the hirings and firings.","cn":"她负责雇用和解雇。"}],"base":"fire"},"film":{"media":{"uk":"media/uk/film__gb_1.mp3","us":"media/us/film__us_1.mp3"},"oxford":{"phon":"fɪlm","pos":"noun","senses":[{"en":"a series of moving pictures recorded with sound that tells a story, watched at a cinema or on a television or other device","cn":"电影；影片","g":"[countable]","lab":"especially British English","sc":"moving pictures","ex":{"en":"Let's stay in and watch a film.","cn":"咱们待在家里看电影吧。"}},{"en":"the art or business of making films","cn":"电影艺术；电影业","g":"[uncountable]","lab":"especially British English","sc":"moving pictures","ex":{"en":"jobs in film and television","cn":"影视行业的工作"}},{"en":"moving pictures of real events, shown for example on television","cn":"新闻片","g":"[uncountable]","sc":"moving pictures","ex":{"en":"television news film of the riots","cn":"这场暴乱的电视新闻片"}},{"en":"thin plastic that is sensitive to light, used especially in the past for taking photographs and making films; a roll of this plastic, used in cameras","cn":"胶片；胶卷；底片","g":"[uncountable, countable]","sc":"in cameras","ex":{"en":"a roll of film","cn":"一卷胶卷"}},{"en":"a thin layer of something, usually on the surface of something else","cn":"薄薄的一层；薄膜","g":"[countable, usually singular]","sc":"thin layer","ex":{"en":"Grease coated everything in a thin film.","cn":"油脂将所有东西都涂上一层薄膜。"}},{"en":"to make a film of a story or a real event; to record somebody/something on film","cn":"拍摄","ex":{"en":"They are filming in Moscow right now.","cn":"目前他们正在莫斯科拍电影。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电影;影片","en":"A film consists of moving pictures that have been recorded so that they can be shown at the cinema or on television. A film tells a story, or shows a real situation.","ex":{"en":"Everything about the film was good. Good acting, good story, good fun.","cn":"这部片子各个方面都很不错：表演出色，故事精彩，情节有趣。"}},{"pos":"VERB 动词","cn":"拍摄;把…拍成电影(或电视)","en":"If you film something, you use a camera to take moving pictures which can be shown on a screen or on television.","ex":{"en":"He had filmed her life story","cn":"他把她一生的经历拍成了电影。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"纪实镜头;记录画面","en":"Film of something is moving pictures of a real event that are shown on television or on a screen.","ex":{"en":"They have seen news film of families queueing in Russia to buy a loaf of bread.","cn":"他们已经看过那段俄罗斯许多家庭为买面包排起长队的新闻画面。"}},{"pos":"N-VAR 可变名词","cn":"胶卷","en":"A film is the narrow roll of plastic that is used in a camera to take photographs.","ex":{"en":"The photographers had already shot a dozen rolls of film.","cn":"摄影师们已经拍光了一打胶卷。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"电影艺术;电影业","en":"The making of cinema films, considered as a form of art or a business, can be referred to as film or films .","ex":{"en":"Film is a business with limited opportunities for actresses","cn":"电影行业对女演员来说机会有限。"}},{"pos":"N-COUNT 可数名词","cn":"薄层","en":"A film of powder, liquid, or oil is a very thin layer of it.","ex":{"en":"The sea is coated with a film of raw sewage.","cn":"海面上漂浮着一层未经处理的污水。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(塑料)薄膜","en":"Plastic film is a very thin sheet of plastic used to wrap and cover things.","ex":{"en":"Cover with plastic film and refrigerate for 24 hours.","cn":"覆上保鲜膜，冷藏 24 小时。"}}]},"examples":[{"en":"Two young boys were filmed stealing CDs on the security video.","cn":"两个少年偷唱片时被保安录像机拍摄了下来。"},{"en":"Let's go to the cinema — there's a good film on this week.","cn":"咱们去看电影吧，本周在上映一部好片子。"}]},"fit":{"media":{"uk":"media/uk/fit__gb_1.mp3","us":"media/us/fit__us_1.mp3"},"oxford":{"phon":"fɪt","pos":"verb","senses":[{"en":"to be the right shape and size for somebody/something","cn":"（形状和尺寸）适合，合身","g":"[intransitive, transitive]","sc":"right size/type","ex":{"en":"I tried the dress on but it didn't fit.","cn":"我试穿了那连衣裙，但不合身。"}},{"en":"to be of the right size, type or number to go somewhere","cn":"（大小、式样、数量）可容纳，可装进","g":"[intransitive]","sc":"right size/type","ex":{"en":"I'd like to have a desk in the room but it won't fit.","cn":"我想在房间放一张桌子，但是搁不下。"}},{"en":"to put clothes on somebody and make them the right size and shape","cn":"试穿（衣服）","g":"[transitive, often passive]","sc":"right size/type","ex":{"en":"I'm going to be fitted for my wedding dress today.","cn":"今天我要去试穿结婚礼服。"}},{"en":"to put or fix something somewhere","cn":"安置，安装（在某处）","g":"[transitive]","sc":"put something somewhere","ex":{"en":"They fitted a smoke alarm to the ceiling.","cn":"他们把烟雾报警器安装在天花板上。"}},{"en":"to put or join something in the right place","cn":"合上；盖上；组合；组装","g":"[intransitive, transitive]","sc":"put something somewhere","ex":{"en":"The glass fits on top of the jug to form a lid.","cn":"这个玻璃杯放在大罐口上恰好当个盖子。"}},{"en":"to agree with, match or be suitable for something; to make something do this","cn":"（使）与…一致，和…相称，符合","g":"[intransitive, transitive]","sc":"agree/match","ex":{"en":"Something doesn't quite fit here.","cn":"这里有点不大协调。"}},{"en":"to make somebody/something suitable for a particular job or situation","cn":"使胜任（某工作）；使适合（某情况）","g":"[transitive]","lab":"especially British English","sc":"make suitable","ex":{"en":"His experience fitted him perfectly for the job.","cn":"他的经验使他完全胜任这项工作。"}},{"en":"healthy and strong, especially because you do regular physical exercise","cn":"健壮的；健康的","lab":"British English","sc":"healthy","ex":{"en":"Top athletes have to be very fit.","cn":"顶级运动员体格必须十分健壮。"},"pos":"adjective"},{"en":"suitable; of the right quality; with the right qualities or skills","cn":"（质量、素质或技能）适合的，恰当的，合格的","lab":"formal","sc":"suitable","ex":{"en":"The food was not fit for human consumption.","cn":"这食物不适合人吃。"},"pos":"adjective"},{"en":"ready or likely to do something extreme","cn":"可能（或准备）做某事至极端程度","lab":"British English, informal，，","sc":"ready","ex":{"en":"They worked until they were fit to drop (= so tired that they were likely to fall down).","cn":"他们一直工作到快要累趴下了。"},"pos":"adjective"},{"en":"sexually attractive","cn":"性感迷人的","lab":"British English, informal，，","sc":"attractive","pos":"adjective"},{"en":"a sudden attack of an illness, such as epilepsy, in which somebody becomes unconscious and their body may make violent movements","cn":"（癫痫等的）突发，发作；昏厥；痉挛","g":"[countable]","sc":"illness","ex":{"en":"to have an epileptic fit","cn":"癫痫发作"},"pos":"noun"},{"en":"a sudden short period of coughing (= forcing air through the throat noisily) or of laughing, that you cannot control","cn":"一阵（忍不住的咳嗽、笑）","g":"[countable]","sc":"of coughing/laughter","ex":{"en":"a fit of coughing","cn":"一阵咳嗽"},"pos":"noun"},{"en":"a short period of very strong feeling","cn":"（强烈感情）发作，冲动","g":"[countable]","sc":"of strong feeling","ex":{"en":"to act in a fit of anger/rage/temper/pique","cn":"一阵愤怒／狂怒／怒火／恼怒之下采取行动"},"pos":"noun"},{"en":"the way that something, especially a piece of clothing, fits; the way that somebody/something fits into something","cn":"（尤指衣服）合身的程度；容纳于…的状态；贴合度","g":"[countable, uncountable]","sc":"how something fits","ex":{"en":"The shoe has a special strap to ensure a good fit.","cn":"这鞋有一条专用的带子，以确保合脚。"},"pos":"noun"},{"en":"the way that two things match each other or are suitable for each other","cn":"匹配；相配","g":"[countable]","sc":"match","ex":{"en":"a perfect fit between the recruit and the job","cn":"新聘员工和工作的完美契合"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(大小和形状)适合;合身","en":"If something fits, it is the right size and shape to go onto a person's body or onto a particular object.","ex":{"en":"The sash, kimono, and other garments were made to fit a child","cn":"腰带、和服和其他衣服都是儿童款的。"}},{"pos":"N-SING 单数名词","cn":"适合;合身","en":"If something is a good fit, it fits well.","ex":{"en":"Eventually he was happy that the sills and doors were a reasonably good fit.","cn":"门槛和门扇算是贴合良好，他终于开心了。"}},{"pos":"VERB 动词","cn":"试穿(看何处需要改动)","en":"If you are fitted for a particular piece of clothing, you try it on so that the person who is making it can see where it needs to be altered.","ex":{"en":"She was being fitted for her wedding dress.","cn":"她正在试穿婚纱。"}},{"pos":"VERB 动词","cn":"适合放置(于);为放置(于…)而设计","en":"If something fits somewhere, it can be put there or is designed to be put there.","ex":{"en":"...a pocket computer which is small enough to fit into your pocket","cn":"小得能够放进衣袋里的袖珍电脑"}},{"pos":"VERB 动词","cn":"将…放(进)","en":"If you fit something into a particular space or place, you put it there.","ex":{"en":"She fitted her key in the lock","cn":"她把钥匙插进锁孔。"}},{"pos":"VERB 动词","cn":"小心固定;稳固放置","en":"If you fit something somewhere, you attach it there, or put it there carefully and securely.","ex":{"en":"Fit hinge bolts to give extra support to the door lock","cn":"安上铰链插销，让门锁更牢靠。"}},{"pos":"VERB 动词","cn":"与…相配;与…相协调;符合","en":"If something fits something else or fits into it, it goes together well with that thing or is able to be part of it.","ex":{"en":"Her daughter doesn't fit the current feminine ideal","cn":"她女儿并不符合当今的完美女性标准。"}},{"pos":"VERB 动词","cn":"适合;符合;与…相称","en":"You can say that something fits a particular person or thing when it is appropriate or suitable for them or it.","ex":{"en":"The punishment must always fit the crime.","cn":"必须始终坚持罪罚相当的原则。"}},{"pos":"ADJ 形容词","cn":"适合的;合适的;适当的","en":"If something is fit for a particular purpose, it is suitable for that purpose.","ex":{"en":"Of the seven bicycles we had, only two were fit for the road.","cn":"我们的7辆自行车中，只有两辆适合走这种路。"}},{"pos":"ADJ 形容词","cn":"合格的;胜任的","en":"If someone is fit to do something, they have the appropriate qualities or skills that will allow them to do it.","ex":{"en":"You're not fit to be a mother!","cn":"你不配做母亲！"}},{"pos":"VERB 动词","cn":"使合格;使胜任","en":"If something fits someone for a particular task or role, it makes them good enough or suitable for it.","ex":{"en":"...a man whose past experience fits him for the top job in education","cn":"一个资历丰富、适合担任教育界最高职位的人"}},{"pos":"ADJ 形容词","cn":"俊秀的;漂亮的","en":"If you describe someone as fit, you mean that they are good-looking.","ex":{"en":"About an hour later a really fit guy came up to me on the dance floor.","cn":"大概过了一个小时，一个长相非常俊美的男人在舞池里向我走过来。"}},{"pos":"ADJ 形容词","cn":"就要;快要;简直要","en":"If you say that something or someone is fit to produce some extreme result, you are emphasizing the extreme nature of that thing or that person's activity.","ex":{"en":"The stink was fit to knock you down.","cn":"这臭味简直要把人熏倒。"}},{"pos":"PHRASE 短语","cn":"(表示不赞成)决定，选择，认为做…合适","en":"If you say that someone sees fit to do something, you mean that they are entitled to do it, but that you disapprove of their decision to do it.","ex":{"en":"He's not a friend, you say, yet you saw fit to lend him money.","cn":"你说他不是朋友，但你却决定借钱给他。"}},{"pos":"","cn":"","en":"fit the bill→see: ;"},{"pos":"","cn":"","en":". to fit like a glove→see: ;"},{"pos":"","cn":"","en":"not in a fit state→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"找到时间(见某人);安排时间(做某事)","en":"If you manage to fit a person or task in, you manage to find time to deal with them.","ex":{"en":"We work long hours both outside and inside the home and we rush around trying to fit everything in","cn":"我们家里家外长时间忙活，忙完这里忙那里，想把一切都搞定。"}},{"pos":"PHRASAL VERB 短语动词","cn":"相处融洽;适应","en":"If you fit in as part of a group, you seem to belong there because you are similar to the other people in it.","ex":{"en":"She was great with the children and fitted in beautifully.","cn":"她和孩子们打交道很有一手,相处得十分融洽。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(在某种情形或体系中)发挥作用，担当职责;适合;符合","en":"If you say that someone or something fits in, you understand how they form part of a particular situation or system.","ex":{"en":"He knew where I fitted in and what he had to do to get the best out of me","cn":"他知道我适合做什么，也知道他要怎么做才能让我发挥出最佳水平。"}},{"pos":"PHRASAL VERB 短语动词","cn":"融入;与…相处融洽(或和谐)","en":"If you fit into a particular group, you seem to belong there because you are similar to the other people in it.","ex":{"en":"It's hard to see how he would fit into the team.","cn":"很难看出他将如何融入这支队伍。"}},{"pos":"PHRASAL VERB 短语动词","cn":"归属，适于(某种情形或体系)","en":"If something fits into a particular situation or system, that seems to be the right place for it.","ex":{"en":"Most film locations broadly fit into two categories; those on private property and those in a public place.","cn":"多数电影的拍摄场地大致归为两类：私人宅院与公共场地。"}},{"pos":"PHRASAL VERB 短语动词","cn":"为…提供装备;供给…必要的东西","en":"If you fit someone or something out, or you fit them up, you provide them with equipment and other things that they need.","ex":{"en":"We helped to fit him out for a trip to the Baltic","cn":"我们帮他准备了去波罗的海的行装。"}},{"pos":"PHRASAL VERB 短语动词","cn":"诬陷;诬告","en":"If someone fits another person up, they try to make it seem that that person is responsible for a crime.","ex":{"en":"Mr Stone said inmates who had given evidence were trying to 'fit him up'","cn":"斯通先生说那些提供证据的同狱犯人是在试图“诬陷他”。"}},{"pos":"","cn":"","en":"相关词组：fit in fit into fit out fit up"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健康的;强健的","en":"Someone who is fit is healthy and physically strong.","ex":{"en":"An averagely fit person can master easy ski runs within a few days.","cn":"健康的普通人几天内就可以掌握简单的滑雪技术。"}},{"pos":"","cn":"","en":"fit as a fiddle→see: ; fighting fit→see: ;"},{"pos":"N-COUNT 可数名词","cn":"痉挛;昏厥","en":"If someone has a fit they suddenly lose consciousness and their body makes uncontrollable movements.","ex":{"en":"About two in every five epileptic fits occur during sleep","cn":"每5例癫痫病中约有两例是在睡眠过程中发作的。"}},{"pos":"N-COUNT 可数名词","cn":"(突然止不住的)一阵(咳嗽、大笑)","en":"If you have a fit of coughing or laughter, you suddenly start coughing or laughing in an uncontrollable way.","ex":{"en":"Halfway down the cigarette she had a fit of coughing","cn":"烟抽到一半，她突然一阵猛咳。"}},{"pos":"N-COUNT 可数名词","cn":"(愤怒、惊慌等的)爆发，发作","en":"If you do something in a fit of anger or panic, you are very angry or afraid when you do it.","ex":{"en":"Pattie shot Tom in a fit of jealous rage.","cn":"帕蒂妒火中烧，开枪击中了汤姆。"}},{"pos":"PHRASE 短语","cn":"大发雷霆;大光其火;大吃一惊","en":"If you say that someone will have a fit when they hear about something, you mean that they will be very angry or shocked.","ex":{"en":"Will Mrs Winterton have a fit if we add one more to the guest list at this late stage?","cn":"到这么晚的时候我们再增加一个客人，温特顿太太会发火吗？"}},{"pos":"PHRASE 短语","cn":"忍不住大笑;忍俊不禁","en":"Someone who is in fits is laughing uncontrollably.","ex":{"en":"He was a much more entertaining person, who used to have us all in fits.","cn":"他以前更为风趣，常常让我们大家都捧腹大笑。"}},{"pos":"PHRASE 短语","cn":"间歇性地;一阵一阵地","en":"Something that happens in fits and starts or by fits and starts keeps happening and then stopping again.","ex":{"en":"My slimming attempts tend to go in fits and starts","cn":"我的瘦身运动总是三天打鱼两天晒网。"}}]},"examples":[{"en":"He's never done this type of work before; I'm not sure how he'll fit in with the other people.","cn":"他过去从未干过这种工作，很难说他是否会与其他人配合得好。"},{"en":"The newspaper did not see fit to publish my letter (= and I criticize it for that).","cn":"那份报纸认为我的信件不宜发表（而我批评这种看法）。"}]},"fire":{"media":{"uk":"media/uk/fire__gb_1.mp3","us":"media/us/fire__us_1.mp3"},"oxford":{"phon":"ˈfaɪə(r)","pos":"noun","senses":[{"en":"the flames, light and heat, and often smoke, that are produced when something burns","cn":"火","g":"[uncountable]","sc":"something burning","ex":{"en":"Most animals are afraid of fire.","cn":"大多数动物怕火。"}},{"en":"flames that are out of control and destroy buildings, trees, etc.","cn":"失火；火灾","g":"[uncountable, countable]","sc":"something burning","ex":{"en":"Several youths had set fire to the police car (= had made it start burning).","cn":"几个年轻人纵火焚烧警车。"}},{"en":"a pile of burning fuel, such as wood or coal, used for cooking food or heating a room","cn":"炉火；灶火","g":"[countable]","sc":"for heating/cooking","ex":{"en":"They cook on an open fire.","cn":"他们用明火做饭。"}},{"en":"a piece of equipment for heating a room","cn":"取暖器；暖气装置","g":"[countable]","lab":"especially British English","sc":"for heating/cooking","ex":{"en":"a gas/an electric fire","cn":"煤气／电取暖器"}},{"en":"shots from guns","cn":"射击；火力","g":"[uncountable]","sc":"from guns","ex":{"en":"The gunmen opened fire on (= started shooting at) the police.","cn":"持枪歹徒向警察开火。"}},{"en":"strong criticism","cn":"严厉的批评；斥责；谴责","g":"[uncountable]","sc":"criticism","ex":{"en":"She directed her fire against the new education policy.","cn":"她大力抨击新的教育政策。"}},{"en":"very strong emotion, especially anger or enthusiasm","cn":"激情；愤怒；热情","g":"[uncountable]","sc":"anger/enthusiasm","ex":{"en":"Her eyes were full of fire.","cn":"她的双眼充满激情的火花。"}},{"en":"to shoot bullets, etc. from a gun or other weapon","cn":"射击；开火","g":"[intransitive, transitive]","sc":"shoot","ex":{"en":"The officer ordered his men to fire.","cn":"军官下令士兵射击。"},"pos":"verb"},{"en":"to shoot bullets out","cn":"射出（子弹）","g":"[intransitive, transitive]","sc":"shoot","ex":{"en":"We heard the sound of guns firing.","cn":"我们听见枪炮射击声。"},"pos":"verb"},{"en":"to force somebody to leave their job","cn":"解雇；开除","g":"[transitive]","lab":"British English","sc":"from job","ex":{"en":"We had to fire him for dishonesty.","cn":"他不诚实，我们不得不开除他。"},"pos":"verb"},{"en":"to make somebody feel very excited about something or interested in something","cn":"激励；激起热情；使充满热情","g":"[transitive]","sc":"make somebody enthusiastic","ex":{"en":"The talk had fired her with enthusiasm for the project.","cn":"这次谈话激起了她对这个项目的热情。"},"pos":"verb"},{"en":"when an engine fires, an electrical spark is produced that makes the fuel burn and the engine start to work","cn":"点火；发动","g":"[intransitive]","sc":"of engine","pos":"verb"},{"en":"using the fuel mentioned in order to operate","cn":"以…为燃料的","sc":"-fired","ex":{"en":"gas-fired central heating","cn":"燃气集中供暖"},"pos":"verb"},{"en":"to heat a clay object to make it hard and strong","cn":"烧制（陶器、砖等）","g":"[transitive]","sc":"clay objects","ex":{"en":"to fire pottery","cn":"烧制陶器"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"火","en":"Fire is the hot, bright flames produced by things that are burning.","ex":{"en":"They saw a big flash and a huge ball of fire reaching hundreds of feet into the sky","cn":"他们看见一道强光和一个巨大的火球冲向数百英尺的高空。"}},{"pos":"N-VAR 可变名词","cn":"火灾;失火","en":"Fire or a fire is an occurrence of uncontrolled burning which destroys buildings, forests, or other things.","ex":{"en":"87 people died in a fire at the Happy Land Social Club","cn":"87 人在乐土社交俱乐部的火灾中丧生。"}},{"pos":"N-COUNT 可数名词","cn":"炉火;灶火;生成的火","en":"A fire is a burning pile of wood, coal, or other fuel that you make, for example to use for heat, light, or cooking.","ex":{"en":"There was a fire in the grate","cn":"壁炉内燃着火。"}},{"pos":"N-COUNT 可数名词","cn":"(电或煤气)取暖器","en":"A fire is a device that uses electricity or gas to give out heat and warm a room.","ex":{"en":"The gas fire was still alight","cn":"燃气取暖器还在烧着。"}},{"pos":"VERB 动词","cn":"烧制(陶器等黏土制品)","en":"When a pot or clay object is fired, it is heated at a high temperature in a special oven, as part of the process of making it.","ex":{"en":"After the pot is dipped in this mixture, it is fired","cn":"陶罐在这一混合料中浸过之后就拿去烧制。"}},{"pos":"VERB 动词","cn":"(引擎)点火，打火","en":"When the engine of a motor vehicle fires, an electrical spark is produced which causes the fuel to burn and the engine to work.","ex":{"en":"The engine fired and we moved off.","cn":"点着引擎后我们就开走了。"}},{"pos":"VERB 动词","cn":"(以某种燃料)驱动","en":"If a machine is fired with a particular fuel, it operates by means of that fuel.","ex":{"en":"The engines were fired with coal and needed water to keep the steam up.","cn":"这些发动机烧煤，并且需要加水以不断产生蒸汽。"}},{"pos":"VERB 动词","cn":"激起;唤起;使充满激情;激发(想象力)","en":"If you fire someone with enthusiasm, you make them feel very enthusiastic. If you fire someone's imagination, you make them feel interested and excited.","ex":{"en":"...the potential to fire the imagination of an entire generation","cn":"能够激发整整一代人想象力的潜能"}},{"pos":"N-UNCOUNT 不可数名词","cn":"激情;生气;活力","en":"You can use fire to refer in an approving way to someone's energy and enthusiasm.","ex":{"en":"I went to hear him speak and was very impressed. He seemed so full of fire","cn":"我去听了他的讲话，结果留下了非常深刻的印象。他看上去充满了激情。"}},{"pos":"PHRASE 短语","cn":"着火;起火;开始燃烧","en":"If an object or substance catches fire, it starts burning.","ex":{"en":"My home catches fire and everything is destroyed","cn":"我家失了火，所有的东西都烧毁了。"}},{"pos":"PHRASE 短语","cn":"激动人心;赢得成功","en":"If a situation or event catches fire, it begins to be exciting and successful.","ex":{"en":"The play only really catches fire once Aschenbach falls in love.","cn":"这部剧直到阿申巴赫堕入情网后才真正开始精彩起来。"}},{"pos":"PHRASE 短语","cn":"以火攻火;以毒攻毒;以其人之道还治其人之身","en":"If you fight fire with fire, you deal with people attacking or threatening you by using similar methods to the ones that they are using.","ex":{"en":"The only way they can deal with crime is to fight fire with fire.","cn":"他们打击犯罪的唯一方法就是以牙还牙。"}},{"pos":"PHRASE 短语","cn":"激情;生气;强烈的情感","en":"If you say that someone has fire in their belly, you are expressing approval of them because they are energetic, enthusiastic, and have very strong feelings.","ex":{"en":"Rocco does not have the same fire in his belly as his father.","cn":"罗科不像他父亲那样充满激情。"}},{"pos":"PHRASE 短语","cn":"着火;起火;在燃烧","en":"If something is on fire, it is burning and being damaged or destroyed by an uncontrolled fire.","ex":{"en":"The captain radioed that the ship was on fire.","cn":"船长发无线电说船着火了。"}},{"pos":"PHRASE 短语","cn":"热情似火;激动万分;激情澎湃","en":"If you say that someone is on fire, you mean they are very enthusiastic, excited, or passionate about something.","ex":{"en":"He was on fire with this marvelous sight.","cn":"看到这一令人叹为观止的景象，他激动万分。"}},{"pos":"PHRASE 短语","cn":"玩火;冒险;做危险的事","en":"If you say that someone is playing with fire, you mean that they are doing something dangerous that may result in great harm for them and cause many problems.","ex":{"en":"Schulte warned government and industrial leaders that those who even venture to think about mass layoffs are playing with fire.","cn":"舒尔特警告政府和业界领袖说，哪怕只是动动大规模裁员念头的人都是在玩火。"}},{"pos":"PHRASE 短语","cn":"放火烧;使燃烧","en":"If you set fire to something or if you set it on fire, you start it burning in order to damage or destroy it.","ex":{"en":"They set fire to vehicles outside that building","cn":"他们纵火焚烧了停在那幢大楼外的车辆。"}},{"pos":"","cn":"","en":"to have irons on the fire→see: ;"},{"pos":"","cn":"","en":"like a house on fire→see: ;"},{"pos":"","cn":"","en":"there's no smoke without fire→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"开动，发动(机器)","en":"If you fire up a machine, you switch it on.","ex":{"en":"Put on a helmet, fire up your engine and head out on the open road.","cn":"戴上头盔，发动引擎，开上乡村干道。"}},{"pos":"PHRASAL VERB 短语动词","cn":"激起…的热情(或积极性)","en":"If you fire someone up, you make them feel very enthusiastic or motivated.","ex":{"en":"The president knows his task is to fire up the delegates.","cn":"总统知道自己的任务就是唤起代表的热情。"}},{"pos":"","cn":"","en":"相关词组：fire up"},{"pos":"VERB 动词","cn":"开(枪或炮);射出(子弹)","en":"If someone fires a gun or a bullet, or if they fire, a bullet is sent from a gun that they are using.","ex":{"en":"Seven people were wounded when soldiers fired rubber bullets to disperse crowds","cn":"士兵发射橡皮子弹驱散人群时有7个人受了伤。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"枪击;炮火;火力","en":"You can use fire to refer to the shots fired from a gun or guns.","ex":{"en":"His car was raked with fire from automatic weapons","cn":"他的车遭到自动武器火力的扫射。"}},{"pos":"VERB 动词","cn":"射，放(箭)","en":"If you fire an arrow, you send it from a bow.","ex":{"en":"He fired an arrow into a clearing in the forest.","cn":"他将箭射向林中的一片空地。"}},{"pos":"VERB 动词","cn":"连珠炮似的提出(问题)","en":"If you fire questions at someone, you ask them a lot of questions very quickly, one after another.","ex":{"en":"They were bombarded by more than 100 representatives firing questions on pollution.","cn":"100多名代表针对污染问题向他们发起连珠炮似的提问。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"猛烈的批评(或抨击、指责)","en":"You can use fire to refer to someone's strong criticisms of something.","ex":{"en":"He said they should turn their fire on the Conservative Party instead.","cn":"他说他们应该掉转枪口，向保守党开火。"}},{"pos":"PHRASE 短语","cn":"吸引火力;成为靶子","en":"If you draw fire from someone, you cause them to shoot at you, for example because they think that you are threatening them.","ex":{"en":"Crowds elsewhere drew fire from troops.","cn":"其他地方的人群吸引了军队的火力。"}},{"pos":"PHRASE 短语","cn":"招致批评;引发攻击","en":"If you draw fire for something that you have done, you cause people to criticize you or attack you because of it.","ex":{"en":"The council recently drew fire for its intervention in the dispute","cn":"委员会最近因为介入该起争端而遭到批评。"}},{"pos":"PHRASE 短语","cn":"暂缓(或推迟)决定","en":"If you hang fire, you delay making a decision about something.","ex":{"en":"All I can suggest is that you just hang fire and wait a minute or two and try again","cn":"我的建议就是，先缓一缓，等上一两分钟再试一次。"}},{"pos":"PHRASE 短语","cn":"停止射击;等待射击开始","en":"If someone holds their fire or holds fire, they stop shooting or they wait before they start shooting.","ex":{"en":"Devereux ordered his men to hold their fire until the ships got closer.","cn":"德弗罗命令士兵等船靠近了再开火。"}},{"pos":"PHRASE 短语","cn":"暂缓（或推迟行动)","en":"If you hold fire in a situation, you delay before taking action.","ex":{"en":"Observers reckon the Bank of England will hold fire until nearer the Budget.","cn":"观察家认为英格兰银行会推迟到更加接近预算案出台时再采取措施。"}},{"pos":"PHRASE 短语","cn":"(子弹的)发射线，行进线","en":"If you are in the line of fire, you are in a position where someone is aiming their gun at you. If you move into their line of fire, you move into a position between them and the thing they were aiming at.","ex":{"en":"He cheerfully blows away any bad guy stupid enough to get in his line of fire","cn":"他兴高采烈地将蠢到撞上他枪口的坏家伙全都干掉。"}},{"pos":"PHRASE 短语","cn":"开枪;开火","en":"If you open fire on someone, you start shooting at them.","ex":{"en":"Then without warning, the troops opened fire on the crowd.","cn":"接着军队未作警示便向人群开了火。"}},{"pos":"PHRASE 短语","cn":"开枪回击;开火还击","en":"If you return fire or you return someone's fire, you shoot back at someone who has shot at you.","ex":{"en":"The soldiers returned fire after being attacked.","cn":"士兵们在遇袭后予以还击。"}},{"pos":"PHRASE 短语","cn":"遭到射击;受到火力攻击","en":"If you come under fire or are under fire, someone starts shooting at you.","ex":{"en":"The Belgians fell back as the infantry came under fire.","cn":"步兵团受到火力攻击时比利时人向后撤退。"}},{"pos":"PHRASE 短语","cn":"遭到猛烈批评;受到强烈抨击","en":"If you come under fire from someone or are under fire, they criticize you strongly.","ex":{"en":"The president's plan first came under fire from critics who said he hadn't included enough spending cuts.","cn":"总统的计划先是遭到批评者的猛烈抨击，他们称开支削减力度不够。"}},{"pos":"","cn":"","en":"to fire from the hip→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"说吧;讲吧;问吧","en":"If someone wants to say or ask something, you can say 'fire away' as a way of showing that you are ready for them to speak.","ex":{"en":"'May I ask you something?' — 'Sure. Fire away.'","cn":"“我可以问你一个问题吗？”——“当然可以。尽管问吧。”"}},{"pos":"PHRASAL VERB 短语动词","cn":"发射，射出(子弹、导弹等)","en":"If you fire off a shot, you send a bullet or other missile from a gun.","ex":{"en":"A gunman fired off a volley of shots into the air","cn":"持枪歹徒朝天扫射了一排子弹。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(常指作为一系列之一地迅速)发出(信件)，提出(问题),讲出(话语)","en":"If you fire off a letter, question, or remark, you send or say it very quickly, often as part of a series.","ex":{"en":"He immediately fired off an angry letter to his ministry colleagues","cn":"他立即给部里的同事发了一封怒气冲冲的信。"}},{"pos":"","cn":"","en":"相关词组：fire away fire off"},{"pos":"VERB 动词","cn":"解雇;开除","en":"If an employer fires you, they dismiss you from your job.","ex":{"en":"If he hadn't been so good at the rest of his job, I probably would have fired him","cn":"如果不是因为他在工作的其他方面做得如此之好，我可能就把他开除了。"}}]},"examples":[{"en":"She spent an hour firing off emails to all concerned.","cn":"她花了一个小时气冲冲地向有关各方发电邮。"},{"en":"‘I've got a few questions.’ ‘OK then, fire away.’ “","cn":"我有几个问题。” “好，那就问吧。”"}]},"fizzy":{"oxford":{"phon":"ˈfɪzi","pos":"adjective","senses":[{"en":"having bubbles of gas in it","cn":"有气泡的","ex":{"en":"fizzy drinks","cn":"气泡饮料"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(饮料)起泡的，充气的，冒泡的","en":"Fizzy drinks are drinks that contain small bubbles of carbon dioxide. They make a sound like a long 's' when you pour them.","ex":{"en":"...fizzy water.","cn":"汽水"}}]},"media":{"uk":"media/uk/fizzy__gb_1.mp3","us":"media/us/fizzy__us_1.mp3","img":["media/ldoce/img/ldoce_318.png"]},"examples":[{"en":"fizzy drinks","cn":"起泡饮料"},{"en":"fizzy water","cn":"冒泡的水"}]},"fits":{"lemma":"fit","media":{"uk":"media/uk/fit__gb_1.mp3","us":"media/us/fit__us_1.mp3"}},"fix":{"media":{"uk":"media/uk/fix__gb_1.mp3","us":"media/us/fix__us_1.mp3","img":["media/ldoce/img/repair.jpg"]},"oxford":{"phon":"fɪks","pos":"verb","senses":[{"en":"to repair or correct something","cn":"修理；校准；校正","sc":"repair","ex":{"en":"The car won't start—can you fix it?","cn":"这辆车发动不起来了，你能修理一下吗？"}},{"en":"to decide on a date, a time, an amount, etc. for something","cn":"决定，确定（日期、时间、数量等）","sc":"arrange","ex":{"en":"Has the date of the next meeting been fixed?","cn":"下次会议的日期确定了没有？"}},{"en":"to arrange or organize something","cn":"安排；组织","lab":"informal","sc":"arrange","ex":{"en":"I'll fix a meeting.","cn":"我要安排一次会议。"}},{"en":"to put something in a place so that it will not move","cn":"使固定；安装","lab":"especially British English","sc":"attach","ex":{"en":"to fix a shelf to the wall","cn":"把搁架固定在墙上。"}},{"en":"to discover or say the exact position, time, etc. of something","cn":"找到，确定，说出（确切位置、时间等）","sc":"position/time","ex":{"en":"We can fix the ship's exact position at the time the fire broke out.","cn":"我们可以确定发生火灾时那艘船的确切位置。"}},{"en":"to provide or prepare something, especially food","cn":"提供，准备（尤指食物）","lab":"especially North American English","sc":"food/drink","ex":{"en":"Can I fix you a drink?","cn":"我给你弄杯饮料好吗？"}},{"en":"to make something such as your hair or face neat and attractive","cn":"梳洗；整理；收拾","lab":"especially North American English","sc":"hair/face","ex":{"en":"I'll fix my hair and then I'll be ready.","cn":"我梳梳头就准备好了。"}},{"en":"to arrange the result of something in a way that is not honest or fair","cn":"操纵；作弊","g":"[often passive]","lab":"informal","sc":"result","ex":{"en":"I'm sure the race was fixed.","cn":"我肯定这场比赛有人操纵。"}},{"en":"to punish somebody who has harmed you and stop them doing you any more harm","cn":"惩罚；收拾","lab":"informal","sc":"punish","ex":{"en":"Don't worry—I'll fix him.","cn":"别担忧，我会收拾他的。"}},{"en":"to treat film for cameras, etc. with a chemical so that the colours do not change or become less bright","cn":"定（影）；定（色）","lab":"specialist","sc":"in photography"},{"en":"to make an animal unable to have young by means of an operation","cn":"阉割（家畜）","lab":"North American English, informal，，","sc":"animal"},{"en":"a solution to a problem, especially an easy or temporary one","cn":"（尤指简单、暂时的）解决方法","g":"[countable]","lab":"informal","sc":"solution","ex":{"en":"Luckily there is an easy fix.","cn":"幸运的是，有一个简单的解决方法。"},"pos":"noun"},{"en":"an amount of something that you need and want frequently, especially an illegal drug such as heroin","cn":"（致瘾的东西，尤指毒品的）一次用量","g":"[singular]","lab":"informal","sc":"drug","ex":{"en":"to get yourself a fix","cn":"给自己注射一剂毒品"},"pos":"noun"},{"en":"a difficult situation","cn":"困境；窘境","g":"[singular]","sc":"difficult situation","ex":{"en":"We've got ourselves in a fix about this.","cn":"在这个问题上我们已陷入了困境。"},"pos":"noun"},{"en":"the act of finding the position of a ship or an aircraft","cn":"（船或飞机的）方位确定，定位","g":"[singular]","sc":"on position","ex":{"en":"They managed to get a fix on the yacht's position.","cn":"他们设法确定了快艇的方位。"},"pos":"noun"},{"en":"an act of understanding something","cn":"理解；了解","g":"[singular]","lab":"informal","sc":"understanding","ex":{"en":"He tried to get a fix on the young man's motives, but he just couldn't understand him.","cn":"他努力了解这个年轻人的动机，但就是弄不清楚。"},"pos":"noun"},{"en":"a thing that is dishonestly arranged; a trick","cn":"受操纵的事；勾当；搞鬼","g":"[singular]","lab":"informal","sc":"dishonest result","ex":{"en":"Her promotion was a fix, I'm sure!","cn":"我肯定她的提升有内幕！"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"固定;安装","en":"If something is fixed somewhere, it is attached there firmly or securely.","ex":{"en":"It is fixed on the wall","cn":"它固定在墙上。"}},{"pos":"VERB 动词","cn":"确定，决定，选定(日期、价格、政策等)","en":"If you fix something, for example a date, price, or policy, you decide and say exactly what it will be.","ex":{"en":"He's going to fix a time when I can see him","cn":"他会确定一个我和他会面的时间。"}},{"pos":"VERB 动词","cn":"安排;弄妥","en":"If you fix something for someone, you arrange for it to happen or you organize it for them.","ex":{"en":"I've fixed it for you to see Bonnie Lachlan","cn":"你去见邦尼·拉克伦的事我已经安排好了。"}},{"pos":"VERB 动词","cn":"修理;维修","en":"If you fix something which is damaged or which does not work properly, you repair it.","ex":{"en":"He cannot fix the electricity","cn":"他不会修电路。"}},{"pos":"VERB 动词","cn":"处理，解决(问题等)","en":"If you fix a problem or a bad situation, you deal with it and make it satisfactory.","ex":{"en":"It's not too late to fix the problem, although time is clearly getting short","cn":"虽然时间越来越紧迫，但现在处理这个问题还为时未晚。"}},{"pos":"N-COUNT 可数名词","cn":"解决方案(或措施)","en":"You can refer to a solution to a problem as a fix .","ex":{"en":"Many of those changes could just be a temporary fix.","cn":"那些变革中可能有很多只是权宜之计。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(目光)专注于，凝视;目不转睛地看","en":"If you fix your eyes on someone or something or if your eyes fix on them, you look at them with complete attention.","ex":{"en":"She fixes her steel-blue eyes on an unsuspecting local official","cn":"她那灰蓝色的眼睛紧盯着一个毫无戒心的地方官员。"}},{"pos":"VERB 动词","cn":"(用某种表情)看着，望着","en":"If you fix someone with a particular kind of expression, you look at them in that way.","ex":{"en":"He took her hand and fixed her with a look of deep concern","cn":"他抓住她的手，表情极其关切地看着她。"}},{"pos":"VERB 动词","cn":"将(注意力)集中在;专心考虑","en":"If you fix your attention on someone or something, you think about them with complete attention.","ex":{"en":"Fix your attention on the practicalities of financing your schemes","cn":"重点考虑为你的计划融资是否可行。"}},{"pos":"VERB 动词","cn":"牢记，铭记，镌刻(在头脑中)","en":"If someone or something is fixed in your mind, you remember them well, for example because they are very important, interesting, or unusual.","ex":{"en":"Leonard was now fixed in his mind","cn":"伦纳德现在已经令他无法忘怀。"}},{"pos":"VERB 动词","cn":"把(枪、相机、雷达)对准(或瞄准、指向)","en":"If someone fixes a gun, camera, or radar on something, they point it at that thing.","ex":{"en":"The US crew fixed its radar on the Turkish ship","cn":"美国船员将雷达对准那艘土耳其船。"}},{"pos":"VERB 动词","cn":"(通常用雷达或电子设备)找到，弄清，确定(确切位置)","en":"If you fix the position of something, you find out exactly where it is, usually by using radar or electronic equipment.","ex":{"en":"He had not been able to fix his position","cn":"他一直未能确定他所在的位置。"}},{"pos":"N-SING 单数名词","cn":"了解;理解;认识","en":"If you get a fix on someone or something, you have a clear idea or understanding of them.","ex":{"en":"It's been hard to get a steady fix on what's going on.","cn":"要对正在发生的事情保持持续的关注和了解并不容易。"}},{"pos":"VERB 动词","cn":"做，准备(食物或饮料)","en":"If you fix some food or a drink for someone, you make it or prepare it for them.","ex":{"en":"Sarah fixed some food for us","cn":"萨拉为我们准备了一些吃的。"}},{"pos":"VERB 动词","cn":"整理，收拾(头发、衣服或妆容)","en":"If you fix your hair, clothes, or make-up, you arrange or adjust them so you look neat and tidy, showing you have taken care with your appearance.","ex":{"en":"'I've got to fix my hair,' I said and retreated to my bedroom","cn":"“我得把头发梳理一下，”我说罢回到了卧室。"}},{"pos":"VERB 动词","cn":"矫正(牙齿);整形","en":"If you have your teeth fixed, you have treatment from a dentist to make your teeth even, straight, and white.","ex":{"en":"The PR man suggested that I might benefit from getting my teeth fixed","cn":"公关顾问建议说，整牙也许对我有好处。"}},{"pos":"VERB 动词","cn":"在(比赛、竞选等活动中)作弊，做手脚，操纵","en":"If someone fixes a race, election, contest, or other event, they make unfair or illegal arrangements or use deception to affect the result.","ex":{"en":"They offered opposing players bribes to fix a decisive league match against Valenciennes","cn":"他们贿赂对方队员，在联赛对阵瓦朗谢讷队的一场决定性比赛中作弊。"}},{"pos":"VERB 动词","cn":"操纵，操控(价格)","en":"If you accuse someone of fixing prices, you accuse them of making unfair arrangements to charge a particular price for something, rather than allowing market forces to decide it.","ex":{"en":"...a suspected cartel that had fixed the price of steel for the construction market","cn":"涉嫌操控建筑市场钢材价格的卡特尔"}},{"pos":"N-COUNT 可数名词","cn":"(毒品)一剂，一次用量","en":"An injection of an addictive drug such as heroin can be referred to as a fix ."},{"pos":"N-COUNT 可数名词","cn":"(维持身体或心理需要所需的)一个剂量，一定数量","en":"You can use fix to refer to an amount of something which a person gets or wants and which helps them physically or psychologically to survive.","ex":{"en":"It turned the country into an 'aid junkie', heavily dependent on its annual fix of dollars","cn":"这使得该国严重依赖每年救济的那点美元，成了“嗜援成瘾”的国家。"}},{"pos":"N-SING 单数名词","cn":"(尤指由自己引起的)困境，窘境","en":"If you are in a fix, you are in a difficult situation, especially one that you have caused for yourself.","ex":{"en":"He was in a fix","cn":"他陷入了困境。"}},{"pos":"VERB 动词","cn":"定(影);定(色)","en":"To fix something such as a dye or photographic image means to treat it with chemicals so that it does not lose its colour or disappear.","ex":{"en":"Certain pigment colours were painted on to dry plaster using tempera (where egg yolk is used to fix the pigment)","cn":"使用蛋彩画颜料(内含可以定色的蛋黄)在干石膏上绘出了特定颜色。"}},{"pos":"VERB 动词","cn":"使永远停止;制止;收拾","en":"If you say that you will fix someone, you mean that you will stop their activities permanently.","ex":{"en":"That'll fix him.","cn":"那样他就不会再干了。"}},{"pos":"VERB 动词","cn":"打算;想要;计划","en":"If you say that you are fixing to do something, you mean that you are planning or intending to do it.","ex":{"en":"I'm fixing to go to graduate school","cn":"我打算去读研究生。"}},{"pos":"PHRASAL VERB 短语动词","cn":"决定;确定;选定","en":"If you fix on a particular thing, you decide that it is the one you want and will have.","ex":{"en":"The Vietnamese government has fixed on May 19th to celebrate his anniversary.","cn":"越南政府已经决定于5月19日庆祝他的诞辰。"}},{"pos":"PHRASAL VERB 短语动词","cn":"安排;确定","en":"If you fix something up, you arrange it.","ex":{"en":"I fixed up an appointment to see her","cn":"我安排了与她见面。"}},{"pos":"PHRASAL VERB 短语动词","cn":"装饰;修饰;整理","en":"If you fix something up, you do work that is necessary in order to make it more suitable or attractive.","ex":{"en":"I've fixed up Matthew's old room","cn":"我已经把马修原来住的房间装饰了一番。"}},{"pos":"PHRASAL VERB 短语动词","cn":"向…提供;为…准备","en":"If you fix someone up with something they need, you provide it for them.","ex":{"en":"We'll fix him up with a tie","cn":"我们将给他准备一条领带。"}},{"pos":"","cn":"","en":"相关词组：fix on fix up"}]},"examples":[{"en":"He tried to get a fix on the young man's motives, but he just couldn't understand him.","cn":"他努力了解这个年轻人的动机，但就是弄不清楚。"},{"en":"We can fix the ship's exact position at the time the fire broke out.","cn":"我们可以确定发生火灾时那艘船的确切位置。"}]},"fills":{"lemma":"fill","media":{"uk":"media/uk/fill__gb_1.mp3","us":"media/us/fill__us_1.mp3"}},"fine":{"media":{"uk":"media/uk/fine__gb_1.mp3","us":"media/us/fine__us_1.mp3"},"oxford":{"phon":"faɪn","pos":"adjective","senses":[{"en":"in good health","cn":"健康的；身体好的","lab":"especially British English","sc":"very well","ex":{"en":"‘How are you?’ ‘Fine, thanks.’","cn":"“你好吗？”“很好，谢谢。”"}},{"en":"of high quality; good","cn":"高质量的；美好的","g":"[usually before noun]","sc":"very good","ex":{"en":"a very fine performance","cn":"十分精彩的演出"}},{"en":"used to tell somebody that an action, a suggestion or a decision is acceptable","cn":"（指行为、建议、决定）可接受","sc":"acceptable/good enough","ex":{"en":"‘I'll leave this here, OK?’ ‘Fine.’","cn":"“我把这个留在这儿，可以吗？”“可以。”"}},{"en":"used to say you are satisfied with something","cn":"（表示满意）很好，不错，满意","lab":"ironic","sc":"acceptable/good enough","ex":{"en":"Don't worry. Your speech was fine.","cn":"别担心。你的讲话挺好的。"}},{"en":"bright and not raining","cn":"晴朗的","lab":"especially British English","sc":"weather","ex":{"en":"a fine day/evening","cn":"晴朗的一天／晚上"}},{"en":"pleasant to look at","cn":"标致的；秀丽的","g":"[usually before noun]","lab":"informal, especially North American English，，","sc":"attractive","ex":{"en":"a fine view","cn":"美景"}},{"en":"made of very small grains","cn":"小颗粒制成的；颗粒细微的","sc":"with small grains","ex":{"en":"fine sand","cn":"细沙"}},{"en":"attractive and small or thin","cn":"精致的；小巧玲珑的","g":"[usually before noun]","sc":"attractive","ex":{"en":"fine bone china","cn":"精致的骨瓷"}},{"en":"very thin or narrow; made of very thin or narrow wires or threads","cn":"纤细的；很细的；细丝制成的","sc":"very thin","ex":{"en":"His fine blond hair came down almost to his shoulders.","cn":"他纤细的金发几乎垂至肩部。"}},{"en":"difficult to see or describe","cn":"难以看出的；很难描述的","g":"[usually before noun]","sc":"detail/distinctions","ex":{"en":"You really need a magnifying glass to appreciate all the fine detail.","cn":"确实需要放大镜才能欣赏到一切细微之处。"}},{"en":"that you have a lot of respect for","cn":"值得尊敬的；杰出的","g":"[only before noun]","sc":"person","ex":{"en":"He was a fine man.","cn":"他是个优秀的人。"}},{"en":"sounding important and impressive but unlikely to have any effect","cn":"漂亮的；虚饰的；辞藻华丽的","sc":"words/speeches","ex":{"en":"His speech was full of fine words which meant nothing.","cn":"他的演讲华而不实。"}},{"en":"containing only a particular metal and no other substances that reduce the quality","cn":"纯的；无杂质的","lab":"specialist","sc":"metals","ex":{"en":"fine gold","cn":"纯金"}},{"en":"in a way that is acceptable or good enough","cn":"可接受；够好；蛮不错","lab":"British English","ex":{"en":"Keep going like that—you're doing fine.","cn":"就这样做下去，你做得蛮不错嘛。"},"pos":"adverb"},{"en":"a sum of money that must be paid as punishment for breaking a law or rule","cn":"罚金；罚款","lab":"especially North American English","ex":{"en":"I got a parking fine for parking on double yellow lines.","cn":"我由于在双黄线停车被罚款了。"},"pos":"noun"},{"en":"to make somebody pay money as an official punishment","cn":"对…处以罚款","ex":{"en":"The magistrate fined him $400.","cn":"地方法官对他处以 400 美元罚款。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"美好的;优秀的;杰出的","en":"You use fine to describe something that you admire and think is very good.","ex":{"en":"There is a fine view of the countryside","cn":"这里可以看到乡村的美景。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健康的;情绪良好的","en":"If you say that you are fine, you mean that you are in good health or reasonably happy.","ex":{"en":"Lina is fine and sends you her love and best wishes.","cn":"莉娜身体很好，还让我转达她对你的爱和祝福。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人满意的;可以接受的","en":"If you say that something is fine, you mean that it is satisfactory or acceptable.","ex":{"en":"The skiing is fine","cn":"滑雪还行。"}},{"pos":"CONVENTION 惯用语","cn":"行;可以","en":"You say 'fine' or 'that's fine' to show that you do not object to an arrangement, action, or situation that has been suggested.","ex":{"en":"If competition is the best way to achieve it, then, fine","cn":"如果竞争是达到目标的最佳方式，那就这么着吧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纤细的;尖细的;微小的","en":"Something that is fine is very delicate, narrow, or small.","ex":{"en":"The heat scorched the fine hairs on her arms","cn":"炙热烤焦了她手臂上的汗毛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精美的;精致的;华贵的","en":"Fine objects or clothing are of good quality, delicate, and expensive.","ex":{"en":"We waited in our fine clothes","cn":"我们身着盛装等候。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"细微的;精确的;精密的","en":"A fine detail or distinction is very delicate, small, or exact.","ex":{"en":"The market likes the broad outline but is reserving judgment on the fine detail.","cn":"市场对这一整体设想表示出认可，但在具体细节上还未作出反应。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高尚的;令人敬佩的","en":"A fine person is someone you consider good, moral, and worth admiring.","ex":{"en":"I was with fine people doing a good job","cn":"我和高尚的人们一起干着一份不错的工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)晴朗的","en":"When the weather is fine, the sun is shining and it is not raining.","ex":{"en":"He might be doing a spot of gardening if the weather is fine.","cn":"天气晴朗的话，他也许会侍弄侍弄花草。"}},{"pos":"N-COUNT 可数名词","cn":"罚金;罚款","en":"A fine is a punishment in which a person is ordered to pay a sum of money because they have done something illegal or broken a rule."},{"pos":"VERB 动词","cn":"对…处以罚金","en":"If someone is fined, they are punished by being ordered to pay a sum of money because they have done something illegal or broken a rule.","ex":{"en":"She was fined £500 and banned from driving for one month","cn":"她被罚款500 英镑，而且一个月内禁止开车。"}}]},"examples":[{"en":"‘Can I get you another drink?’ ‘No, thanks. I'm fine. ’ “","cn":"我可以再给你取一杯吗？” “不，谢谢。我够了。”"},{"en":"He tried to appeal to their finer feelings (= feelings of duty, love, etc.).","cn":"他试图打动他们更美好的情感（即责任感、爱等）。"}]},"fill":{"media":{"uk":"media/uk/fill__gb_1.mp3","us":"media/us/fill__us_1.mp3"},"oxford":{"phon":"fɪl","pos":"verb","senses":[{"en":"to make something full of something; to become full of something","cn":"（使）充满，装满，注满，填满","g":"[transitive, intransitive]","sc":"make full","ex":{"en":"Please fill this glass for me.","cn":"请把这个杯子给我倒满。"}},{"en":"to block a hole with a substance","cn":"堵塞，填补（洞、孔）","g":"[transitive]","sc":"block hole","ex":{"en":"They used putty to fill the holes.","cn":"他们用油灰把洞填平了。"}},{"en":"a put a filling (= a small amount of special material) in a hole in a tooth","cn":"满足","g":"[transitive]","sc":"tooth","ex":{"en":"I need to have two teeth filled.","cn":"我有两颗牙要补。"}},{"en":"to make somebody have a strong feeling; to become full of a strong feeling","cn":"（使某人）满怀强烈的感情","g":"[transitive, intransitive]","sc":"with feeling","ex":{"en":"A deep joy filled me.","cn":"我心里充满了深深的喜悦。"}},{"en":"if a smell, sound or light fills a place, it is very strong, loud or bright and easy to notice","cn":"使遍及；弥漫；布满；照满","g":"[transitive]","sc":"with smell/sound/light","ex":{"en":"The sound of bells ringing filled the air.","cn":"钟声响彻四周。"}},{"en":"full of the thing mentioned","cn":"充满…的","sc":"-filled","ex":{"en":"a smoke-filled room","cn":"烟雾弥漫的房间"}},{"en":"to supply something that is missing","cn":"填补；满足","g":"[transitive]","sc":"a need/gap","ex":{"en":"More nurseries will be built to fill the need for high-quality childcare.","cn":"将建立更多的托儿所以满足对高质量儿童保育的需求。"}},{"en":"to do a job, have a role or position, etc.","cn":"担任；充任","g":"[transitive]","sc":"job","ex":{"en":"The team needs someone to fill the role of manager.","cn":"该队需要一个人来担任主教练。"}},{"en":"to choose somebody for a job","cn":"填补（职位空缺）","g":"[transitive]","sc":"job","ex":{"en":"The vacancy has already been filled.","cn":"该空缺已有人填补。"}},{"en":"to use up a particular period of time doing something","cn":"耗去；打发；消磨","g":"[transitive]","sc":"time","ex":{"en":"How do you fill your day now that you've retired?","cn":"现在你已退休了，怎样打发你的日子？"}},{"en":"to make somebody/yourself feel unable to eat any more","cn":"（使）吃饱","g":"[transitive]","lab":"informal","sc":"with food","ex":{"en":"The kids filled themselves with snacks.","cn":"孩子们吃零食吃饱了。"}},{"en":"if somebody fills an order or a prescription, they give the customer what they have asked for","cn":"（按订单）供应；交付（订货）；（按药方）配药","g":"[transitive]","sc":"an order","ex":{"en":"We need to reduce the time taken to fill orders.","cn":"我们需要减少完成订单所需的时间。"}},{"en":"as much of something/somebody as you are willing to accept","cn":"填满…的量；足够…的量","ex":{"en":"I've had my fill of entertaining for one week.","cn":"我已足足享受了一周的款待。"},"pos":"noun"},{"en":"as much as you can eat/drink","cn":"吃饱的量；喝足的量","ex":{"en":"All we had was what was left after the guests had eaten their fill.","cn":"我们所拥有的只是客人吃饱后剩下的东西。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)装满;(使)注满;(使)充满","en":"If you fill a container or area, or if it fills, an amount of something enters it that is enough to make it full.","ex":{"en":"Fill a saucepan with water and bring to a slow boil","cn":"往平底锅里加满水,小火煮沸。"}},{"pos":"VERB 动词","cn":"挤满;占满;充塞","en":"If something fills a space, it is so big, or there are such large quantities of it, that there is very little room left.","ex":{"en":"He cast his eyes at the rows of cabinets that filled the enormous work area","cn":"他把目光投向那一排排挤占了巨大工作空间的柜子。"}},{"pos":"VERB 动词","cn":"填塞，填平(缝隙或孔洞)","en":"If you fill a crack or hole, you put a substance into it in order to make the surface smooth again.","ex":{"en":"Fill small holes with wood filler in a matching colour","cn":"用颜色相配的木质填料填平小孔。"}},{"pos":"VERB 动词","cn":"布满;使遍及","en":"If a sound, smell, or light fills a space, or the air, it is very strong or noticeable.","ex":{"en":"In the parking lot of the school, the siren filled the air","cn":"警报声响彻学校停车场。"}},{"pos":"VERB 动词","cn":"使强烈地感到;(感情)充盈于","en":"If something fills you with an emotion, or if an emotion fills you, you experience this emotion strongly.","ex":{"en":"I admired my father, and his work filled me with awe and curiosity","cn":"我很钦佩父亲，并对他的工作充满了敬畏和好奇。"}},{"pos":"VERB 动词","cn":"度过，打发(时间)","en":"If you fill a period of time with a particular activity, you spend the time in this way.","ex":{"en":"If she wants a routine to fill her day, let her do community work.","cn":"如果她想做些日常的事务来打发白天的时间，就让她去做社区工作吧。"}},{"pos":"VERB 动词","cn":"满足(需要);弥补(空白)","en":"If something fills a need or a gap, it puts an end to this need or gap by existing or being active.","ex":{"en":"...properly organized and staffed day-care programs fill a need which allows family structures to remain intact","cn":"组织得当、人员配备齐整的日托中心满足了人们的需求，保持了家庭结构不受破坏。"}},{"pos":"VERB 动词","cn":"充任;担任;发挥","en":"If something fills a role, position, or function, they have that role or position, or perform that function, often successfully.","ex":{"en":"Dena was filling the role of diplomat's wife with the skill she had learned over the years.","cn":"德娜利用她多年来学到的处事技巧扮演着外交家妻子的角色。"}},{"pos":"VERB 动词","cn":"填补(职位空缺)","en":"If a company or organization fills a job vacancy, they choose someone to do the job. If someone fills a job vacancy, they accept a job that they have been offered.","ex":{"en":"One problem not mentioned is the unemployed may not have the skills to fill the vacancies on offer","cn":"一个没有提及的问题是，失业人员也许缺乏填补所提供的空职的技能。"}},{"pos":"VERB 动词","cn":"使吃饱;填饱…的肚子","en":"If you fill yourself with food, you eat so much that you do not feel hungry.","ex":{"en":"They joked and drank coffee and filled themselves with chocolate cake.","cn":"他们开着玩笑，喝着咖啡，尽情地吃着巧克力蛋糕。"}},{"pos":"VERB 动词","cn":"使爆满;使满座;使座无虚席","en":"A play, film, or performer that fills a theatre, concert hall, or cinema attracts a very large audience.","ex":{"en":"Children are enthralled by his stories; he has been known to fill theatre halls in Australia.","cn":"孩子们为他的故事所着迷;众所周知他在澳大利亚总是场场爆满。"}},{"pos":"VERB 动词","cn":"补(牙)","en":"When a dentist fills someone's tooth, he or she puts a filling in it.","ex":{"en":"It is almost impossible to find a dentist who will fill a tooth on the National Health.","cn":"几乎不可能找到一位愿意接受国民医疗保健来补牙的医师。"}},{"pos":"VERB 动词","cn":"(按订单)供货;(按药方)配药","en":"If you fill an order or a prescription, you provide the things that are asked for.","ex":{"en":"A pharmacist can fill any prescription if, in his or her judgment, the prescription is valid.","cn":"只要药剂师认定处方有效就可按方配药。"}},{"pos":"PHRASE 短语","cn":"受够;对…感到厌烦","en":"If you have had your fill of something, you have had enough of it, and do not want to experience it any more or do it any more.","ex":{"en":"We feel that we have had our fill of disappointments and emotional upsets.","cn":"我们觉得已经受够了失望和情绪困扰。"}},{"pos":"","cn":"","en":"to fill the bill→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"填，填写(表格等)","en":"If you fill in a form or other document requesting information, you write information in the spaces on it.","ex":{"en":"If you want your free copy of the Patients' Charter fill this form in","cn":"如果想要一份免费的《病人约章》，就把这张表填一下。"}},{"pos":"PHRASAL VERB 短语动词","cn":"涂满，填充(图形)","en":"If you fill in a shape, you cover the area inside the lines with colour or shapes so that none of the background is showing.","ex":{"en":"When you have both filled in your patterns, you may want to share these with each other","cn":"两人都把图案填好色后，不妨互相交换着看一下。"}},{"pos":"PHRASAL VERB 短语动词","cn":"告诉…详情;向…详述","en":"If you fill someone in, you give them more details about something that you know about.","ex":{"en":"I didn't give Reid all the details yet — I'll fill him in","cn":"我还没有告诉里德所有详情——我会讲给他听的。"}},{"pos":"PHRASAL VERB 短语动词","cn":"临时补缺;暂代","en":"If you fill in for someone, you do the work or task that they normally do because they are unable to do it.","ex":{"en":"Vice-presidents' wives would fill in for first ladies.","cn":"副总统夫人们将临时代替各位第一夫人。"}},{"pos":"PHRASAL VERB 短语动词","cn":"消磨,打发(时间)","en":"If you are filling in time, you are using time that is available by doing something that is not very important.","ex":{"en":"That's not a career. She's just filling in time until she gets married.","cn":"那算不上什么事业，她只不过是在嫁人之前打发一下时间而已。"}},{"pos":"PHRASAL VERB 短语动词","cn":"填，填写(表格等)","en":"If you fill out a form or other document requesting information, you write information in the spaces on it.","ex":{"en":"Fill out the application carefully, and keep copies of it.","cn":"仔细填写申请表，并且保存副本。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(很瘦的人)发胖,长胖","en":"If a fairly thin person fills out, they become fatter.","ex":{"en":"A girl may fill out before she reaches her full height.","cn":"女孩子在长足个头之前可能会发胖。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(使)吃饱;填饱(…的)肚子","en":"If you fill up or fill yourself up with food, you eat so much that you do not feel hungry.","ex":{"en":"Fill up on potatoes, bread and pasta, which are high in carbohydrate and low in fat","cn":"用碳水化合物含量高、脂肪含量低的土豆、面包和意大利面食填饱肚子。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(食物)使易饱，使有饱胀感","en":"A type of food that fills you up makes you feel that you have eaten a lot, even though you have only eaten a small amount.","ex":{"en":"Potatoes fill us up without overloading us with calories.","cn":"吃土豆容易让我们有一种饱胀感，又不会摄入过多的热量。"}},{"pos":"","cn":"","en":"相关词组：fill in fill out fill up"}]},"examples":[{"en":"More nurseries will be built to fill the need for high-quality child care.","cn":"将建立更多的托儿所以满足高质量儿童保育的需要。"},{"en":"How do you fill your day now that you've retired?","cn":"现在你已退休了，怎样打发你的日子？"}]},"fights":{"lemma":"fight","media":{"uk":"media/uk/fight__gb_1.mp3","us":"media/us/fight__us_1.mp3"}},"first-class":{"oxford":{"phon":"ˌfɜːst ˈklɑːs","pos":"adverb","senses":[{"en":"using the best and most expensive seats or accommodation in a train, plane or ship","cn":"乘坐头等座位（或车厢、舱）","ex":{"en":"to travel first class","cn":"乘头等舱旅行"}},{"en":"(in the UK) by the quickest form of mail","cn":"（英国）按最快投递邮件","ex":{"en":"I sent the package first class on Monday.","cn":"我于星期一以第一类邮件寄出包裹。"}},{"en":"(in the US) by the class of mail that is used for letters","cn":"（美国）按第一类邮件"},{"en":"the best and most expensive seats or accommodation on a train, plane or ship","cn":"头等座位（或车厢、舱）","ex":{"en":"There is more room in first class.","cn":"头等舱更宽敞。"},"pos":"noun"},{"en":"(in the UK) the class of mail that is delivered most quickly","cn":"第一类邮件（在英国投递最快的邮件）","ex":{"en":"First class costs more.","cn":"第一类邮件邮资较高。"},"pos":"noun"},{"en":"(in the US) the class of mail that is used for letters","cn":"第一类邮件（在美国用于投递信件和明信片）","pos":"noun"},{"en":"the highest standard of degree given by a British university","cn":"一级优等学位（英国大学学位等级）","pos":"noun"},{"en":"in the best group; of the highest standard","cn":"第一流的；一级的；一等的；最优的","g":"[usually before noun]","ex":{"en":"a first-class novel","cn":"最佳小说"},"pos":"adjective"},{"en":"connected with the best and most expensive way of travelling on a train, plane or ship","cn":"（座位、车厢、舱位）头等的","g":"[only before noun]","ex":{"en":"first-class rail travel","cn":"乘头等车厢旅行"},"pos":"adjective"},{"en":"(in the UK) connected with letters, packages, etc. that are delivered most quickly, or that cost more to send","cn":"第一类的（英国邮件等级，投递最快）","g":"[only before noun]","ex":{"en":"first-class mail/post/postage/stamps","cn":"第一类邮件／邮资／邮票"},"pos":"adjective"},{"en":"used to describe a university degree of the highest class from a British university","cn":"一级优等的（英国大学学位）","g":"[only before noun]","ex":{"en":"She was awarded a first-class degree in English.","cn":"她获得一级优等英语学位。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一流的;极好的;最优的","en":"If you describe something or someone as first-class, you mean that they are extremely good and of the highest quality.","ex":{"en":"The food was first-class","cn":"食物一流。"}},{"pos":"ADJ 形容词","cn":"甲级的;一等的;优等的","en":"You use first-class to describe something that is in the group that is considered to be of the highest standard.","ex":{"en":"He officially announced his retirement from first-class cricket yesterday","cn":"他昨天正式宣布退出甲级板球赛。"}},{"pos":"ADJ 形容词","cn":"(车厢、船舱、机舱)头等的，一等的","en":"First-class accommodation on a train, aeroplane, or ship is the best and most expensive type of accommodation.","ex":{"en":"...a first-class carriage","cn":"头等车厢"}},{"pos":"ADJ 形容词","cn":"(英)优先投递的，第一类的;(美)第一类邮件的(适用于信函和明信片)","en":"In Britain, first-class postage is the quicker and more expensive type of postage. In the United States, first-class postage is the type of postage that is used for sending letters and postcards.","ex":{"en":"Two first class stamps, please","cn":"买两张第一类邮件邮票。"}}]},"media":{"uk":"media/uk/first_class_1_gb_1.mp3","us":"media/us/first_class_1_us_1.mp3"},"examples":[{"en":"I know a place where the food is first-class.","cn":"我知道有一个品尝一流美食的地方。"},{"en":"She was awarded a first-class degree in English.","cn":"她获得一级优等英语学位。"}]},"fight":{"media":{"uk":"media/uk/fight__gb_1.mp3","us":"media/us/fight__us_1.mp3"},"oxford":{"phon":"faɪt","pos":"verb","senses":[{"en":"to take part in a war or battle against an enemy","cn":"打仗；战斗；作战","g":"[intransitive, transitive]","sc":"in war/battle","ex":{"en":"soldiers trained to fight","cn":"受过作战训练的士兵"}},{"en":"to struggle physically with somebody","cn":"搏斗；打斗；打架","g":"[intransitive, transitive]","sc":"struggle/hit","ex":{"en":"My little brothers are always fighting.","cn":"我的小弟弟们总在打架。"}},{"en":"to have an argument with somebody about something","cn":"争辩","g":"[intransitive]","sc":"argue","ex":{"en":"I remember lying in bed listening to my parents fighting.","cn":"我记得躺在床上听我父母吵架。"}},{"en":"to try hard to stop, deal with or oppose something bad or something that you disagree with","cn":"极力反对；与…斗争","g":"[transitive, intransitive]","sc":"oppose","ex":{"en":"We will continue to fight for as long as it takes.","cn":"无论需时多久，我们都必定斗争到底。"}},{"en":"to try very hard to get something or to achieve something","cn":"努力争取；为…斗争","g":"[intransitive, transitive]","sc":"try to get/do something","ex":{"en":"We fought for years before we got the recognition we deserved.","cn":"我们奋斗了多年才得到应有的认可。"}},{"en":"to take part in a contest against somebody","cn":"参加（竞赛）；竞争","g":"[transitive, intransitive]","sc":"in contest","ex":{"en":"to fight an election/a campaign","cn":"参加竞选／争取权益的运动"}},{"en":"to take part in a boxing match","cn":"参加拳击比赛","g":"[intransitive, transitive]","sc":"in boxing","ex":{"en":"Doctors fear he may never fight again.","cn":"医生认为他可能再也不能重返拳坛了。"}},{"en":"to try to get what you want in court","cn":"（为…）和某人打官司","g":"[transitive, intransitive]","sc":"law","ex":{"en":"He fought his wife for custody of the children.","cn":"他和妻子打官司争取孩子的监护权。"}},{"en":"a struggle against somebody/something using physical force","cn":"搏斗；打斗；打架","g":"[countable]","lab":"figurative","sc":"struggle","ex":{"en":"a street/gang fight","cn":"街头／帮派打斗"},"pos":"noun"},{"en":"an occasion when people fight as a sport, especially in boxing","cn":"（尤指拳击）比赛","sc":"sport","ex":{"en":"They got tickets to watch the world title fight.","cn":"他们弄到了观看世界拳王争霸赛的票。"},"pos":"noun"},{"en":"an argument about something","cn":"争论；争吵","g":"[countable]","lab":"especially North American English","sc":"argument","ex":{"en":"Paul and I had this terrible fight last night.","cn":"保罗和我昨晚发生了一场可怕的争吵。"},"pos":"noun"},{"en":"the work of trying to destroy, prevent or achieve something","cn":"斗争","g":"[singular]","sc":"trying to get/do something","ex":{"en":"the fight against crime/terrorism","cn":"打击犯罪／恐怖主义"},"pos":"noun"},{"en":"a competition or an act of competing, especially in a sport","cn":"（尤指体育运动）比赛，竞赛","g":"[singular]","sc":"competition","ex":{"en":"The team put up a good fight (= they played well) but were finally beaten.","cn":"这个队打得不错，但最后还是输了。"},"pos":"noun"},{"en":"a battle, especially for a particular place or position","cn":"战斗（尤指为夺取某一地方或位置）","g":"[countable]","sc":"battle/war","ex":{"en":"In the fight for Lemburg, the Austrians were defeated.","cn":"在争夺伦贝格的战斗中，奥地利人战败了。"},"pos":"noun"},{"en":"the desire or ability to keep fighting for something","cn":"斗志；战斗力","g":"[uncountable]","sc":"desire to fight","ex":{"en":"In spite of many defeats, they still had plenty of fight left in them.","cn":"他们尽管多次失败，但仍然斗志昂扬。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"与…作斗争;坚决反对","en":"If you fight something unpleasant, you try in a determined way to prevent it or stop it happening.","ex":{"en":"Mother Teresa is an elderly nun who has devoted her life to fighting poverty","cn":"德肋撒嬷嬷是一位毕生致力于消除贫困事业的年迈修女。"}},{"pos":"VERB 动词","cn":"(为…而)斗争;努力争取","en":"If you fight for something, you try in a determined way to get it or achieve it.","ex":{"en":"Our Government should be fighting for an end to food subsidies","cn":"我们政府应该努力废止食物补贴。"}},{"pos":"V-RECIP 相互动词","cn":"进行(战斗、对抗等);打(仗)","en":"If an army or group fights a battle with another army or group, they oppose each other with weapons. You can also say that two armies or groups fight a battle.","ex":{"en":"The two men fought a battle over land and water rights","cn":"这两个男人为土地和水的使用权发生了争斗。"}},{"pos":"VERB 动词","cn":"参战;作战;打仗","en":"If a person or army fights in a battle or a war, they take part in it.","ex":{"en":"He fought in the war and was taken prisoner by the Americans","cn":"他参了战，后被美国人俘虏。"}},{"pos":"V-RECIP 相互动词","cn":"(和…)打架;(同…)打斗;(与…)搏斗","en":"If one person fights with another, or fights them, the two people hit or kick each other because they want to hurt each other. You can also say that two people fight .","ex":{"en":"As a child she fought with her younger sister","cn":"她小时候会和妹妹打架。"}},{"pos":"V-RECIP 相互动词","cn":"(和…)争吵;(同…)吵架;(与…)争论","en":"If one person fights with another, or fights them, they have an angry disagreement or quarrel. You can also say that two people fight .","ex":{"en":"She was always arguing with him and fighting with him","cn":"她总是跟他争辩吵嘴。"}},{"pos":"VERB 动词","cn":"努力辟出(一条路)","en":"If you fight your way to a place, you move towards it with great difficulty, for example because there are a lot of people or obstacles in your way.","ex":{"en":"I fought my way into a carriage just before the doors closed","cn":"我刚挤进车厢，车门就关上了。"}},{"pos":"N-COUNT 可数名词","cn":"(一场)拳击赛","en":"A fight is a boxing match.","ex":{"en":"This was Hyer's last fight, for no one else challenged him","cn":"这是海尔的最后一场比赛，因为再没有人向他发起挑战。"}},{"pos":"VERB 动词","cn":"参加拳击赛","en":"To fight means to take part in a boxing match.","ex":{"en":"In a few hours' time one of the world's most famous boxers will be fighting in Britain for the first time","cn":"几个小时后，世界最著名的拳击手之一将开始其在英国的首场比赛。"}},{"pos":"VERB 动词","cn":"参加(竞选以期获胜)","en":"If you fight an election, you are a candidate in the election and try to win it.","ex":{"en":"The former party treasurer helped raise almost £40 million to fight the election campaign.","cn":"该党的前任财政部长帮助筹集了近 4,000 万英镑用于竞选。"}},{"pos":"N-COUNT 可数名词","cn":"竞赛;比赛","en":"You can use fight to refer to a contest such as an election or a sports match.","ex":{"en":"...the fight for power between the two parties.","cn":"两党间的权力之争"}},{"pos":"VERB 动词","cn":"进行(诉讼、辩护等);打(官司)","en":"If you fight a case or a court action, you make a legal case against someone in a very determined way, or you put forward a defence when a legal case is made against you.","ex":{"en":"Watkins sued the Army and fought his case in various courts for 10 years","cn":"沃特金斯将军队诉至法院，并在各级法庭打了 10 年的官司。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"斗志;战斗力","en":"Fight is the desire or ability to keep fighting.","ex":{"en":"I thought that we had a lot of fight in us.","cn":"我觉得我们斗志高昂。"}},{"pos":"VERB 动词","cn":"努力克制，竭力抑制(感情或欲望)","en":"If you fight an emotion or desire, you try very hard not to feel it, show it, or act on it, but do not always succeed.","ex":{"en":"I desperately fought the urge to giggle","cn":"我拼命地想忍住笑。"}},{"pos":"PHRASE 短语","cn":"呼吸困难;吸气费力","en":"If you fight for breath, you try to breathe but find it very difficult."},{"pos":"PHRASE 短语","cn":"经过努力才能成功的机会;需要极大好运的机会","en":"If you have a fighting chance of doing or achieving something, it is possible that you will do or achieve it, but only if you make a great effort or are very lucky.","ex":{"en":"When they didn't shoot at me right away, I figured I had a fighting chance.","cn":"当他们没有立即向我开枪时，我估摸自己还有一线生机。"}},{"pos":"PHRASE 短语","cn":"非常健康;极为强健","en":"If you describe someone as fighting fit, you are emphasizing that they are very fit or healthy.","ex":{"en":"After a good night's sleep I feel fighting fit again.","cn":"昨夜睡得很香，我又觉得自己精力充沛了。"}},{"pos":"PHRASE 短语","cn":"与死神殊死搏斗;奋力求生","en":"Someone who is fighting for their life is making a great effort to stay alive, either when they are being physically attacked or when they are very ill.","ex":{"en":"He is still fighting for his life in hospital.","cn":"他仍在医院与死神搏斗。"}},{"pos":"","cn":"","en":"to fight a losing battle→see: ;"},{"pos":"","cn":"","en":"fight to the finish→see: ;"},{"pos":"","cn":"","en":". to fight fire with fire→see: ;"},{"pos":"","cn":"","en":". to fight shy→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"奋力抵抗;反击;还击","en":"If you fight back against someone or something that is attacking or harming you, you resist them actively or attack them.","ex":{"en":"The teenage attackers fled when the two men fought back","cn":"当那两名男子还击时，袭击他们的少年逃之夭夭。"}},{"pos":"PHRASAL VERB 短语动词","cn":"强忍住，抑制住(感情或欲望)","en":"If you fight back an emotion or a desire, you try very hard not to feel it, show it, or act on it.","ex":{"en":"She fought back the tears.","cn":"她强忍住眼泪。"}},{"pos":"PHRASAL VERB 短语动词","cn":"强忍住，抑制住(感情或欲望)","en":"If you fight down an emotion or a desire, you try very hard not to feel it, show it, or act on it.","ex":{"en":"Meg fought down the desire to run","cn":"梅格极力忍住不跑。"}},{"pos":"PHRASAL VERB 短语动词","cn":"抵抗，战胜(疾病);摆脱(不快)","en":"If you fight off something, for example an illness or an unpleasant feeling, you succeed in getting rid of it and in not letting it overcome you.","ex":{"en":"Unfortunately these drugs are quite toxic and hinder the body's ability to fight off infection","cn":"可惜的是，这些药物毒性很大，会削弱身体对感染的抵抗力。"}},{"pos":"PHRASAL VERB 短语动词","cn":"击退;打退","en":"If you fight off someone who has attacked you, you fight with them, and succeed in making them go away or stop attacking you.","ex":{"en":"The woman fought off the attacker.","cn":"这名女子打跑了袭击她的人。"}},{"pos":"PHR-V-RECIP 相互动词短语","cn":"在…上一争高下;通过比出胜负解决","en":"If two people or groups fight something out, they fight or argue until one of them wins.","ex":{"en":"Instead of retaliating, he walks away leaving his team-mates to fight it out","cn":"他没有以牙还牙，而是径直走开，让队友去争出个结果。"}},{"pos":"","cn":"","en":"相关词组：fight back fight down fight off fight out"}]},"examples":[{"en":"The residents are fighting tooth and nail to stop the new development.","cn":"居民为制止新的建房开发计划正在全力以赴进行斗争。"},{"en":"They hadn't reached any agreement so we left them to fight it out.","cn":"他们未有达成协议，所以我们让他们争出个结果。"}]},"filing":{"media":{"uk":"media/uk/filing__gb_1.mp3","us":"media/us/filing__us_1.mp3"},"oxford":{"phon":"ˈfaɪlɪŋ","pos":"noun","senses":[{"en":"the act of putting documents, letters, etc. into a file","cn":"存档；归档","g":"[uncountable]"},{"en":"something that is placed in an official record","cn":"存档档案；归档记录","g":"[countable]","lab":"especially North American English","ex":{"en":"a bankruptcy filing","cn":"破产档案"}},{"en":"very small pieces of metal, made when a larger piece of metal is filed","cn":"锉屑","g":"[plural]","ex":{"en":"iron filings","cn":"铁锉屑"}}]},"examples":[{"en":"a bankruptcy filing","cn":"破产档案"},{"en":"iron filings","cn":"铁锉屑"}],"base":"file"},"fibre":{"media":{"uk":"media/uk/fibre__gb_1.mp3","us":"media/us/fibre__us_1.mp3"},"oxford":{"phon":"ˈfaɪbə(r)","pos":"noun","senses":[{"en":"the part of food that helps to keep a person healthy by keeping the bowels working and moving other food quickly through the body","cn":"（食物中的）纤维素","g":"[uncountable]","ex":{"en":"dietary fibre","cn":"饮食纤维素"}},{"en":"a material such as cloth or rope that is made from a mass of natural or artificial threads","cn":"（织物或绳等）纤维制品","g":"[countable, uncountable]","ex":{"en":"nylon and other man-made fibres","cn":"尼龙和其他人造纤维制品"}},{"en":"one of the many thin threads that form body tissue, such as muscle, and natural materials, such as wood and cotton","cn":"（人或动物身体组织及天然物质的）纤维","g":"[countable]","lab":"literary","ex":{"en":"cotton/wood/nerve/muscle fibres","cn":"棉／木／神经／肌肉纤维"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指制织物或绳索的天然或人造)纤维，丝","en":"A fibre is a thin thread of a natural or artificial substance, especially one that is used to make cloth or rope.","ex":{"en":"If you look at the paper under a microscope, you will see the fibres.","cn":"如果在显微镜下观察纸张，就会看见纤维。"}},{"pos":"N-VAR 可变名词","cn":"织物；纤维制品","en":"A particular fibre is a type of cloth or other material that is made from or consists of threads.","ex":{"en":"The ball is made of rattan — a natural fibre.","cn":"这个球是由一种天然纤维——省藤制成的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(植物或种子中的)纤维,食物纤维","en":"Fibre consists of the parts of plants or seeds that your body cannot digest. Fibre is useful because it makes food pass quickly through your body.","ex":{"en":"Most vegetables contain fibre.","cn":"大多数蔬菜都含有纤维。"}},{"pos":"N-COUNT 可数名词","cn":"(神经或肌肉)纤维","en":"A fibre is a thin piece of flesh like a thread which connects nerve cells in your body or which muscles are made of.","ex":{"en":"...the nerve fibres.","cn":"神经纤维"}},{"pos":"PHRASE 短语","cn":"深切地;全身心地","en":"If you say that you feel something with every fibre of your being, you mean that you feel it very deeply.","ex":{"en":"I wanted to be an actress with every fibre of my being.","cn":"我一心一意想去做演员。"}}]},"examples":[{"en":"Dried fruits are especially high in fibre.","cn":"干水果的纤维素含量尤其高。"},{"en":"( literary ) She loved him with every fibre of her being.","cn":"她一心一意地爱他。"}]},"final":{"media":{"uk":"media/uk/final__gb_1.mp3","us":"media/us/final__us_1.mp3"},"oxford":{"phon":"ˈfaɪnl","pos":"adjective","senses":[{"en":"being or happening at the end of a series of events, actions, statements, etc.","cn":"最终的；最后的","g":"[only before noun]","ex":{"en":"his final act as party leader","cn":"他作为党的领袖所采取的最后行动"}},{"en":"being the result of a particular process","cn":"（指结果）最终的，最后的","g":"[only before noun]","ex":{"en":"I think you will be satisfied with the final product.","cn":"我想您会对最终产品感到满意。"}},{"en":"that cannot be argued with or changed","cn":"决定性的；不可改变的；最终的","ex":{"en":"The judge's decision is final.","cn":"法官的判决是最终判决。"}},{"en":"the last of a series of games or competitions, in which the winner is decided","cn":"决赛","g":"[countable]","ex":{"en":"She reached the final of the 100m hurdles.","cn":"她进入了 100 米跨栏的决赛。"},"pos":"noun"},{"en":"a series of games or performances that make up the last stage of a competition","cn":"决赛阶段","ex":{"en":"the 2022 World Cup Finals","cn":"2022 年世界杯决赛阶段"},"pos":"noun"},{"en":"the last exams taken by university students at the end of their final year","cn":"大学毕业考试","g":"[plural]","lab":"British English","ex":{"en":"to sit/take your finals","cn":"参加大学毕业考试"},"pos":"noun"},{"en":"an exam taken by school, university or college students at the end of a semester or quarter, usually in a topic that they will not study again","cn":"期终考试；期终结业考试","g":"[countable]","lab":"North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(出现次序)最后的，末尾的","en":"In a series of events, things, or people, the final one is the last one.","ex":{"en":"Astronauts will make a final attempt today to rescue a communications satellite from its useless orbit","cn":"今天宇航员将会做最后一次尝试,力图把一颗通信卫星从无效的轨道上抢救下来。"}},{"pos":"ADJ 形容词","cn":"(发生时间)最终的，末了的","en":"Final means happening at the end of an event or series of events.","ex":{"en":"You must have been on stage until the final curtain","cn":"你肯定在台上一直呆到了演出结束。"}},{"pos":"ADJ 形容词","cn":"无比的;极度的","en":"You can use final to emphasize that a situation has a particular quality to a very great or severe degree.","ex":{"en":"Only a few go through the final humiliation of meeting the bailiff at the door.","cn":"很少有人经受执达官上门的奇耻大辱。"}},{"pos":"ADJ 形容词","cn":"(决定)不可更改的;(权威)毋庸置疑的","en":"If a decision or someone's authority is final, it cannot be changed or questioned.","ex":{"en":"The judges' decision is final","cn":"法官的判决不可更改。"}},{"pos":"N-COUNT 可数名词","cn":"决赛","en":"The final is the last game or contest in a series and decides who is the winner.","ex":{"en":"...the Scottish Cup Final","cn":"苏格兰杯的决赛"}},{"pos":"N-PLURAL 复数名词","cn":"(锦标赛的)决赛阶段比赛","en":"The finals of a sporting tournament consist of a smaller tournament that includes only players or teams that have won earlier games. The finals decide the winner of the whole tournament.","ex":{"en":"Poland know they have a chance of qualifying for the World Cup Finals.","cn":"波兰队知道他们有机会获得参加世界杯决赛的资格。"}},{"pos":"N-PLURAL 复数名词","cn":"(大学或学院的)课程终结考试，期终考试","en":"When a student takes his or her finals, he or she takes the last and most important examinations in a university or college course.","ex":{"en":"Anna sat her finals in the summer.","cn":"安娜在夏天参加了课程终结考试。"}}]},"examples":[{"en":"She reached the final of the 100m hurdles.","cn":"她取得了 100 米跨栏的决赛权。"},{"en":"No one could have predicted the final outcome.","cn":"谁也没有预想到最终结果会是这样。"}]},"first":{"media":{"uk":"media/uk/first__gb_1.mp3","us":"media/us/first__us_1.mp3"},"oxford":{"phon":"fɜːst","pos":"determiner, ordinal number","senses":[{"en":"happening or coming before all other similar things or people; 1st","cn":"第一","ex":{"en":"her first husband","cn":"她的第一任丈夫"}},{"en":"the most important or best","cn":"最重要的；首要的；最优秀的","ex":{"en":"Your first duty is to your family.","cn":"你首先应对家庭尽责。"}},{"en":"before anyone or anything else; at the beginning","cn":"首先；第一；最初","ex":{"en":"‘Do you want a drink?’ ‘I'll finish my work first.’","cn":"“你想喝杯饮料吗？”“我要先完成工作。”"},"pos":"adverb"},{"en":"for the first time","cn":"第一次；首次","ex":{"en":"When did you first meet him?","cn":"你和他初次见面是何时？"},"pos":"adverb"},{"en":"used to introduce the first of a list of points you want to make in a speech or piece of writing","cn":"（用于列举）第一，首先","ex":{"en":"This method has two advantages: first it is cheaper and second it is quicker.","cn":"这个方法有两个优点：一是更便宜，二是较快。"},"pos":"adverb"},{"en":"used to emphasize that you are determined not to do something","cn":"（强调不愿意）宁可，宁愿","ex":{"en":"She swore that she wouldn't apologize—she'd die first!","cn":"她发誓决不道歉，宁死也不！"},"pos":"adverb"},{"en":"the person or thing that comes or happens before all other similar people or things","cn":"第一个人（或事物）","ex":{"en":"I was the first in my family to go to college.","cn":"我是我们家第一个大学生。"},"pos":"noun"},{"en":"the earliest","cn":"最早","g":"[singular]","ex":{"en":"The first I heard about the wedding (= the first time I became aware of it) was when I saw it in the local paper.","cn":"我最初知道他们结婚的消息是从当地报纸上看到的。"},"pos":"noun"},{"en":"the most likely","cn":"最有可能","ex":{"en":"I'd be the first to admit (= I will most willingly admit) I might be wrong.","cn":"我非常愿意承认我可能错了。"},"pos":"noun"},{"en":"an important achievement, event, etc., never done or experienced before","cn":"空前的成就；前所未有的事情","g":"[countable, usually singular]","ex":{"en":"We went on a cruise, a first for both of us.","cn":"我俩都是平生第一次去海上旅游。"},"pos":"noun"},{"en":"the lowest gear on a car, bicycle, etc. that you use when you are moving slowly","cn":"（汽车、自行车等的）一挡，最低挡","g":"[uncountable]","ex":{"en":"He stuck the car in first and revved.","cn":"他挂上了一挡，开动了汽车。"},"pos":"noun"},{"en":"the highest level of university degree at British universities","cn":"（英国大学学位）最高成绩，优等成绩","g":"[countable]","ex":{"en":"She got a first in maths at Exeter.","cn":"她在埃克塞特大学毕业，获数学一级优等学位。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"最早的;最先的;第一位的","en":"The first thing, person, event, or period of time is the one that happens or comes before all the others of the same kind.","ex":{"en":"She lost 16 pounds in the first month of her diet.","cn":"她节食的头一个月就减掉了16磅。"}},{"pos":"ADV 副词","cn":"最早;最先;先","en":"If you do something first, you do it before anyone else does, or before you do anything else.","ex":{"en":"I do not remember who spoke first, but we all expressed the same opinion","cn":"我不记得是谁最先发言的，但我们全都表达了相同的看法。"}},{"pos":"ORD 序数词","cn":"第一(次)的;首(次)的","en":"When something happens or is done for the first time, it has never happened or been done before.","ex":{"en":"This is the first time she has experienced disappointment","cn":"这是她第一次感受到失望。"}},{"pos":"N-SING 单数名词","cn":"首次出现的事物;首例","en":"An event that is described as a first has never happened before and is important or exciting.","ex":{"en":"It is a first for New York. An outdoor exhibition of Fernando Botero's sculpture on Park Avenue.","cn":"在公园大道上露天展出费尔南多·博特罗的雕塑，这在纽约还是破天荒的事。"}},{"pos":"PRON 代词","cn":"第一次;首次","en":"The first you hear of something or the first you know about it is the time when you first become aware of it.","ex":{"en":"We heard it on the TV last night — that was the first we heard of it","cn":"昨晚我们在电视上听到了这件事——那是我们头回听说。"}},{"pos":"ADV 副词","cn":"最初;起初;开始","en":"You use first when you are talking about what happens in the early part of an event or experience, in contrast to what happens later.","ex":{"en":"When he first came home he wouldn't say anything about what he'd been doing.","cn":"刚回到家时，他只字不提自己一直在做什么。"}},{"pos":"ADV 副词","cn":"(强调不愿意做某事)宁可，宁愿","en":"In order to emphasize your determination not to do a particular thing, you can say that rather than do it, you would do something else first .","ex":{"en":"Marry that fat son of a fat cattle dealer? She would die first!","cn":"嫁给那个大腹便便的牛贩子的胖儿子？她宁愿去死！"}},{"pos":"ADV 副词","cn":"(用于列举条目)第一，首先","en":"You use first when you are about to give the first in a series of items.","ex":{"en":"Certain guidelines can be given. First, have a heating engineer check the safety of the system.","cn":"可以提供一些指导原则：第一，找位供暖工程师检查系统的安全性。"}},{"pos":"ORD 序数词","cn":"(一列中)离得最近的，最前面的","en":"The first thing, person, or place in a line is the one that is nearest to you or nearest to the front.","ex":{"en":"Before him, in the first row, sat the President","cn":"在他面前第一排坐着总统。"}},{"pos":"ORD 序数词","cn":"首要的;头等的","en":"You use first to refer to the best or most important thing or person of a particular kind.","ex":{"en":"The first duty of any government must be to protect the interests of the taxpayers","cn":"任何政府的首要职责都必须是保护纳税人的利益。"}},{"pos":"ORD 序数词","cn":"(用于工作或职位的头衔中)最高的","en":"First is used in the title of the job or position of someone who has a higher rank than anyone else with the same basic job title.","ex":{"en":"...the First Lord of the Admiralty.","cn":"海军大臣"}},{"pos":"N-COUNT 可数名词","cn":"(英国大学的)优等学位，一级荣誉学位","en":"In British universities, a first is an honours degree of the highest standard.","ex":{"en":"...an Oxford Blue who took a First in Constitutional History.","cn":"获得宪法史优等学位的牛津大学校队运动员"}},{"pos":"PHRASE 短语","cn":"第一;首先","en":"You use first of all to introduce the first of a number of things that you want to say.","ex":{"en":"The cut in the interest rates has not had very much impact in California for two reasons. First of all, banks are still afraid to loan.","cn":"降息在加利福尼亚并未产生多大影响，原因有二。首先，银行仍然不敢放贷。"}},{"pos":"PHRASE 短语","cn":"最初;起初;开始时","en":"You use at first when you are talking about what happens in the early stages of an event or experience, or just after something else has happened, in contrast to what happens later.","ex":{"en":"At first, he seemed surprised by my questions","cn":"起初，他似乎对我的问题感到惊讶。"}},{"pos":"PHRASE 短语","cn":"居于首要地位;占据头等位置","en":"If you say that someone or something comes first for a particular person, you mean they treat or consider that person or thing as more important than anything else.","ex":{"en":"There's no time for boyfriends, my career comes first.","cn":"我没时间交男朋友，事业对我来说是第一位的。"}},{"pos":"PHRASE 短语","cn":"先到先接待;先到先供应;按先来后到对待","en":"You say 'first come first served' to indicate that a group of people or things will be dealt with or given something in the order in which they arrive.","ex":{"en":"There will be five buses, first come first served.","cn":"会有5辆巴士，先到先上。"}},{"pos":"PHRASE 短语","cn":"从最初;从一开始","en":"From the first means ever since something started.","ex":{"en":"You knew about me from the first, didn't you?","cn":"从一开始你就知道我，对吧？"}},{"pos":"PHRASE 短语","cn":"第一手地;直接;亲自","en":"If you learn or experience something at first hand, you experience it yourself or learn it directly rather than being told about it by other people.","ex":{"en":"He arrived in Natal to see at first hand the effects of the recent heavy fighting.","cn":"他来到纳塔尔亲自了解最近发生的激烈冲突造成的后果。"}},{"pos":"PHRASE 短语","cn":"对…一无所知;对…毫不知晓","en":"If you say that you do not know the first thing about something, you are emphasizing that you know absolutely nothing about it.","ex":{"en":"You don't know the first thing about farming.","cn":"你对种地一窍不通。"}},{"pos":"PHRASE 短语","cn":"第一;首先","en":"You use first off to introduce the first of a number of things that you want to say.","ex":{"en":"First off, huge apologies for last month's confusing report.","cn":"首先，要对上个月那篇交代不清的报道表示深深的歉意。"}},{"pos":"PHRASE 短语","cn":"视…为最重要;把…放在首位","en":"If you put someone or something first, you treat or consider them as more important than anything else.","ex":{"en":"Somebody has to think for the child and put him first.","cn":"必须有人替孩子着想，把他放在第一位。"}},{"pos":"PHRASE 短语","cn":"最重要的先做;最要紧的先处理","en":"You say 'first things first' when you are talking about something that should be done or dealt with before anything else because it is the most important.","ex":{"en":"Let's see if we can't find something to set the mood. First things first; some music.","cn":"看看我们能不能找点什么烘托一下气氛。当务之急：来点音乐吧。"}},{"pos":"","cn":"","en":"first and foremost→see: ;"}]},"examples":[{"en":"The first I heard about the wedding (= the first time I became aware of it) was when I saw it in the local paper.","cn":"我最初知道他们结婚的消息是从当地报纸上看到的。"},{"en":"At first I thought he was shy, but then I discovered he was just not interested in other people.","cn":"起先我以为他腼腆，后来才发现他对别人没兴趣。"}]},"fifteen":{"media":{"uk":"media/uk/fifteen__gb_1.mp3","us":"media/us/fifteen__us_1.mp3"},"oxford":{"phon":"ˌfɪfˈtiːn","pos":"","senses":[{"en":"15","cn":"十五"},{"en":"a team of Rugby Union players","cn":"十五人制橄榄球队；联合会橄榄球队","ex":{"en":"He's in the first fifteen.","cn":"他是联合会橄榄球队首发队员。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 15","en":"Fifteen is the number 15.","ex":{"en":"In India, there are fifteen official languages.","cn":"印度有 15 种官方语言。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(15 人的)英式橄榄球队","en":"A rugby-union team can be referred to as a fifteen ."}]},"examples":[{"en":"He's in the first fifteen.","cn":"他是联合会橄榄球球队队员。"},{"en":"a coastal village fifteen miles south of Tourane","cn":"土伦以南15英里的一个滨海村落"}]},"fitter":{"oxford":{"phon":"ˈfɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is to put together or repair equipment","cn":"装配工；修理工；钳工","ex":{"en":"a gas fitter","cn":"煤气设备装修工"}},{"en":"a person whose job is to cut and fit clothes or carpets, etc.","cn":"试衣裁缝；试样裁缝；地毯安装工"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"装配工;修理工;钳工","en":"A fitter is a person whose job is to put together, adjust, or install machinery or equipment.","ex":{"en":"George was a fitter at the shipyard.","cn":"乔治是造船厂的一名钳工。"}}]},"media":{"uk":"media/uk/fitter__gb_1.mp3","us":"media/us/fitter__us_1.mp3"},"examples":[{"en":"a gas fitter","cn":"煤气设备装修工"}]},"fines":{"lemma":"fine","media":{"uk":"media/uk/fine__gb_1.mp3","us":"media/us/fine__us_1.mp3"}},"finally":{"media":{"uk":"media/uk/finally__gb_1.mp3","us":"media/us/finally__us_1.mp3"},"oxford":{"phon":"ˈfaɪnəli","pos":"adverb","senses":[{"en":"after a long time, especially when there has been some difficulty or delay","cn":"终于；最终","ex":{"en":"The performance finally started half an hour late.","cn":"延迟了半小时以后演出终于开始了。"}},{"en":"used to introduce the last in a list of things","cn":"（用于列举）最后","ex":{"en":"And finally, I would like to thank you all for coming here today.","cn":"最后，我感谢大家今天的光临。"}},{"en":"in a way that ends all discussion about something","cn":"彻底地；决定性地","ex":{"en":"The matter was not finally settled until later.","cn":"这事后来才得到彻底解决。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"终于;总算","en":"You use finally to suggest that something happens after a long period of time, usually later than you wanted or expected it to happen.","ex":{"en":"The word was finally given for us to get on board","cn":"终于通知我们登乘了。"}},{"pos":"ADV 副词","cn":"最后地;末尾地","en":"You use finally to indicate that something is last in a series of actions or events.","ex":{"en":"The action slips from comedy to melodrama and finally to tragedy.","cn":"剧情从喜剧逐渐发展为情节剧，最后又演变为悲剧。"}},{"pos":"ADV 副词","cn":"(用于引出观点等)最后，最后要说的是","en":"You use finally in speech or writing to introduce a final point, question, or topic.","ex":{"en":"Finally, who needs the theatre?","cn":"最后要说的是，谁还需要剧院呢？"}}]},"examples":[{"en":"The performance finally started half an hour late.","cn":"延迟了半小时以后演出终于开始了。"},{"en":"When they finally arrived it was well past midnight.","cn":"他们最后到达时已是第二天的凌晨。"}]},"five":{"media":{"uk":"media/uk/five__gb_1.mp3","us":"media/us/five__us_1.mp3"},"oxford":{"phon":"faɪv","pos":"number","senses":[{"en":"5","cn":"五","ex":{"en":"There are only five cookies left.","cn":"只剩下五块曲奇了。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字)5","en":"Five is the number 5.","ex":{"en":"Eric Edward Bullus was born in Peterborough, the second of five children.","cn":"埃里克·爱德华·布勒斯出生于彼得伯勒，是 5 个孩子中的老二。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"墙手球(一种英式球类运动，球小而硬，戴手套或用球拍向场地的三面墙上击球)","en":"Fives is a British ball game in which you hit a small hard ball with a glove or bat against three walls of a court."}]},"examples":[{"en":"I can't read your writing — is this meant to be a five?","cn":"我看不懂你的笔迹 — 这个是不是五字？"},{"en":"The bulbs are planted in threes or fives (= groups of three or five).","cn":"这些鳞茎植物是三五株在一起种植的。"}]},"fish":{"media":{"img":["media/pic/fish_trout_comp.jpg","media/thumb/trout.jpg"],"uk":"media/uk/fish__gb_1.mp3","us":"media/us/fish__us_1.mp3"},"oxford":{"phon":"fɪʃ","pos":"noun","senses":[{"en":"a creature that lives in water, breathes through gills, and uses fins and a tail for swimming","cn":"鱼","g":"[countable]","ex":{"en":"They caught several fish.","cn":"他们捉到了几条鱼。"}},{"en":"the soft part of fish that is eaten as food","cn":"鱼肉","g":"[uncountable]","ex":{"en":"a regular diet of fresh fish","cn":"常吃鲜鱼"}},{"en":"to try to catch fish with nets, a fishing line, etc.","cn":"钓鱼；捕鱼","g":"[intransitive]","ex":{"en":"The trawler was fishing off the coast of Iceland.","cn":"拖网渔船在冰岛沿海捕鱼。"},"pos":"verb"},{"en":"to spend time fishing for pleasure","cn":"钓鱼；捕鱼","g":"[intransitive]","ex":{"en":"Let's go fishing this weekend.","cn":"咱们这个周末去钓鱼吧。"},"pos":"verb"},{"en":"to try to catch fish in the area of water mentioned","cn":"在…捕鱼（或钓鱼）","g":"[transitive]","ex":{"en":"They fished the loch for salmon.","cn":"他们在狭长海湾里钓鲑鱼。"},"pos":"verb"},{"en":"to search for something, using your hands","cn":"摸找","g":"[intransitive]","ex":{"en":"She fished around in her bag for her keys.","cn":"她在包里摸找钥匙。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鱼","en":"A fish is a creature that lives in water and has a tail and fins. There are many different kinds of fish.","ex":{"en":"I was chatting to an islander who had just caught a fish","cn":"我正在跟一个刚刚抓到一条鱼的岛民聊天。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(吃的)鱼，鱼肉","en":"Fish is the flesh of a fish eaten as food.","ex":{"en":"Does dry white wine go best with fish?","cn":"吃鱼时喝干白葡萄酒是最佳选择吗？"}},{"pos":"VERB 动词","cn":"垂钓;钓鱼;捕鱼","en":"If you fish, you try to catch fish, either for food or as a form of sport or recreation.","ex":{"en":"Brian remembers learning to fish in the River Cam.","cn":"布赖恩记得曾在剑河学过钓鱼。"}},{"pos":"VERB 动词","cn":"在…垂钓(或钓鱼、捕鱼)","en":"If you fish a particular area of water, you try to catch fish in it.","ex":{"en":"On Saturday we fished the River Arno.","cn":"周六我们在阿尔诺河钓鱼。"}},{"pos":"VERB 动词","cn":"旁敲侧击地打听;拐弯抹角地谋取","en":"If you say that someone is fishing for information or praise, you disapprove of the fact that they are trying to get it from someone in an indirect way.","ex":{"en":"He didn't want to create the impression that he was fishing for information","cn":"他不想让人觉得自己是在套话。"}},{"pos":"PHRASE 短语","cn":"如离水之鱼(指因离开熟悉的环境而感到不适)","en":"If you feel like a fish out of water, you do not feel comfortable or relaxed because you are in an unusual or unfamiliar situation.","ex":{"en":"I think he thought of himself as a country gentleman and was like a fish out of water in Birmingham.","cn":"我想他认为自己是一名乡绅，在伯明翰就如离水之鱼一般浑身不自在。"}},{"pos":"PHRASE 短语","cn":"海里的鱼有的是;天涯何处无芳草","en":"If you tell someone that there are plenty more fish in the sea, you are comforting them by saying that although their relationship with someone has failed, there are many other people they can have relationships with."},{"pos":"PHRASAL VERB 短语动词","cn":"(从…中)取出，拿出，拖出","en":"If you fish something out from somewhere, you take or pull it out, often after searching for it for some time.","ex":{"en":"Kelly fished out another beer from his cooler","cn":"凯莉从他的冷藏箱里又拿出一瓶啤酒。"}},{"pos":"","cn":"","en":"相关词组：fish out"}]},"examples":[{"en":"The list of endangered species includes nearly 600 fishes.","cn":"濒临灭绝物种的名单中列有将近 600 种鱼。"},{"en":"She fished a piece of paper out of the pile on her desk.","cn":"她从桌上一大堆纸中抽出了一张。"}]},"finder":{"oxford":{"phon":"ˈfaɪndə(r)","pos":"noun","senses":[{"en":"a person who finds something","cn":"发现者；寻得者","ex":{"en":"If the money remains unclaimed for a certain time it is returned to the finder.","cn":"如果在一定时间内无人认领这笔钱，则会将其退还给拾得者。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发现者;寻得者;找到…的人","en":"You can refer to someone who finds something as the finder of that thing.","ex":{"en":"The finder of a wallet who takes it home may be guilty of theft","cn":"将钱包据为己有的人可能会被控盗窃。"}}]},"media":{"uk":"media/uk/finder__gb_1.mp3","us":"media/us/finder__us_1.mp3"},"examples":[{"en":"The finder usually receives a reward.","cn":"找到失物的人一般会有酬金。"}]},"fitness":{"oxford":{"phon":"ˈfɪtnəs","pos":"noun","senses":[{"en":"the state of being physically healthy and strong","cn":"健壮；健康","lab":"British English","ex":{"en":"a magazine on health and fitness","cn":"卫生与健康杂志"}},{"en":"the state of being suitable or good enough for something","cn":"适合（某事物或做某事）","ex":{"en":"He convinced us of his fitness for the task.","cn":"他使我们相信他适合做这项工作。"}}]},"media":{"uk":"media/uk/fitness__gb_1.mp3","us":"media/us/fitness__us_1.mp3"},"examples":[{"en":"He convinced us of his fitness for the task.","cn":"他使我们相信他适合做这项工作。"},{"en":"There were doubts about her fitness to hold office.","cn":"她是否称职还有疑虑。"}]},"financially":{"oxford":{"phon":"faɪˈnænʃəli","pos":"adverb","senses":[{"en":"in a way that is connected with money and finance","cn":"财政的；财务的；金融的","ex":{"en":"She is still financially dependent on her parents.","cn":"她在经济上仍然依赖父母。"}}]},"media":{"uk":"media/uk/financially__gb_1.mp3","us":"media/us/financially__us_1.mp3"},"examples":[{"en":"Such projects are not financially viable without government funding.","cn":"没有政府专款，这样的项目在资金上是不可行的。"},{"en":"Financially, I'm much better off than before.","cn":"我的经济状况比过去好多了。"}]},"finite":{"oxford":{"phon":"ˈfaɪnaɪt","pos":"adjective","senses":[{"en":"having a definite limit or fixed size","cn":"有限的；有限制的","ex":{"en":"a finite number of possibilities","cn":"为数有限的可能"}},{"en":"a finite verb form or clause shows a particular tense, person and number","cn":"限定的","lab":"grammar","ex":{"en":"‘Am’, ‘is’, ‘are’, ‘was’ and ‘were’ are the finite forms of ‘be’; ‘being’ and ‘been’ are the non-finite forms.","cn":"am、is、are、was 和 were 是 be 的限定形式，being 和 been 是非限定形式。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有限的;有尽的","en":"Something that is finite has a definite fixed size or extent.","ex":{"en":"...a finite set of elements","cn":"有限元素集"}},{"pos":"ADJ 形容词","cn":"(从句)限定的，定式的","en":"A finite clause is a clause based on a verb group which indicates tense, such as 'went', 'is waiting', or 'will be found', rather than on an infinitive or a participle."}]},"media":{"uk":"media/uk/finite__gb_1.mp3","us":"media/us/finite__us_1.mp3"},"examples":[{"en":"‘Am’, ‘is’, ‘are’, ‘was’ and ‘were’ are the finite forms of ‘be’; ‘being’, and ‘been’ are the non-finite forms. * am、is、are、was","cn":"和 were 是 be 的限定形式，being 和 been 是非限定形式。"},{"en":"The world's resources are finite.","cn":"世界的资源是有限的。"}]},"financial":{"media":{"uk":"media/uk/financial__gb_1.mp3","us":"media/us/financial__us_1.mp3"},"oxford":{"phon":"faɪˈnænʃl","pos":"adjective","senses":[{"en":"connected with money and finance","cn":"财政的；财务的；金融的","ex":{"en":"the world's major financial markets/institutions","cn":"世界主要金融市场／机构"}},{"en":"having money","cn":"有钱的","lab":"Australian English, New Zealand English, informal，，，，"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"财政的;金融的;财务的","en":"Financial means relating to or involving money.","ex":{"en":"The company is in financial difficulties.","cn":"公司目前财政困难。"}}]},"examples":[{"en":"Such projects are not financially viable without government funding.","cn":"没有政府专款，这样的项目在资金上是不可行的。"},{"en":"Tokyo and New York are major financial centres.","cn":"东京和纽约是重要的金融中心。"}]},"filter":{"media":{"img":["media/pic/filter_comp.jpg","media/thumb/filter.jpg"],"uk":"media/uk/filter__gb_1.mp3","us":"media/us/filter__us_1.mp3"},"oxford":{"phon":"ˈfɪltə(r)","pos":"noun","senses":[{"en":"a device containing paper, sand, chemicals, etc. that a liquid or gas is passed through in order to remove any materials that are not wanted","cn":"滤器；过滤器","ex":{"en":"an air/oil filter","cn":"空气过滤器；滤油器"}},{"en":"a device that allows only particular types of light or sound to pass through it","cn":"滤光器；滤声器；滤波器","ex":{"en":"The camera has an anti-glare filter.","cn":"相机配有防眩光滤镜。"}},{"en":"a program that processes information to leave out the types that are not wanted, or that stops particular types of electronic information, email, etc. from being sent to a computer","cn":"筛选（或过滤）程序","lab":"computing","ex":{"en":"Spam filters block out almost all threats.","cn":"垃圾邮件过滤器能隔绝大多数的风险。"}},{"en":"a light on a set of traffic lights showing that traffic can turn left (or right) while traffic that wants to go straight ahead or turn right (or left) must wait","cn":"（不得直行或右转时表示可左转，或不得直行或左转时表示可右转的）分流指示灯","lab":"British English","ex":{"en":"a filter lane","cn":"分流车道。"}},{"en":"a tool on digital cameras, photo apps, etc. that allows you to change the appearance of an image","cn":"滤镜（修图软件功能）","lab":"computing","ex":{"en":"The software allows you to apply filters, remove blemishes and add doodles or text to your images.","cn":"该软件能够使用滤镜，去除瑕疵，还能在图像上添加涂鸦或文字。"}},{"en":"to pass liquid, light, etc. through a special device, especially to remove something that is not wanted","cn":"过滤","g":"[transitive]","lab":"figurative","ex":{"en":"All drinking water must be filtered.","cn":"所有饮用水必须经过过滤。"},"pos":"verb"},{"en":"to use a special program to check the content of emails or websites before they are sent to your computer","cn":"（用程序）筛选，过滤","g":"[transitive]","pos":"verb"},{"en":"to move slowly in a particular direction","cn":"缓行","g":"[intransitive]","ex":{"en":"The doors opened and people started filtering through.","cn":"门开了，人们开始徐徐通过。"},"pos":"verb"},{"en":"to slowly become known","cn":"慢慢传开；走漏","g":"[intransitive]","ex":{"en":"More details about the crash are filtering through.","cn":"这场空难的具体情况慢慢披露了。"},"pos":"verb"},{"en":"to come into a place slowly or in small amounts","cn":"渗入；透过","g":"[intransitive]","ex":{"en":"Sunlight filtered in through the curtains.","cn":"阳光从窗帘透了进来。"},"pos":"verb"},{"en":"to turn left (or right) at traffic lights while other vehicles wanting to go straight ahead or turn right (or left) must wait","cn":"仅可左转（或右转）行驶","g":"[intransitive]","lab":"British English","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"过滤","en":"To filter a substance means to pass it through a device which is designed to remove certain particles contained in it.","ex":{"en":"The best prevention for cholera is to boil or filter water, and eat only well-cooked food.","cn":"预防霍乱的最佳方法是将水煮沸或过滤，并且只食用煮熟后的食物。"}},{"pos":"N-COUNT 可数名词","cn":"滤器;过滤器","en":"A filter is a device through which a substance is passed when it is being filtered.","ex":{"en":"...a paper coffee filter.","cn":"咖啡过滤纸"}},{"pos":"N-COUNT 可数名词","cn":"滤声器;滤光器;滤波器","en":"A filter is a device through which sound or light is passed and which blocks or reduces particular sound or light frequencies.","ex":{"en":"You might use a yellow filter to improve the clarity of a hazy horizon.","cn":"可以使用黄色滤光器让模糊的视野更加清晰。"}},{"pos":"VERB 动词","cn":"(光或声)隐约透过，缓缓传至","en":"If light or sound filters into a place, it comes in weakly or slowly, either through a partly covered opening, or from a long distance away.","ex":{"en":"Light filtered into my kitchen through the soft, green shade of the cherry tree.","cn":"光线透过樱桃树柔和的绿阴隐约照进我的厨房。"}},{"pos":"VERB 动词","cn":"(消息等)走漏，慢慢传开","en":"When news or information filters through to people, it gradually reaches them.","ex":{"en":"It took months before the findings began to filter through to the politicians","cn":"调查结果数月后才传到从政者的耳朵里。"}},{"pos":"N-COUNT 可数名词","cn":"(路口的)转弯信号灯(或车道)","en":"A traffic filter is a traffic signal or lane which controls the movement of traffic wanting to turn left or right."},{"pos":"PHRASAL VERB 短语动词","cn":"滤除;滤掉","en":"To filter out something from a substance or from light means to remove it by passing the substance or light through something acting as a filter.","ex":{"en":"Children should have glasses which filter out UV rays","cn":"儿童应该戴上滤除紫外线的眼镜。"}},{"pos":"","cn":"","en":"相关词组：filter out"}]},"examples":[{"en":"The software filters out Internet sites whose content is not suitable for children.","cn":"这个软件可筛除含儿童不宜内容的互联网网站。"},{"en":"Use a sun block that filters UVA effectively.","cn":"使用能有效滤掉长波紫外线的防晒霜。"}]},"finished":{"media":{"uk":"media/uk/finished__gb_1.mp3","us":"media/us/finished__us_1.mp3"},"oxford":{"phon":"ˈfɪnɪʃt","pos":"adjective","senses":[{"en":"no longer doing something or dealing with somebody/something","cn":"完成；不再与…打交道","g":"[not before noun]","ex":{"en":"I won't be finished for another hour.","cn":"我还得一小时才能完成。"}},{"en":"no longer powerful, effective or able to continue","cn":"垮台；失败；完蛋","g":"[not before noun]","ex":{"en":"If the newspapers find out, he's finished in politics.","cn":"如果报界发现这些问题，他的政治生涯就完了。"}},{"en":"fully completed, especially in a particular way","cn":"完成了的","g":"[usually before noun]","ex":{"en":"a beautifully finished suit","cn":"做工精美的一套西服"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不再做(…)的;(同…)不再打交道的;(对…)不再感兴趣的","en":"Someone who is finished with something is no longer doing it or dealing with it or is no longer interested in it.","ex":{"en":"One suspects he will be finished with boxing.","cn":"人们猜想他不会再打拳了。"}},{"pos":"ADJ 形容词","cn":"不复存在的;不再发生的","en":"Something that is finished no longer exists or is no longer happening.","ex":{"en":"I go back on the dole when the shooting season's finished.","cn":"狩猎季节过后，我又重靠领取救济金过活。"}},{"pos":"ADJ 形容词","cn":"垮台的;完蛋的;失势的;失效的","en":"Someone or something that is finished is no longer important, powerful, or effective.","ex":{"en":"Her power over me is finished","cn":"她再也不能控制我了。"}},{"pos":"ADJ 形容词","cn":"(以某种方式的外观或装饰)最后呈现的","en":"Something that is finished or finished off in a particular way has been given a particular appearance or decoration.","ex":{"en":"The dining room is finished in deep red","cn":"餐厅装饰成了深红色。"}}]},"examples":[{"en":"If the newspapers find out, he's finished in politics.","cn":"如果报界发现这些问题，他的政治生涯就完了。"},{"en":"I won't be finished for another hour.","cn":"我还得一小时以后才能完成。"}],"base":"finish"},"filler":{"oxford":{"phon":"ˈfɪlə(r)","pos":"noun","senses":[{"en":"a substance used to fill holes, especially in walls before painting them","cn":"填充物，填料（尤用于漆墙前填孔或缝）","g":"[uncountable, countable]"},{"en":"something that is not important but is used to complete something else because nothing better is available","cn":"充数的东西；填补空白之物","g":"[countable]","lab":"informal","ex":{"en":"The song was originally a filler on their first album.","cn":"这首歌在他们第一张专辑中本来是用来凑时间的。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(尤用于填塞墙壁、车身或木头缝隙或孔洞的)填料,填充物","en":"Filler is a substance used for filling cracks or holes, especially in walls, car bodies, or wood."},{"pos":"N-COUNT 可数名词","cn":"充数(或补空的事物)","en":"You can describe something as a filler when it is being used or done because there is a need for something and nothing better is available."},{"pos":"N-COUNT 可数名词","cn":"引致满场的事物","en":"If you say that something is, for example, a stadium filler or a floor filler, you mean that it is likely to attract crowds to a stadium or onto a dance floor."}]},"media":{"uk":"media/uk/filler__gb_1.mp3","us":"media/us/filler__us_1.mp3"},"examples":[{"en":"The song was originally a filler on their first album.","cn":"这首歌在他们第一张专辑中本来是用来凑时间的。"}]},"figure":{"media":{"uk":"media/uk/figure__gb_1.mp3","us":"media/us/figure__us_1.mp3"},"oxford":{"phon":"ˈfɪɡə(r)","pos":"noun","senses":[{"en":"a number representing a particular amount, especially one given in official information","cn":"（代表数量，尤指官方资料中的）数字","g":"[countable, usually plural]","sc":"numbers","ex":{"en":"the latest sales/crime/unemployment figures","cn":"最新的销售／犯罪／失业数字"}},{"en":"a symbol rather than a word representing one of the numbers between 0 and 9","cn":"数字符号；字码；位数","g":"[countable]","sc":"numbers","ex":{"en":"Write the figure ‘7’ on the board.","cn":"把数字 7 写在黑板上。"}},{"en":"the area of mathematics that deals with adding, multiplying, etc. numbers","cn":"算术","g":"[plural]","lab":"informal","sc":"numbers","ex":{"en":"Are you any good at figures?","cn":"你的算术好吗？"}},{"en":"a person of the type mentioned","cn":"人物","g":"[countable]","sc":"person","ex":{"en":"a leading figure in the music industry","cn":"音乐界一位主要人物"}},{"en":"the shape of a person seen from a distance or not clearly","cn":"（远处人的）轮廓；（隐约可见的）人影","g":"[countable]","sc":"person","ex":{"en":"There before him stood a tall figure in black.","cn":"站在他面前的是一个穿黑衣的高个子。"}},{"en":"the shape of the human body, especially a woman’s body that is considered attractive","cn":"身材；体形；（尤指）身段","g":"[countable]","lab":"becoming old-fashioned","sc":"shape of body","ex":{"en":"You have a really good figure.","cn":"你的身材真的很好。"}},{"en":"a person or an animal in a drawing, painting, etc., or in a story","cn":"（绘画或故事中的）人，动物","g":"[countable]","sc":"in painting/story","ex":{"en":"The central figure in the painting is the artist's daughter.","cn":"画中间那个人是画家的女儿。"}},{"en":"a statue of a person or an animal","cn":"（人或动物的）雕像，塑像","g":"[countable]","sc":"statue","ex":{"en":"a bronze figure of a horse","cn":"一座马的铜像"}},{"en":"a picture, diagram, etc. in a book, that is referred to by a number or letter","cn":"（书中的）图，表","g":"[countable]","sc":"picture/diagram","ex":{"en":"The results are illustrated in figure 3 opposite.","cn":"结果见对页图表 3。"}},{"en":"a particular shape formed by lines or surfaces","cn":"图形","g":"[countable]","sc":"geometry","ex":{"en":"a five-sided figure","cn":"五边形"}},{"en":"a pattern or series of movements performed on ice","cn":"（冰上表演动作的）花样","g":"[countable]","sc":"movement on ice","ex":{"en":"The skater executed a perfect set of figures.","cn":"那个滑冰的人做出了一套完美的花样动作。"}},{"en":"to be part of a process, situation, etc. especially an important part","cn":"是重要部分；是…的部分","g":"[intransitive]","sc":"be important","ex":{"en":"My feelings about the matter didn't seem to figure at all.","cn":"我对这个问题的意见似乎根本无足轻重。"},"pos":"verb"},{"en":"to think or decide that something will happen or is true","cn":"认为，认定（某事将发生或属实）","g":"[transitive]","lab":"informal","sc":"think/decide","ex":{"en":"I figured (that) if I took the night train, I could be in Scotland by morning.","cn":"我认为，如果我坐夜班火车，早上就可以到达苏格兰。"},"pos":"verb"},{"en":"to calculate an amount or the cost of something","cn":"计算（数量或成本）","g":"[transitive]","lab":"North American English","sc":"calculate","ex":{"en":"We figured the attendance at 150 000.","cn":"我们估计有 15 万人参加。"},"pos":"verb"},{"en":"to represent somebody/something in a particular way in art or literature","cn":"显出…的样子；显得","g":"[transitive]","sc":"represent","ex":{"en":"Tom Eakins was figured as a regular guy, an ordinary Joe.","cn":"汤姆·埃金斯被描绘成一个普通人，一个普通的乔。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"数字;(尤指)统计数字","en":"A figure is a particular amount expressed as a number, especially a statistic.","ex":{"en":"It would be very nice if we had a true figure of how many people in this country haven't got a job","cn":"如果我们能得到该国失业人口的真实数字就好了。"}},{"pos":"N-COUNT 可数名词","cn":"(0 到 9 的)数字符号，数目字","en":"A figure is any of the ten written symbols from 0 to 9 that are used to represent a number."},{"pos":"N-PLURAL 复数名词","cn":"位数","en":"An amount or number that is in single figures is between zero and nine. An amount or number that is in double figures is between ten and ninety-nine. You can also say, for example, that an amount or number is in three figures when it is between one hundred and nine hundred and ninety-nine.","ex":{"en":"Inflation, which has usually been in single figures, is running at more than 12%","cn":"通常保持在个位数的通货膨胀率现在已超过了 12％。"}},{"pos":"N-COUNT 可数名词","cn":"人影;身影","en":"You refer to someone that you can see as a figure when you cannot see them clearly or when you are describing them.","ex":{"en":"Alistair saw the dim figure of Rose in the chair","cn":"阿利斯泰尔看见了坐在椅子里的罗丝的模糊身影。"}},{"pos":"N-COUNT 可数名词","cn":"(绘画作品中的)人物;雕像;塑像","en":"In art, a figure is a person in a drawing or a painting, or a statue of a person.","ex":{"en":"...a life-size bronze figure of a brooding, hooded woman.","cn":"一个戴着兜帽作沉思状的真人大小青铜女子雕像"}},{"pos":"N-COUNT 可数名词","cn":"体形;身材","en":"Your figure is the shape of your body.","ex":{"en":"Take pride in your health and your figure","cn":"为自己的健康和体形感到骄傲吧。"}},{"pos":"N-COUNT 可数名词","cn":"知名人士;重要人物","en":"Someone who is referred to as a figure of a particular kind is a person who is well-known and important in some way.","ex":{"en":"The movement is supported by key figures in the three main political parties.","cn":"这个运动受到三大政党关键人物的支持。"}},{"pos":"N-COUNT 可数名词","cn":"(某种)人物，形象","en":"If you say that someone is, for example, a mother figure or a hero figure, you mean that other people regard them as the type of person stated or suggested.","ex":{"en":"Sometimes young lads just need to turn to a mother figure for a bit of a chat and reassurance.","cn":"有时候年轻小伙子只是需要找一个母亲式的人物聊一聊，从中获得安慰。"}},{"pos":"N-COUNT 可数名词","cn":"(书、杂志等中的)图，表","en":"In books and magazines, the diagrams which help to show or explain information are referred to as figures .","ex":{"en":"If you look at a world map (see Figure 1) you can identify the major wine-producing regions","cn":"查一查世界地图(见图1)，就能找到主要的葡萄酒产区。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指规则的几何)图形","en":"In geometry, a figure is a shape, especially a regular shape.","ex":{"en":"Draw a pentagon, a regular five-sided figure.","cn":"画个五边形，一个规则的五边形。"}},{"pos":"VERB 动词","cn":"认为;猜想;估计","en":"If you figure that something is the case, you think or guess that it is the case.","ex":{"en":"She figured that both she and Ned had learned a lot from the experience.","cn":"她觉得自己和内德都从这一经历中学到了很多东西。"}},{"pos":"VERB 动词","cn":"不奇怪;很正常;合乎情理","en":"If you say 'That figures' or 'It figures', you mean that the fact referred to is not surprising.","ex":{"en":"When I finished, he said, 'Yeah. That figures'","cn":"等我说完，他说道：“是啊，那是预料中事。”"}},{"pos":"VERB 动词","cn":"出现，包括(在…中)","en":"If a person or thing figures in something, they appear in or are included in it.","ex":{"en":"Human rights violations figured prominently in the report.","cn":"有关侵犯人权的部分在报告中占据了显要地位。"}},{"pos":"PHRASE 短语","cn":"显出…的样子;显得","en":"If you say that someone cuts a particular figure, you mean that they appear to other people in the way described.","ex":{"en":"Today she cuts a lonely figure.","cn":"今天她看起来十分孤独。"}},{"pos":"PHRASE 短语","cn":"小丑;可笑的人","en":"If you describe someone as a figure of fun, you mean that people think they are ridiculous.","ex":{"en":"The man has become an unlikely figure of fun.","cn":"令人想象不到的是，这个男人已经成为了笑谈。"}},{"pos":"PHRASE 短语","cn":"保持/失去苗条的身材","en":"If you keep your figure, you stay thin. If you lose your figure, you become rather fat.","ex":{"en":"You'll lose your girlish figure if you don't watch out.","cn":"如果不多加注意，你就会失去女孩般的苗条身段。"}},{"pos":"PHRASE 短语","cn":"说出…的确切数量(或数目)","en":"When you put a figure on an amount, you say exactly how much it is.","ex":{"en":"No one will put a figure on the final cost of this reconstruction.","cn":"谁也不愿确切地说明这一重建最后总共的花费是多少。"}},{"pos":"PHRASAL VERB 短语动词","cn":"预料;料想","en":"If you figure on something, you plan that it will happen or assume that it will happen when making your plans.","ex":{"en":"Jack worked as hard as he could to build his business, but he hadn't figured on a few obstacles.","cn":"杰克竭尽全力发展自己的公司，但有几个障碍是他始料不及的。"}},{"pos":"PHRASAL VERB 短语动词","cn":"想出;理解;弄清","en":"If you figure out a solution to a problem or the reason for something, you succeed in solving it or understanding it.","ex":{"en":"It took them about one month to figure out how to start the equipment","cn":"他们花了大约1个月的时间才搞清楚如何启动设备。"}},{"pos":"PHRASAL VERB 短语动词","cn":"算出…的总和","en":"If you figure up a cost or amount, you add numbers together to get the total.","ex":{"en":"He figured up the balance in their checking account.","cn":"他算出了他们活期存款账户上的余额总和。"}},{"pos":"","cn":"","en":"相关词组：figure on figure out figure up"}]},"examples":[{"en":"People are more aware of the risks of smoking nowadays, but more young women are smoking than ever. Go figure!","cn":"现在人们更加了解吸烟的危害，但吸烟的年轻女性倒比以往多了。真让人搞不懂！"},{"en":"‘John called in sick.’ ‘That figures, he wasn't feeling well yesterday.’ “","cn":"约翰打电话来说他病了。” “这合乎情理，他昨天就感到不舒服。”"}]},"fist":{"media":{"uk":"media/uk/fist__gb_1.mp3","us":"media/us/fist__us_1.mp3"},"oxford":{"phon":"fɪst","pos":"noun","senses":[{"en":"a hand when it is tightly closed with the fingers bent into the palm","cn":"拳；拳头","ex":{"en":"He punched me with his fist.","cn":"他用拳头猛击我。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拳;拳头","en":"Your hand is referred to as your fist when you have bent your fingers in towards the palm in order to hit someone, to make an angry gesture, or to hold something.","ex":{"en":"Angry protestors with clenched fists shouted their defiance","cn":"愤怒的抗议者们紧握拳头大声抗议。"}},{"pos":"PHRASE 短语","cn":"(政策或方法)铁拳的，残酷无情的，强硬的","en":"An iron fist policy or approach is one which deals with people and situations in a very strict and cruel way.","ex":{"en":"The iron-fist policy towards the fundamentalists is unlikely to be interrupted.","cn":"对原教旨主义者采取的铁拳政策不可能中止。"}},{"pos":"","cn":"","en":"hand over fist→see: ;"}]},"examples":[{"en":"She clenched her fists to stop herself trembling.","cn":"她紧握双拳，克制颤抖。"},{"en":"He got into a fist fight in the bar.","cn":"他在酒吧与人挥拳斗殴。"}]},"fishermen":{"lemma":"fisherman"},"figurative":{"media":{"uk":"media/uk/figurative__gb_1.mp3","us":"media/us/figurative__us_1.mp3"},"oxford":{"phon":"ˈfɪɡərətɪv","pos":"adjective","senses":[{"en":"used in a way that is different from the usual meaning, in order to create a particular mental picture. For example, ‘He exploded with rage’ shows a figurative use of the verb ‘explode’.","cn":"比喻的"},{"en":"showing people, animals and objects as they really look","cn":"具象的","ex":{"en":"a figurative artist","cn":"具象艺术家"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"比喻的;借喻的","en":"If you use a word or expression in a figurative sense, you use it with a more abstract or imaginative meaning than its ordinary literal one.","ex":{"en":"...an event that will change your route — in both the literal and figurative sense.","cn":"一个无论从字面还是比喻意义上来说都将改变你的路线的事件"}},{"pos":"ADJ 形容词","cn":"(艺术风格)具象的，写实的","en":"Figurative art is a style of art in which people and things are shown in a realistic way.","ex":{"en":"His career spanned some 50 years and encompassed both abstract and figurative painting.","cn":"他的职业生涯延续了大约50年，作品既有抽象画也有写实画。"}}]},"examples":[{"en":"She is, figuratively speaking, holding a gun to his head.","cn":"打个比方说，她正拿枪对着他的脑袋。"},{"en":"a figurative artist","cn":"形象艺术家"}]},"fishing":{"media":{"uk":"media/uk/fishing__gb_1.mp3","us":"media/us/fishing__us_1.mp3"},"oxford":{"phon":"ˈfɪʃɪŋ","pos":"noun","senses":[{"en":"the sport or business of catching fish","cn":"钓鱼；捕鱼业（或活动）","ex":{"en":"They often go fishing.","cn":"他们常去钓鱼。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"捕鱼;钓鱼","en":"Fishing is the sport, hobby, or business of catching fish.","ex":{"en":"Despite the poor weather the fishing has been pretty good.","cn":"尽管天气恶劣，却渔获颇丰。"}}]},"examples":[{"en":"We enjoyed a day's fishing by the river.","cn":"我们在河边享受了一天垂钓之乐。"},{"en":"They often go fishing.","cn":"他们常去钓鱼。"}],"base":"fish"},"figured":{"media":{"uk":"media/uk/figured__gb_1.mp3","us":"media/us/figured__us_1.mp3"},"oxford":{"phon":"ˈfɪɡəd","pos":"adjective","senses":[{"en":"decorated with a small pattern","cn":"饰以图案的","ex":{"en":"figured pottery","cn":"绘有图案的陶器"}}]},"examples":[{"en":"figured pottery","cn":"绘有图案的陶器"}],"base":"figure"},"financier":{"oxford":{"phon":"faɪˈnænsiə(r)","pos":"noun","senses":[{"en":"a person who manages or lends large amounts of money for or to businesses or governments","cn":"金融家；理财家"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出资人;出资方;金融(资本)家","en":"A financier is a person, company, or government that provides money for projects or businesses."}]},"media":{"uk":"media/uk/financier__gb_1.mp3","us":"media/us/financier__us_1.mp3"}},"files":{"lemma":"file","media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/file2.jpg"],"uk":"media/uk/file__gb_1.mp3","us":"media/us/file__us_1.mp3"}},"firm":{"media":{"uk":"media/uk/firm__gb_1.mp3","us":"media/us/firm__us_1.mp3"},"oxford":{"phon":"fɜːm","pos":"noun","senses":[{"en":"a business or company","cn":"商行；商号；公司","lab":"North American English","ex":{"en":"a law/consulting/research firm","cn":"律师事务所；咨询／研究公司"}},{"en":"fairly hard; not easy to press into a different shape","cn":"坚固的；坚硬的；结实的","ex":{"en":"a firm bed/mattress","cn":"结实的床／床垫"},"pos":"adjective"},{"en":"not likely to change","cn":"坚定的；确定的；坚决的","ex":{"en":"a firm believer in socialism","cn":"坚定信仰社会主义的人"},"pos":"adjective"},{"en":"strongly fixed in place","cn":"牢固的；稳固的","ex":{"en":"Stand the fish tank on a firm base.","cn":"把鱼缸放在牢固的基座上。"},"pos":"adjective"},{"en":"strong and steady","cn":"强有力的；坚决的","ex":{"en":"‘No,’ she repeated, her voice firmer this time.","cn":"“不。”她重复道，这次语气更加坚决。"},"pos":"adjective"},{"en":"strong and in control","cn":"牢牢控制的；严格的；掌握的","ex":{"en":"to exercise firm control/discipline/leadership","cn":"实施严格的控制／纪律／领导"},"pos":"adjective"},{"en":"not lower than another","cn":"坚挺的","g":"[usually before noun]","ex":{"en":"The euro remained firm against the dollar, but fell against the yen.","cn":"欧元对美元依然坚挺，但对日元的汇率则下跌。"},"pos":"adjective"},{"en":"to make something become stronger or harder","cn":"使强壮；使坚固；使坚实","g":"[transitive]","ex":{"en":"Firm the soil around the plant.","cn":"把植物周围的土弄紧实。"},"pos":"verb"},{"en":"to become steady or rise steadily","cn":"坚挺；稳步上涨","g":"[intransitive]","lab":"finance","ex":{"en":"The company's shares firmed 3p to 696p.","cn":"这家公司的股票涨了 3 便士，升至 696 便士。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商号;商行;公司","en":"A firm is an organization which sells or produces something or which provides a service which people pay for.","ex":{"en":"The firm's employees were expecting large bonuses.","cn":"这家公司的雇员期待着发放大笔奖金。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚固的;坚硬的;结实的","en":"If something is firm, it does not change much in shape when it is pressed but is not completely hard.","ex":{"en":"Fruit should be firm and in excellent condition","cn":"水果应该硬实完好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳固的;牢固的","en":"If something is firm, it does not shake or move when you put weight or pressure on it, because it is strongly made or securely fastened.","ex":{"en":"If you have to climb up, use a firm platform or a sturdy ladder.","cn":"如果非要爬上去，就踩在一个稳固的台子上或者找把结实的梯子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(抓握或动作)强有力的，使上劲的","en":"If someone's grip is firm or if they perform a physical action in a firm way, they do it with quite a lot of force or pressure but also in a controlled way.","ex":{"en":"The quick handshake was firm and cool","cn":"短暂的握手有力沉稳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)坚定的，坚决的,强势的","en":"If you describe someone as firm, you mean they behave in a way that shows that they are not going to change their mind, or that they are the person who is in control.","ex":{"en":"She had to be firm with him. 'I don't want to see you again.'","cn":"她不得不对他狠下心来：“我不想再见到你。”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(决定或意见)确定的,不会更改的","en":"A firm decision or opinion is definite and unlikely to change.","ex":{"en":"He made a firm decision to leave Fort Multry by boat","cn":"他打定主意乘船离开穆尔特里堡。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(证据或信息)确切的，确实的，确凿的","en":"Firm evidence or information is based on facts and so is likely to be true.","ex":{"en":"This man may have killed others but unfortunately we have no firm evidence","cn":"这名男子可能还杀害过其他人，只可惜我们没有确凿的证据。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(控制、基础、位置等)坚实的，不可动摇的","en":"You use firm to describe control or a basis or position when it is strong and unlikely to be ended or removed.","ex":{"en":"Although the Yakutians are a minority, they have firm control of the territory","cn":"尽管雅库特人是少数民族，但他们却牢牢地掌控着这块版图。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忠实的;忠贞的;牢靠的","en":"If people are firm friends, they have been close friends for a long time and their friendship is likely to continue.","ex":{"en":"The couple met about two years ago and soon became firm friends.","cn":"这对夫妇大约两年前相遇，很快就成了知交。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(价格、价值、货币等)坚挺的，稳定的，居高不下的","en":"If a price, value, or currency is firm, it is not decreasing in value or amount.","ex":{"en":"Cotton prices remain firm and demand is strong","cn":"棉花价格始终保持坚挺，需求旺盛。"}},{"pos":"VERB 动词","cn":"(在植物周围)压，培(土)","en":"If you firm soil around a plant, you press it so that it is fairly solid rather than loose.","ex":{"en":"Firm more soil over the roots and water thoroughly.","cn":"在根上再多培些土，用水浇透。"}},{"pos":"PHRASE 短语","cn":"坚定不移;坚持己见;拒不让步","en":"If someone stands firm, they refuse to change their mind about something.","ex":{"en":"The council is standing firm against the barrage of protest","cn":"委员会面对接二连三的抗议拒不让步。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)更坚固;(使)更坚硬;(使)更结实","en":"If you firm up something or if it firms up, it becomes firmer and more solid.","ex":{"en":"This treatment helps tone the body, firm up muscles and tighten the skin","cn":"该治疗有助于强身健体、紧致皮肤。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)更明确;(使)更强化;(使)确切","en":"If you firm something up or if it firms up, it becomes clearer, stronger, or more definite.","ex":{"en":"Looking to the future, the Government will firm up their plans for a cleaner, greener, safer Britain","cn":"展望未来，政府将更加明确其计划，建设一个更清洁、更环保、更安全的英国。"}},{"pos":"PHRASAL VERB 短语动词","cn":"使(价格、价值等)保持坚挺(或稳定)","en":"If a financial institution firms up the price or value of something, they take action to protect and maintain its price or value.","ex":{"en":"OPEC has agreed to freeze its global oil production slightly in order to firm up crude prices.","cn":"石油输出国组织已同意对全球石油生产稍加冻结，以稳定原油价格。"}},{"pos":"","cn":"","en":"相关词组：firm up"}]},"examples":[{"en":"Rank's shares firmed 3p to 696p.","cn":"兰克公司的股票涨了 3 便士，升至 696 便士。"},{"en":"Everyone agreed with me, so I knew I was on firm ground.","cn":"每个人都同意我的意见，所以我知道自己立场稳固了。"}]},"filling":{"media":{"uk":"media/uk/filling__gb_1.mp3","us":"media/us/filling__us_1.mp3","img":["media/ldoce/img/apple_pie.jpg"]},"oxford":{"phon":"ˈfɪlɪŋ","pos":"noun","senses":[{"en":"a small amount of metal or other material used to fill a hole in a tooth","cn":"（补牙的）填料","g":"[countable]","ex":{"en":"I had to have two fillings at the dentist's today.","cn":"我今天不得不在牙科诊所补了两颗牙。"}},{"en":"food put inside a sandwich, cake, pie, etc.","cn":"（糕点等的）馅","g":"[countable, uncountable]","ex":{"en":"a sponge cake with cream and jam filling","cn":"奶油果酱作馅的海绵蛋糕"}},{"en":"soft material used to fill cushions, pillows, etc.","cn":"（枕头、靠垫等的）填充物，填料","g":"[countable, uncountable]"},{"en":"making your stomach feel full","cn":"能填饱肚子的","ex":{"en":"This cake is very filling.","cn":"这种饼很能填饱肚子。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(补牙用的)填料","en":"A filling is a small amount of metal or plastic that a dentist puts in a hole in a tooth to prevent further decay.","ex":{"en":"The longer your child can go without needing a filling, the better.","cn":"孩子越晚需要补牙就越好。"}},{"pos":"N-MASS 物质名词","cn":"(糕点的)馅","en":"The filling in something such as a cake, pie, or sandwich is a substance or mixture that is put inside it.","ex":{"en":"Spread some of the filling over each pancake.","cn":"在每个薄煎饼上摊上一些馅。"}},{"pos":"N-MASS 物质名词","cn":"(软体家具或垫子的)芯，填充物","en":"The filling in a piece of soft furniture or in a cushion is the soft substance inside it.","ex":{"en":"...second-hand sofas with old-style foam fillings.","cn":"老式泡沫芯子的二手沙发"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)令人感到饱足的","en":"Food that is filling makes you feel full when you have eaten it.","ex":{"en":"Although it is tasty, crab is very filling.","cn":"螃蟹虽然好吃，却容易让人感到饱足。"}}]},"examples":[{"en":"I had to have two fillings at the dentist's today.","cn":"我今天不得不在牙科诊所补了两颗牙。"},{"en":"a sponge cake with cream and jam filling","cn":"奶油果酱作馅的海绵蛋糕"}],"base":"fill"},"finding":{"media":{"uk":"media/uk/finding__gb_1.mp3","us":"media/us/finding__us_1.mp3"},"oxford":{"phon":"ˈfaɪndɪŋ","pos":"noun","senses":[{"en":"information that is discovered as the result of research into something","cn":"调查发现；调研结果","g":"[usually plural]","ex":{"en":"Our research findings indicate that pregnant women benefit from this treatment.","cn":"我们的研究结果显示这种治疗对孕妇有效。"}},{"en":"a decision made by the judge or jury in a court case","cn":"判决；裁决","lab":"law","ex":{"en":"The appeal court upheld a finding that the agreement was unlawful.","cn":"上诉法院维持原裁决，认为协议不合法。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(调查或研究的)结果，发现","en":"Someone's findings are the information they get or the conclusions they come to as the result of an investigation or some research.","ex":{"en":"One of the main findings of the survey was the confusion about the facilities already in place","cn":"这项调查的一个主要发现就是对于哪些设备已经到位搞不清楚。"}},{"pos":"N-COUNT 可数名词","cn":"(法庭的)裁决","en":"The findings of a court are the decisions that it reaches after a trial or an investigation.","ex":{"en":"The government hopes the court will announce its findings before the end of the month.","cn":"政府希望法庭能在月底前宣布其判决结果。"}}]},"examples":[{"en":"The findings of the commission will be published today.","cn":"委员会的调查结果将于今天公布。"},{"en":"Surveys conducted in other countries reported similar findings.","cn":"在其他国家进行的调查也报告说有类似的结果。"}],"base":"find"},"find":{"media":{"uk":"media/uk/find__gb_1.mp3","us":"media/us/find__us_1.mp3"},"oxford":{"phon":"faɪnd","pos":"verb","senses":[{"en":"to discover somebody/something unexpectedly or by chance","cn":"（意外或偶然地）发现，碰到","g":"[transitive]","sc":"by chance","ex":{"en":"Look what I've found!","cn":"看我发现了什么！"}},{"en":"to get back something/somebody that was lost after searching for it/them","cn":"找到；找回","g":"[transitive]","sc":"by searching","ex":{"en":"I can't find my keys.","cn":"我找不到我的钥匙。"}},{"en":"to discover something/somebody by searching, studying or thinking carefully","cn":"（经寻找、研究或思考）发现，查明，找出，求得","g":"[transitive]","sc":"by studying/thinking","ex":{"en":"They found no evidence to support this claim.","cn":"他们找不到证据支持这个说法。"}},{"en":"to discover that something is true after you have tried it, tested it or experienced it","cn":"发现（某事属实）","g":"[transitive]","sc":"by experience/testing","ex":{"en":"I find (that) it pays to be honest.","cn":"我发现老实人不吃亏。"}},{"en":"to have a particular feeling or opinion about something","cn":"认为；感到","g":"[transitive]","sc":"have opinion/feeling","ex":{"en":"You may find it hard to accept your illness.","cn":"你可能觉得难以接受自己患病。"}},{"en":"used to say that something exists, grows, etc. somewhere","cn":"（在某处）存在，生长","g":"[transitive, often passive]","sc":"exist/grow","ex":{"en":"These flowers are found only in Africa.","cn":"这些花仅见于非洲。"}},{"en":"to discover somebody/something/yourself doing something or in a particular situation, especially when this is unexpected","cn":"（尤指意外地）发现，发觉（处于某状态、在做某事）","g":"[transitive]","sc":"in unexpected situations","ex":{"en":"She woke up and found herself in a hospital bed.","cn":"她醒来发觉自己躺在医院的床上。"}},{"en":"to have something available so that you can use it","cn":"现有（可用）","g":"[transitive]","sc":"have/make available","ex":{"en":"I keep meaning to write, but never seem to find (the) time.","cn":"我一直打算写信，但似乎总找不到时间。"}},{"en":"to show a quality in yourself, usually with an effort","cn":"鼓起（勇气等）","g":"[transitive]","sc":"have/make available","ex":{"en":"I found the courage to speak.","cn":"我鼓起勇气来发言。"}},{"en":"to arrive at something naturally; to reach something/somebody","cn":"自然到达；达到","g":"[transitive]","sc":"reach","ex":{"en":"Water will always find its own level.","cn":"水总会自行流平。"}},{"en":"to make a particular decision in a court case","cn":"裁决；判决","g":"[transitive, intransitive]","lab":"formal","sc":"in court","ex":{"en":"The jury found him guilty.","cn":"陪审团裁决他有罪。"}},{"en":"a thing or person that has been found, especially one that is interesting, valuable or useful; the act of finding a thing or person like this","cn":"（尤指有趣、有价值或有用的）发现物，被发现的人，发现","ex":{"en":"This is an important archaeological find.","cn":"这是个重大的考古发现。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发现…的所在","en":"If you find someone or something, you see them or learn where they are.","ex":{"en":"The police also found a pistol","cn":"警方还发现了一把手枪。"}},{"pos":"VERB 动词","cn":"找到;寻得;获得","en":"If you find something that you need or want, you succeed in achieving or obtaining it.","ex":{"en":"Many people here cannot find work","cn":"这里很多人都找不到工作。"}},{"pos":"V-PASSIVE 被动动词","cn":"发现…存在(于)","en":"If something is found in a particular place or thing, it exists in that place.","ex":{"en":"Two thousand of France's 4,200 species of flowering plants are found in the park","cn":"法国的 4,200 种开花植物中有 2,000种可见于这个公园。"}},{"pos":"VERB 动词","cn":"发现…处于某种状态;遇见;碰见","en":"If you find someone or something in a particular situation, they are in that situation when you see them or come into contact with them.","ex":{"en":"They found her walking alone and depressed on the beach","cn":"他们碰见她独自一人神色忧郁地走在海滩上。"}},{"pos":"VERB 动词","cn":"(不知不觉中)发现(自己在做某事)","en":"If you find yourself doing something, you are doing it without deciding or intending to do it.","ex":{"en":"It's not the first time that you've found yourself in this situation","cn":"你陷入这种状况已经不是第一次了。"}},{"pos":"VERB 动词","cn":"(某一时刻或事件)把…置于某种情形中","en":"If a time or event finds you in a particular situation, you are in that situation at the time mentioned or when the event occurs.","ex":{"en":"Daybreak found us on a cold, clammy ship","cn":"天亮时我们发现自己呆在一条冰冷黏湿的船上。"}},{"pos":"VERB 动词","cn":"发觉，认识到(某事属实)","en":"If you find that something is the case, you become aware of it or realize that it is the case.","ex":{"en":"The two biologists found, to their surprise, that both groups of birds survived equally well","cn":"这两位生物学家惊奇地发现，两组鸟都很好地存活了下来。"}},{"pos":"VERB 动词","cn":"裁决;判决;判定","en":"When a court or jury decides that a person on trial is guilty or innocent, you say that the person has been found guilty or not guilty.","ex":{"en":"She was found guilty of manslaughter and put on probation for two years","cn":"她被裁定过失杀人罪名成立，缓刑两年。"}},{"pos":"VERB 动词","cn":"觉得;认为","en":"You can use find to express your reaction to someone or something.","ex":{"en":"I find most of the young men of my own age so boring","cn":"我觉得和我同龄的年轻人大多都很无聊。"}},{"pos":"VERB 动词","cn":"感受到(愉快、安慰等情感)","en":"If you find a feeling such as pleasure or comfort in a particular thing or activity, you experience the feeling mentioned as a result of this thing or activity.","ex":{"en":"How could anyone find pleasure in hunting and killing this beautiful creature?","cn":"怎么会有人以猎杀这种美丽的动物为乐呢？"}},{"pos":"VERB 动词","cn":"找出，挤出(时间或金钱)","en":"If you find the time or money to do something, you succeed in making or obtaining enough time or money to do it.","ex":{"en":"I was just finding more time to write music","cn":"我刚刚找到了更多时间来作曲。"}},{"pos":"N-COUNT 可数名词","cn":"(有价值的)发现;(有用的)发现物","en":"If you describe someone or something that has been discovered as a find, you mean that they are valuable, interesting, good, or useful.","ex":{"en":"Another of his lucky finds was a pair of candle-holders","cn":"他的另一个幸运发现是一对烛台。"}},{"pos":"PHRASE 短语","cn":"找到正确的路(去某处);成功地到达","en":"If you find your way somewhere, you successfully get there by choosing the right way to go.","ex":{"en":"He was an expert at finding his way, even in strange surroundings","cn":"他是认路的行家，即使在陌生的环境中也是如此。"}},{"pos":"PHRASE 短语","cn":"(尤指某物偶然)去到(某处)","en":"If something finds its way somewhere, it comes to that place, especially by chance.","ex":{"en":"It is one of the very few Michelangelos that have found their way out of Italy","cn":"这是少数几件流传到意大利境外的米开朗琪罗作品之一。"}},{"pos":"","cn":"","en":"to find fault with→see: ;"},{"pos":"","cn":"","en":". to find one's feet→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"(尤指特意通过努力)发现，找出，查明","en":"If you find something out, you learn something that you did not already know, especially by making a deliberate effort to do so.","ex":{"en":"It makes you want to watch the next episode to find out what's going to happen","cn":"这让人想要看下一集，弄清紧接着会发生什么事。"}},{"pos":"PHRASAL VERB 短语动词","cn":"查出…的不轨行为;揭发出","en":"If you find someone out, you discover that they have been doing something dishonest.","ex":{"en":"Her face was so grave, I wondered for a moment if she'd found me out.","cn":"她的表情如此严肃，我一时怀疑她是不是已经知道了我干的事。"}},{"pos":"","cn":"","en":"相关词组：find out"}]},"examples":[{"en":"She'd been seeing the boy for a while, but didn't want her parents to find out.","cn":"她和这个男孩约会已有一段时间了，但不想让父母知道。"},{"en":"He had been cheating the taxman but it was years before he was found out.","cn":"他过去一直在欺骗税务部门，只是多年以后才被查出来。"}]},"finance":{"media":{"uk":"media/uk/finance__gb_1.mp3","us":"media/us/finance__us_1.mp3"},"oxford":{"phon":"ˈfaɪnæns","pos":"noun","senses":[{"en":"money used to run a business, an activity or a project","cn":"资金","g":"[uncountable]","lab":"especially British English","ex":{"en":"The project will only go ahead if they can raise the necessary finance.","cn":"他们筹集到所需的资金，这个项目才能继续下去。"}},{"en":"the activity of managing money, especially by a government or commercial organization","cn":"财政；金融；财务","g":"[uncountable]","ex":{"en":"the Minister of Finance","cn":"财政部长"}},{"en":"the money available to a person, an organization or a country; the way this money is managed","cn":"（个人、组织、国家的）财力，财源，财务管理","g":"[plural]","lab":"informal","ex":{"en":"government/public/personal finances","cn":"政府／公共／个人财力"}},{"en":"to provide money for a project","cn":"提供资金","ex":{"en":"He took a job to finance his stay in Germany.","cn":"他找了一份工作以赚钱支付在德国逗留的费用。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给…提供资金;资助","en":"When someone finances something such as a project or a purchase, they provide the money that is needed to pay for them.","ex":{"en":"The fund has been used largely to finance the construction of federal prisons","cn":"该基金大部分用于了资助联邦监狱的建造。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"财政;金融","en":"Finance is the commercial or government activity of managing money, debt, credit, and investment.","ex":{"en":"...a major player in the world of high finance","cn":"高级金融界的大户"}},{"pos":"N-UNCOUNT 不可数名词","cn":"财力;财务状况(或管理)","en":"You can refer to the amount of money that you have and how well it is organized as your finances .","ex":{"en":"Be prepared for unexpected news concerning your finances","cn":"对财务上的意外状况要做到有备无患。"}}]},"examples":[{"en":"He took a job to finance his stay in Germany.","cn":"他找了一份工作以赚钱支付在德国逗留的费用。"},{"en":"the world of high finance (= finance involving large companies or countries)","cn":"高级金融界（关乎大公司或国家的金融）"}]},"fitting":{"oxford":{"phon":"ˈfɪtɪŋ","pos":"adjective","senses":[{"en":"suitable or right for the occasion","cn":"适合（某场合）的；恰当的","lab":"formal","ex":{"en":"The award was a fitting tribute to her years of devoted work.","cn":"这个奖项是对她多年全心全意工作的恰如其分的褒奖。"}},{"en":"having a particular fit","cn":"合身的；合适的","ex":{"en":"a tight-fitting dress","cn":"贴身的连衣裙"}},{"en":"a small part on a piece of equipment or furniture","cn":"（设备或家具的）小配件，附件","g":"[usually plural]","ex":{"en":"light fittings","cn":"灯具配件"},"pos":"noun"},{"en":"items in a house such as a cooker, lights or shelves that are usually fixed but that you can take with you when you move to a new house","cn":"可拆除装置，附加设备（如煤气灶、灯、搁架）","g":"[usually plural]","lab":"British English","ex":{"en":"The room still has the original fixtures and fittings.","cn":"这个房间还留着当初的固定装置和附加设备。"},"pos":"noun"},{"en":"an occasion when you try on a piece of clothing that is being made for you to see if it fits","cn":"试衣","ex":{"en":"to have a fitting for a wedding dress","cn":"试穿婚纱"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(设备、家具等的)小配件，附件，零件","en":"A fitting is one of the smaller parts on the outside of a piece of equipment or furniture, for example a handle or a tap.","ex":{"en":"...brass light fittings.","cn":"黄铜灯具配件"}},{"pos":"N-PLURAL 复数名词","cn":"可拆除装置(如烤箱、加热器等)","en":"Fittings are things such as ovens or heaters, that are fitted inside a building, but can be removed if necessary."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恰好的;恰当的;合适的","en":"Something that is fitting is right or suitable.","ex":{"en":"A solitary man, it was perhaps fitting that he should have died alone","cn":"他是个离群索居的人，孤独地死去也许正得其所。"}},{"pos":"N-COUNT 可数名词","cn":"试穿;试衣","en":"If someone has a fitting, they try on a piece of clothing that is being made for them to see if it fits.","ex":{"en":"She lunched and shopped and went for fittings for clothes she didn't need.","cn":"她吃完午饭后去购物,试穿了一些她并不需要的衣服。"}}]},"media":{"uk":"media/uk/fitting__gb_1.mp3","us":"media/us/fitting__us_1.mp3"},"examples":[{"en":"It is fitting that the new centre for European studies should be in a university that teaches every European language.","cn":"新的欧洲研究中心应设在教授各种欧洲语言的大学里才合适。"},{"en":"The award was a fitting tribute to her years of devoted work.","cn":"这个奖项是对她多年全心全意工作的恰如其分的褒奖。"}],"base":"fit"},"finely":{"oxford":{"phon":"ˈfaɪnli","pos":"adverb","senses":[{"en":"into very small grains or pieces","cn":"成颗粒；细微地；细小地","ex":{"en":"finely chopped herbs","cn":"剁得很细的香草"}},{"en":"in a beautiful or impressive way","cn":"华丽地；优雅地","ex":{"en":"a finely furnished room","cn":"陈设雅致的房间"}},{"en":"in a very careful or exact way","cn":"精致地；精巧地；精确地","ex":{"en":"a finely tuned engine","cn":"精确调整过的发动机"}}]},"media":{"uk":"media/uk/finely__gb_1.mp3","us":"media/us/finely__us_1.mp3"},"examples":[{"en":"The match was finely balanced throughout.","cn":"比赛自始至终不分上下。"},{"en":"a finely tuned engine","cn":"精确调整的发动机"}]},"fisherman":{"oxford":{"phon":"ˈfɪʃəmən","pos":"noun","senses":[{"en":"a person who catches fish, either as a job or as a sport","cn":"渔民；钓鱼爱好者","ex":{"en":"A keen fly-fisherman caught a record-sized salmon.","cn":"一名用假蝇钓鱼的钓鱼爱好者捕到一条创纪录的大鲑鱼。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"渔民;渔夫;垂钓者","en":"A fisherman is a person who catches fish as a job or for sport."}]},"media":{"uk":"media/uk/fisherman__gb_1.mp3","us":"media/us/fisherman__us_1.mp3"}},"fickleness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to keep changing your mind about what you believe or what you are going to do, especially when you have two choices and you cannot decide which one is best","cn":""},{"en":"someone who is fickle is always changing their mind about the people or things that they like so you cannot depend on them","cn":""}]},"examples":[{"en":"an unpredictable and fickle lover","cn":"","src":"ld"}],"media":{"uk":"media/uk/fickleness__gb_1.mp3","us":"media/us/fickleness__us_1.mp3"},"oxford":{"phon":"ˈfɪklnəs","pos":"noun","senses":[{"en":"the fact of changing often and suddenly","cn":"易变的；无常的","ex":{"en":"the fickleness of the English climate","cn":"英格兰气候的多变"}},{"en":"the fact of often changing your mind in an unreasonable way so that people cannot rely on you","cn":"反复无常的","ex":{"en":"the fickleness of young lovers","cn":"年轻恋人的善变"}}]}},"fireplace":{"oxford":{"phon":"ˈfaɪəpleɪs","pos":"noun","senses":[{"en":"an open space for a fire in the wall of a room","cn":"壁炉","ex":{"en":"A log fire crackled in the fireplace.","cn":"一节原木在壁炉里烧得劈啪作响。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壁炉;火炉","en":"In a room, the fireplace is the place where a fire can be lit and the area on the wall and floor surrounding this place."}]},"media":{"uk":"media/uk/fireplace__gb_1.mp3","us":"media/us/fireplace__us_1.mp3","img":["media/ldoce/img/fireplace.jpg"]}},"filled":{"lemma":"fill"},"finishes":{"lemma":"finish"},"films":{"lemma":"film"},"finishing":{"lemma":"finish"},"fingers":{"lemma":"finger"},"figures":{"lemma":"figure"},"fished":{"lemma":"fish"},"firms":{"lemma":"firm"},"finds":{"lemma":"find"},"findings":{"lemma":"find"},"fields":{"lemma":"field"},"figuring":{"lemma":"figure"},"fifths":{"lemma":"fifth"},"fishy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(味道或气味)鱼腥味的，鱼味的","en":"A fishy taste or smell reminds you of fish."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可疑的;有鬼的","en":"If you describe a situation as fishy, you feel that someone is not telling the truth or behaving completely honestly.","ex":{"en":"There seems to be something fishy going on.","cn":"事情好像有点不对劲。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is fishy or sounds fishy makes you suspect that something bad or dishonest is being done","cn":""},{"en":"shady deals and other activities seem to have something dishonest or illegal about them. A shady person is someone who seems likely to be involved in dishonest or illegal activities","cn":""},{"en":"seeming bad or dishonest","cn":"可疑的﹐靠不住的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Anything fishy smells, tastes, or resembles a fish in some way. Suspicious people and situations are also called fishy . Since this word has two meanings, context is key."}]},"collocations":{"phrases":["VERBS be, look, seem, smell, sound It all sounds very fishy to me.","ADV. very | definitely, distinctly | a bit","PHRASES something fishy There was definitely something fishy going on."]},"media":{"uk":"media/ldoce/hwd/bre/7/fishy0205.mp3","us":"media/ldoce/hwd/ame/2/fishy.mp3"},"examples":[{"en":"There's something fishy going on here.","cn":"这儿有点不大对头。"},{"en":"What's that fishy smell?","cn":"那是什么腥味？"}],"oxford":{"phon":"ˈfɪʃi","pos":"adjective","senses":[{"en":"seeming or likely to be wrong, illegal or dishonest","cn":"可疑的；有问题的；不正当的","lab":"informal","ex":{"en":"There's something fishy going on here.","cn":"这儿有点不大对头。"}},{"en":"smelling or tasting like a fish","cn":"（像）鱼味的；有鱼腥味的","ex":{"en":"What's that fishy smell?","cn":"那是什么腥味？"}}]}},"fieldwork":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"实地考察;现场调查","en":"Fieldwork is the gathering of information about something in a real, natural environment, rather than in a place of study such as a laboratory or classroom.","ex":{"en":"...anthropological fieldwork.","cn":"人类学实地考察"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of scientific or social subjects, done outside the class or laboratory 〔","cn":"科学或社会研究的〕实地考察﹐野外考察"}]},"collocations":{"phrases":["ADJ. extensive, intensive | detailed","VERB + FIELDWORK be engaged in, carry out, conduct, do, participate in, undertake","FIELDWORK + NOUN student","PREP. during/in the course of ~ evidence obtained during fieldwork | ~ on extensive fieldwork on chimpanzees"]},"media":{"uk":"media/ldoce/hwd/bre/4/fieldwork_las2_br.mp3","us":"media/ldoce/hwd/ame/7/fieldwork.mp3"},"oxford":{"phon":"ˈfiːldwɜːk","pos":"noun","senses":[{"en":"research or study that is done in the real world rather than in a library or laboratory","cn":"实地研究；野外考察","ex":{"en":"Most of the fieldwork was carried out in Italy.","cn":"大部分实地考察是在意大利进行的。"}}]}},"fickle":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"变化无常的;善变的","en":"If you describe someone as fickle, you disapprove of them because they keep changing their mind about what they like or want.","ex":{"en":"The group has been notoriously fickle in the past.","cn":"这伙人过去一直是出了名的善变。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无常的;靠不住的","en":"If you say that something is fickle, you mean that it often changes and is unreliable.","ex":{"en":"Orta's weather can be fickle.","cn":"奥尔塔的天气变幻莫测。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to keep changing your mind about what you believe or what you are going to do, especially when you have two choices and you cannot decide which one is best","cn":""},{"en":"someone who is fickle is always changing their mind about the people or things that they like so you cannot depend on them","cn":""},{"en":"if someone blows hot and cold about something, they keep changing their attitude so that sometimes they are eager to do it and at other times they are unwilling","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"People who are fickle change their minds so much you can't rely on them. If your best friend suddenly decides that she doesn't like you one week, and then the next week she wants to hang out again, she's being fickle ."}]},"collocations":{"phrases":["VERBS be","ADV. very | a bit, rather | notoriously The television world was a notoriously fickle one."]},"media":{"uk":"media/ldoce/hwd/bre/9/fickle0205.mp3","us":"media/ldoce/hwd/ame/3/fickle.mp3"},"examples":[{"en":"The weather here is notoriously fickle.","cn":"这里的天气出了名的变化无常。"},{"en":"the fickleness of the English climate","cn":"英国气候的变幻不定"}],"oxford":{"phon":"ˈfɪkl","pos":"adjective","senses":[{"en":"changing often and suddenly","cn":"易变的；无常的","ex":{"en":"The weather here is notoriously fickle.","cn":"这里的天气出了名的变化无常。"}},{"en":"often changing their mind in an unreasonable way so that you cannot rely on them","cn":"反复无常的","ex":{"en":"She had been a fickle friend, even at the best of times.","cn":"即便是在最好的时候，她作为朋友也不太靠得住。"}}]}},"firework":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"焰火;烟花","en":"Fireworks are small objects that are lit to entertain people on special occasions. They contain chemicals and burn brightly or attractively, often with a loud noise, when you light them.","ex":{"en":"Berlin people drank champagne, set off fireworks and tooted their car horns.","cn":"柏林市民喝香槟、放焰火、鸣车笛。"}},{"pos":"N-PLURAL 复数名词","cn":"焰火表演;焰火晚会","en":"You use fireworks to refer to an occasion on which fireworks are lit to entertain people.","ex":{"en":"On the night of the fireworks we had a really good spot.","cn":"观看焰火表演的那天晚上，我们找了一个非常好的位置。"}},{"pos":"N-PLURAL 复数名词","cn":"精彩难忘的演出(或作品)","en":"An exciting and impressive performance or piece of writing can be referred to as fireworks .","ex":{"en":"It is given a typically thoughtful production with just enough theatrical fireworks.","cn":"该剧在制作上一如既往地花费了心思，舞台演出效果也相当精彩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small container filled with powder that burns or explodes to produce coloured lights and noise in the sky","cn":"烟火﹐烟花"},{"en":"used to say that someone will be angry","cn":"怒火"},{"en":"something that is exciting or impressive","cn":"亮点〔令人兴奋或赞叹之物〕"}]},"collocations":{"phrases":["VERB + FIREWORK light Be very careful when lighting fireworks. | let off, set off They set off fireworks in their back garden.","FIREWORK + VERB explode, go off","FIREWORK + NOUN display, show"]},"media":{"uk":"media/ldoce/hwd/bre/3/firework0205.mp3","us":"media/ldoce/hwd/ame/9/amelasdefirework.mp3"},"examples":[{"en":"There'll be fireworks when he finds out!","cn":"他要是发觉了就会大发雷霆！"},{"en":"When do the fireworks start?","cn":"什么时候开始放烟火？"}],"oxford":{"phon":"ˈfaɪəwɜːk","pos":"noun","senses":[{"en":"a small device containing powder that burns or explodes and produces bright coloured lights and loud noises, used especially at celebrations","cn":"烟火；烟花","g":"[countable]","lab":"British English","ex":{"en":"to let off a few fireworks","cn":"放几个烟火"}},{"en":"a display of fireworks","cn":"烟火表演；烟花表演；放烟火","g":"[plural]","ex":{"en":"When do the fireworks start?","cn":"什么时候开始放烟火？"}},{"en":"strong or angry words; exciting actions","cn":"激烈的言辞；愤怒的话语；令人激动的行动","g":"[plural]","lab":"informal","ex":{"en":"There'll be fireworks when he finds out!","cn":"他要是发觉了就会大发雷霆！"}}]}},"fillet":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指牛肉)无骨肉片","en":"Fillet is a strip of meat, especially beef, that has no bones in it.","ex":{"en":"...fillet of beef with shallots.","cn":"葱香无骨牛肉片"}},{"pos":"N-COUNT 可数名词","cn":"去骨鱼片","en":"A fillet of fish is the side of a fish with the bones removed.","ex":{"en":"...anchovy fillets","cn":"去骨鳀鱼片"}},{"pos":"VERB 动词","cn":"剔除(鱼或肉)的骨头","en":"When you fillet fish or meat, you prepare it by taking the bones out.","ex":{"en":"Don't be afraid to ask your fishmonger to fillet flat fish.","cn":"尽管叫鱼贩子把比目鱼的鱼刺剔掉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of meat or fish without bones 〔","cn":"去骨的〕肉片﹐鱼片"},{"en":"to remove the bones from a piece of meat or fish","cn":"剔除〔肉或鱼〕的骨头"}]},"collocations":{"phrases":["ADJ. anchovy, cod, haddock, salmon, etc. | beef, pork","FILLET + NOUN steak","PREP. ~ of fillet of beef with a red wine sauce •"]},"media":{"uk":"media/ldoce/hwd/bre/6/fillet_n0205.mp3","us":"media/ldoce/hwd/ame/f/fillet1.mp3"},"examples":[{"en":"a fillet of cod","cn":"一片鳕鱼片"},{"en":"fillet steak","cn":"无骨牛排"}],"oxford":{"phon":"ˈfɪlɪt","pos":"noun","senses":[{"en":"a piece of meat or fish that has no bones in it","cn":"无骨肉片；去骨鱼片","ex":{"en":"plaice fillets","cn":"鲽鱼片"}},{"en":"to remove the bones from a piece of fish or meat; to cut fish or meat into fillets","cn":"剔去（鱼或肉）的骨头；把（鱼或肉）切成片","pos":"verb"}]}},"fixture":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(房间等建筑物内的)固定装置，固定设施","en":"Fixtures are pieces of furniture or equipment, for example baths and sinks, which are fixed inside a house or other building and which stay there if you move.","ex":{"en":"...a detailed list of what fixtures and fittings are included in the purchase price.","cn":"房屋购买价中包括的固定装置及设备的详细清单"}},{"pos":"N-COUNT 可数名词","cn":"(定期举行的)体育活动，体育赛事","en":"A fixture is a sports event which takes place on a particular date.","ex":{"en":"City won this fixture 3-0 last season.","cn":"上个赛季曼城队在该项赛事中以3比0获胜。"}},{"pos":"N-COUNT 可数名词","cn":"(…的)常客;(…的)固定事物","en":"If you describe someone or something as a fixture in a particular place or occasion, you mean that they always seem to be there.","ex":{"en":"She was a fixture in New York's nightclubs","cn":"她是纽约夜总会的常客。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sports match that has been arranged for a particular time and place 〔","cn":"预定举行的〕体育比赛"},{"en":"a piece of equipment that is fixed inside a house or building and is sold as part of the house 〔","cn":"房屋或建筑物内的〕固定设备﹐固定装置"},{"en":"to be always present and not likely to move or go away","cn":"是固定存在物﹔是固定成员"}]},"collocations":{"phrases":["ADJ. important, major | difficult | away, home | annual, regular | opening | final | international | friendly | league | sporting","VERB + FIXTURE play playing an important fixture this evening | fulfil The club was fined for not fulfilling its fixtures at the weekend. | ","FIXTURE + NOUN list a full fixture list of friendly matches","PREP. ~ against a home fixture against Leeds 2 sth fixed in a house","ADJ. original an exceptional example of Victorian architecture with the original fixtures and fittings intact | permanent (often figurative)","PHRASES fixtures and fittings"]},"media":{"uk":"media/ldoce/hwd/bre/8/fixture0205.mp3","us":"media/ldoce/hwd/ame/7/fixture.mp3"},"examples":[{"en":"( figurative ) He has stayed with us so long he seems to have become a permanent fixture.","cn":"他在我们这里待了很久，好像成了我们的固定成员。"},{"en":"( BrE ) The price of the house includes fixtures and fittings.","cn":"房屋价格包括固定装置和附加设备。"}],"oxford":{"phon":"ˈfɪkstʃə(r)","pos":"noun","senses":[{"en":"a sports event that has been arranged to take place on a particular date and at a particular place","cn":"（定期定点举行的）体育活动，体育节","lab":"British English","ex":{"en":"There are plans to make the race an annual fixture.","cn":"已有计划使该赛事成为一年一度的体育活动。"}},{"en":"a thing such as a bath or toilet that is fixed in a house and that you do not take with you when you move house","cn":"固定设施（如房屋内安装的浴缸或抽水马桶）","lab":"British English","ex":{"en":"The price of the house includes fixtures and fittings.","cn":"房屋价格包括固定装置和附加设备。"}}]}},"finale":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(演出的)终场，最后一幕;(音乐的)终曲，末乐章;(一系列演出)最后一场","en":"The finale of a show, piece of music, or series of shows is the last part of it or the last one of them, especially when this is exciting or impressive.","ex":{"en":"... the finale of Shostakovich's Fifth Symphony","cn":"肖斯塔科维奇第五交响曲的末乐章"}},{"pos":"N-COUNT 可数名词","cn":"(特定的)结尾，结束","en":"If you say that an event provides a particular kind of finale to something, you mean that it provides it with a particular kind of ending.","ex":{"en":"...the dramatic finale to America's seven-year hostage crisis","cn":"历时7年的美国人质危机的戏剧性结局"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the last part of a book, film, show etc","cn":""},{"en":"the way a story or film ends","cn":""},{"en":"the exciting or impressive last part of a piece of music, show, ceremony etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you decide to leave the theater early to beat traffic, you’ll miss the finale — the exciting final part of a theatrical performance."}]},"collocations":{"phrases":["ADJ. dramatic, exciting, grand, rousing, thrilling The evening ended with a grand finale of fireworks and music. | fitting","VERB + FINALE end in/with, have, reach The match had a thrilling finale, with three goals scored in the last five minutes. | provide This vi","PREP. ~ to a rousing finale to an evening of enthralling music"]},"media":{"uk":"media/ldoce/hwd/bre/0/finale0205.mp3","us":"media/ldoce/hwd/ame/3/laadfinale.mp3"},"examples":[{"en":"The festival ended with a grand finale in Hyde Park.","cn":"节日的压轴活动是在海德公园举行的盛大演出。"},{"en":"the rousing finale of Beethoven's Ninth Symphony","cn":"贝多芬第九交响曲激动人心的末乐章"}],"oxford":{"phon":"fɪˈnɑːli","pos":"noun","senses":[{"en":"the last part of a show or a piece of music","cn":"（演出的）终场，结局；（音乐的）终曲，末乐章","ex":{"en":"the rousing finale of Beethoven’s Ninth Symphony","cn":"贝多芬《第九交响曲》激动人心的末乐章"}},{"en":"an ending to something of the type mentioned","cn":"结尾","ex":{"en":"It was a fitting finale to the day's events.","cn":"当天的活动至此顺利结束。"}}]}},"fictitious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"虚幻的;子虚乌有的","en":"Fictitious is used to describe something that is false or does not exist, although some people claim that it is true or exists.","ex":{"en":"We're interested in the source of these fictitious rumours.","cn":"我们对这些子虚乌有的谣言从何而来很感兴趣。"}},{"pos":"ADJ 形容词","cn":"虚构的;小说的","en":"A fictitious character, thing, or event occurs in a story, play, or film but never really existed or happened.","ex":{"en":"The persons and events portrayed in this production are fictitious.","cn":"这部作品中描述的人物和事件均属虚构。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not true, or not real","cn":"虚构的﹐杜撰的﹔捏造的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Fictitious means made up, or imaginary. No matter how real Scarlett O'Hara might seem in \"Gone With the Wind,\" she's a fictitious character invented by author Margaret Mitchell."}]},"collocations":{"phrases":["VERBS be His story is wholly fictitious.","ADV. entirely, purely, totally, wholly | largely"]},"media":{"uk":"media/ldoce/hwd/bre/b/fictitious0205.mp3","us":"media/ldoce/hwd/ame/c/fictitious.mp3"},"examples":[{"en":"All the places and characters in my novel are fictitious (= they do not exist in real life).","cn":"我小说中的人物地点纯属虚构。"},{"en":"a fictitious address","cn":"杜撰的地址"}],"oxford":{"phon":"fɪkˈtɪʃəs","pos":"adjective","senses":[{"en":"invented by somebody rather than true","cn":"虚构的；虚假的","ex":{"en":"All the places and characters in my novel are fictitious (= they do not exist in real life).","cn":"我小说中的人物和地点纯属虚构。"}}]}},"fingernail":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手指甲","en":"Your fingernails are the thin hard areas at the end of each of your fingers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the hard flat part that covers the top end of your finger","cn":"手指甲"}]},"collocations":{"phrases":["ADJ. long | black, dirty | broken, torn | manicured, well-manicured | painted, red, scarlet","VERB + FINGERNAIL cut, manicure, polish | bite, chew | break, tear | dig in She dug her fingernails into my neck. | drag, draw, rake, scrape","FINGERNAIL + VERB dig in","PREP. under the/your ~s I noticed I had dirt under my fingernails."]},"media":{"img":["media/ldoce/img/hand.jpg"],"uk":"media/ldoce/hwd/bre/f/fingernail0205.mp3","us":"media/ldoce/hwd/ame/9/fingernail.mp3"},"oxford":{"phon":"ˈfɪŋɡəneɪl","pos":"noun","senses":[{"en":"the thin hard layer that covers the outer tip of each finger","cn":"指甲"}]}},"fictional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"虚构的;非真实的","en":"Fictional characters or events occur only in stories, plays, or films and never actually existed or happened.","ex":{"en":"It is drama featuring fictional characters","cn":"这部戏剧中的人物是虚构的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"fictional people, events etc are imaginary and from a book or story","cn":"虚构的﹐编造的﹐小说（中）的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Something fictional has been invented, most likely for a book, play, or movie. But if you're really self-centered, you might think a fictional story is actually about you."}]},"collocations":{"phrases":["VERBS be The names of the shops are entirely fictional.","ADV. entirely, purely, wholly"]},"media":{"uk":"media/ldoce/hwd/bre/1/fictional0205.mp3","us":"media/ldoce/hwd/ame/f/fictional.mp3"},"examples":[{"en":"a fictional account of life on a desert island","cn":"对荒岛生活的虚构描述"},{"en":"fictional characters","cn":"虚构的人物"}],"oxford":{"phon":"ˈfɪkʃənl","pos":"adjective","senses":[{"en":"not real or true; existing only in stories; connected with fiction","cn":"虚构的；小说（中）的","ex":{"en":"fictional characters","cn":"虚构的人物"}}]}},"fifty-fifty":{"collins":{"senses":[{"pos":"ADV 副词","cn":"对半;各半;均(分)地","en":"If something such as money or property is divided or shared fifty-fifty between two people, each person gets half of it.","ex":{"en":"The proceeds of the sale are split fifty-fifty.","cn":"出售的收益双方平分。"}},{"pos":"ADJ 形容词","cn":"(发生概率)一半一半的，百分之五十的","en":"If there is a fifty-fifty chance of something happening, it is equally likely to happen as it is not to happen.","ex":{"en":"You've got a fifty-fifty chance of being right.","cn":"你有 50％的可能性是对的。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if you say that something such as a game or a decision could go either way , you mean that either of two results is equally possible","cn":""},{"en":"a borderline case is a situation in which the decision is not certain, for example about whether someone should pass an exam, get a job etc","cn":""},{"en":"if you say there is a fifty-fifty chance of something happening, you mean there is an equal chance of it happening or not happening","cn":""}]},"collocations":{"phrases":["VERBS be | divide sth, go, split sth We'll divide the profit fifty-fifty. We went fifty-fifty on the meal.","ADV. about, roughly The chances of reaching the survivors in time are about fifty-fifty."]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41fifty-fifty.mp3","us":"media/ldoce/hwd/ame/c/ld41fifty-fifty.mp3"},"examples":[{"en":"She has a fifty-fifty chance of winning (= an equal chance of winning or losing).","cn":"她获胜的可能性是百分之五十。"},{"en":"Costs are to be shared on a fifty-fifty basis between the government and local businesses.","cn":"费用由政府和当地企业均摊。"}],"oxford":{"phon":"ˌfɪfti ˈfɪfti","pos":"adjective, adverb","senses":[{"en":"divided equally between two people, groups or possibilities","cn":"对半（的）；各半（的）；平分（的）；二一添作五","ex":{"en":"Costs are to be shared on a fifty-fifty basis between the government and local businesses.","cn":"费用由政府和当地企业均摊。"}}]}},"fidget":{"collins":{"senses":[{"pos":"VERB 动词","cn":"坐立不安;烦躁","en":"If you fidget, you keep moving your hands or feet slightly or changing your position slightly, for example because you are nervous, bored, or excited.","ex":{"en":"Brenda fidgeted in her seat.","cn":"布伦达在座位上烦躁不安。"}},{"pos":"VERB 动词","cn":"(由于紧张或无聊)摆弄，拨弄","en":"If you fidget with something, you keep moving it or touching it with your fingers with small movements, for example because you are nervous or bored.","ex":{"en":"He fidgeted with his tie","cn":"他摆弄着领带。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To fidget is to make little movements with your hands and feet. Even if you're nervous during your job interview, try not to fidget ."}]},"collocations":{"phrases":["ADV. nervously","PREP. with She was fidgeting nervously with her pen."]},"media":{"uk":"media/ldoce/hwd/bre/d/fidget_n0205.mp3","us":"media/ldoce/hwd/ame/5/fidget1.mp3"},"examples":[{"en":"Sit still and stop fidgeting!","cn":"坐好，不要动来晃去的！"},{"en":"The kids had started to fidget.","cn":"孩子们开始坐立不安起来。"}],"oxford":{"phon":"ˈfɪdʒɪt","pos":"verb","senses":[{"en":"to keep moving your body, your hands or your feet because you are nervous, bored, excited, etc.","cn":"坐立不安；烦躁","ex":{"en":"Sit still and stop fidgeting!","cn":"坐好，不要动来晃去的！"}},{"en":"a person who is always fidgeting","cn":"坐立不安的人","ex":{"en":"You’re such a fidget!","cn":"你真是个坐不住的人！"},"pos":"noun"}]}},"fib":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小谎;无伤大雅的谎话","en":"A fib is a small, unimportant lie.","ex":{"en":"She told innocent fibs like anyone else.","cn":"她也像别人一样，说些无伤大雅的谎话。"}},{"pos":"VERB 动词","cn":"说谎;撒谎;说假话","en":"If someone is fibbing, they are telling lies.","ex":{"en":"He laughs loudly when I accuse him of fibbing.","cn":"当我指责他说谎时，他大笑起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or write that you know is untrue","cn":""},{"en":"a lie that you tell to avoid upsetting someone","cn":""},{"en":"a lie, especially about something that is not very important – used especially by children","cn":""}]},"collocations":{"phrases":["VERB + FIB tell Don't tell fibs !"]},"media":{"uk":"media/ldoce/hwd/bre/e/fib_v0205.mp3","us":"media/ldoce/hwd/ame/1/fib.mp3"},"examples":[{"en":"Come on, don't fib! Where were you really last night?","cn":"得了吧，不要撒谎了！昨夜你到底在哪儿？"},{"en":"Stop telling fibs.","cn":"别再撒谎了。"}],"oxford":{"phon":"fɪb","pos":"noun","senses":[{"en":"a lie, usually one that is not important","cn":"谎言；（无关紧要的）小谎；瞎话","ex":{"en":"Stop telling fibs.","cn":"别再撒谎了。"}},{"en":"to tell a lie, usually about something that is not important","cn":"撒谎；说瞎话","ex":{"en":"Come on, don't fib! Where were you really last night?","cn":"得了吧，不要撒谎了！昨夜你到底在哪儿？"},"pos":"verb"}]}},"filthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肮脏的;污秽的","en":"Something that is filthy is very dirty indeed.","ex":{"en":"He never washed, and always wore a filthy old jacket.","cn":"他总是穿着一件从来不洗的脏兮兮的旧夹克。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卑劣的;淫秽的;猥亵的","en":"If you describe something as filthy, you mean that you think it is morally very unpleasant and disgusting, sometimes in a sexual way.","ex":{"en":"Apparently, well known actors were at these filthy parties","cn":"听说有些知名演员也参加了这些下流的聚会。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)阴冷潮湿的，恶劣的","en":"Filthy weather is very cold, wet, and windy.","ex":{"en":"...a filthy wet night.","cn":"糟糕的雨夜"}},{"pos":"","cn":"","en":"filthy rich→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not clean","cn":""},{"en":"very dirty","cn":"十分肮脏的﹐污秽的"},{"en":"covered with mud","cn":""}]},"vocab":{"pos":"1 adj 2 adj 3 adj","senses":[{"en":"Filthy is a dirty word. Sure, you can say it aloud in public, but it means \"dirty\" — like your dirty laundry pile by the end of the week."}]},"collocations":{"phrases":["VERBS be, feel, look, smell | get | leave sth, make sth He always leaves the bath absolutely filthy!","ADV. really | absolutely, completely | pretty"]},"media":{"uk":"media/ldoce/hwd/bre/2/filthy_adv0205.mp3","us":"media/ldoce/hwd/ame/8/filthy.mp3"},"examples":[{"en":"Isn't it a filthy day?","cn":"今天可不是又冷又湿吗？"},{"en":"Ann gave him a filthy look.","cn":"安气愤地瞧了他一眼。"}],"oxford":{"phon":"ˈfɪlθi","pos":"adjective","senses":[{"en":"very dirty and unpleasant","cn":"肮脏的；污秽的","ex":{"en":"filthy rags/streets","cn":"肮脏的破布／街道"}},{"en":"very rude and offensive and usually connected with sex","cn":"下流的；淫秽的；猥亵的","ex":{"en":"filthy language/words","cn":"下流的语言／言辞"}},{"en":"showing anger","cn":"气愤的","lab":"informal","ex":{"en":"He was in a filthy mood.","cn":"他气愤不已。"}},{"en":"cold and wet","cn":"寒冷潮湿的；恶劣的；糟糕的","lab":"British English, informal，，","ex":{"en":"Isn't it a filthy day?","cn":"今天可不是又冷又湿吗？"}},{"en":"extremely dirty","cn":"极其肮脏的","pos":"adverb"},{"en":"extremely rich, especially in a way that you find offensive because it is too much","cn":"富得流油的","pos":"adverb"}]}},"firearm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火器;枪支","en":"Firearms are guns.","ex":{"en":"He was also charged with illegal possession of firearms","cn":"他还被控非法持有枪支。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a gun","cn":"火器﹐枪"}]},"collocations":{"phrases":["ADJ. imitation, replica | unlicensed","VERB + FIREARM be in possession of, possess The police charged her with possessing a firearm with intent to endanger life. | carry","FIREARM + NOUN training | expert | certificate, licence | offence He is wanted for robbery and firearms offences."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdefirearm.mp3","us":"media/ldoce/hwd/ame/4/firearm.mp3"},"examples":[{"en":"The police were issued with firearms.","cn":"警察都配发了小型枪支。"},{"en":"He was charged with illegal possession of a firearm.","cn":"他被控非法持有火器。"}],"oxford":{"phon":"ˈfaɪərɑːm","pos":"noun","senses":[{"en":"a gun that can be carried","cn":"（便携式的）枪","ex":{"en":"The police were issued with firearms.","cn":"警察都配发了小型枪支。"}}]}},"fingerprint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指纹;指印","en":"Fingerprints are marks made by a person's fingers which show the lines on the skin. Everyone's fingerprints are different, so they can be used to identify criminals.","ex":{"en":"The detective discovered no fewer than 35 fingerprints.","cn":"那位侦探发现了至少35个指纹。"}},{"pos":"VERB 动词","cn":"提取…的指纹","en":"If someone is fingerprinted, the police take their fingerprints.","ex":{"en":"He took her to jail, where she was fingerprinted and booked.","cn":"他把她带到监狱，在那里对她提取了指纹并进行了登记。"}},{"pos":"VERB 动词","cn":"提取在…上的指纹","en":"If the police fingerprint an object, they put a layer of special dust on it so that any fingerprints that are on it can be seen.","ex":{"en":"Let's fingerprint the canoe, see if we come up with anything.","cn":"让我们提取一下独木舟上的指纹，看看能不能有什么发现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dirty area on something that spoils its appearance","cn":""},{"en":"a small mark on something","cn":""},{"en":"a mark that is difficult to remove, especially one made by a dark liquid","cn":""}]},"collocations":{"phrases":["QUANT. set The police were able to obtain a set of fingerprints from the suspect.","VERB + FINGERPRINT leave She was careful not to leave any fingerprints. | check (sth) for, dust sth for, examine sth for, look for The car i"]},"media":{"uk":"media/ldoce/hwd/bre/2/fingerprint0205.mp3","us":"media/ldoce/hwd/ame/f/fingerprint1.mp3"},"examples":[{"en":"His fingerprints were all over the gun.","cn":"枪上到处是他的指纹。"},{"en":"He was careful not to leave any fingerprints .","cn":"他小心地不留下指纹。"}],"oxford":{"phon":"ˈfɪŋɡəprɪnt","pos":"noun","senses":[{"en":"a mark made by the pattern of lines on the tip of a person’s finger, often used by the police to identify criminals","cn":"指纹；指印","ex":{"en":"His fingerprints were all over the gun.","cn":"那把枪上布满了他的指纹。"}},{"en":"to make a record of somebody's fingerprints, often because they are suspected of committing a crime","cn":"指纹；指印","ex":{"en":"I was booked, fingerprinted and locked up for the night.","cn":"我被立案审查，录了指纹并关了一夜。"},"pos":"verb"}]}},"fidelity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对人、组织或信仰的)忠诚，忠实","en":"Fidelity is loyalty to a person, organization, or set of beliefs.","ex":{"en":"I had to promise fidelity to the Queen.","cn":"我必须承诺效忠女王。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对配偶或伴侣的)忠贞，忠诚","en":"Fidelity is being loyal to your husband, wife, or partner by not having a sexual relationship with anyone else.","ex":{"en":"Wanting fidelity implies you're thinking about a major relationship.","cn":"要求忠诚意味着你想发展一段严肃认真的恋爱关系。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(报告或翻译的)准确度，精确度，确切度","en":"The fidelity of something such as a report or translation is the degree to which it is accurate.","ex":{"en":"...the fidelity of these early documents.","cn":"这些早期文件的准确性"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you are loyal to your husband, girlfriend etc, by not having sex with anyone else 〔","cn":"对丈夫﹑女友等的〕忠诚﹐忠贞﹐忠实"},{"en":"when you are loyal to a person, an organization, or something that you believe in 〔","cn":"对组织﹑信仰等的〕忠诚﹐忠实"},{"en":"how much a film, a piece of written work etc remains unchanged from an earlier piece of work, or the facts that are known 〔","cn":"影片﹑文字作品等对原作或事实的〕忠实性"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Fidelity is the quality of being faithful or loyal. Dogs are famous for their fidelity ."}]},"collocations":{"phrases":["ADJ. great | absolute | marital","PREP. with ~ telling the story with great fidelity to the original | ~ to They swore an oath of fidelity to their king."]},"media":{"uk":"media/ldoce/hwd/bre/a/fidelity0205.mp3","us":"media/ldoce/hwd/ame/d/fidelity.mp3"},"examples":[{"en":"the fidelity of the translation to the original text","cn":"对原文翻译的准确性"},{"en":"fidelity to your principles","cn":"对原则的忠诚不移"}],"oxford":{"phon":"fɪˈdeləti","pos":"noun","senses":[{"en":"the quality of being loyal to somebody/something","cn":"忠诚；忠实；忠贞","lab":"formal","ex":{"en":"fidelity to your principles","cn":"对原则的忠诚不移"}},{"en":"the quality of being faithful to your husband, wife or partner by not having a sexual relationship with anyone else","cn":"（对丈夫、妻子或性伴侣的）忠贞，忠实，忠诚","ex":{"en":"marital/sexual fidelity","cn":"婚姻／性的忠贞"}},{"en":"the quality of being accurate","cn":"准确性；精确性","lab":"formal","ex":{"en":"the fidelity of the translation to the original text","cn":"对原文翻译的准确性"}}]}}});
